window.LESSONS_META={"1":{"title":"Fundamentos de la hiperautomatización","kick":"Episodio 01 · Fundamentos · Lección completa"},"2":{"title":"Introducción a los agentes inteligentes y la IA generativa","kick":"Episodio 02 · IA Generativa · Lección completa"},"3":{"title":"Prompt engineering para agentes","kick":"Episodio 03 · Prompting · Lección completa"},"4":{"title":"Herramientas de inteligencia artificial generativa","kick":"Episodio 04 · IA Generativa · Lección completa"},"5":{"title":"Creación de agentes con n8n","kick":"Episodio 05 · No-code · Lección completa"},"6":{"title":"Creación de agentes con Make","kick":"Episodio 06 · No-code · Lección completa"},"7":{"title":"Automatización y vibe coding con Claude","kick":"Episodio 07 · IA + Código · Lección completa"},"8":{"title":"Levantamiento de procesos y detección de oportunidades","kick":"Episodio 08 · Análisis · Lección completa"},"9":{"title":"Diseño funcional de soluciones y ciclo de vida de proyectos","kick":"Episodio 09 · Metodología · Lección completa"},"10":{"title":"Diseño de procesos BPMN","kick":"Episodio 10 · Modelado · Lección completa"},"11":{"title":"Automatización con RPA","kick":"Episodio 11 · RPA · Lección completa"},"12":{"title":"Automatización documental, procesamiento de datos y web scraping","kick":"Episodio 12 · Datos · Lección completa"},"13":{"title":"Diseño de automatizaciones empresariales robustas y control de excepciones","kick":"Episodio 13 · Robustez · Lección completa"},"14":{"title":"Orquestación y despliegue de robots con UiPath Orchestrator","kick":"Episodio 14 · RPA · Lección completa"},"15":{"title":"Creación de aplicaciones low-code con PowerApps y Power Automate","kick":"Episodio 15 · Low-code · Lección completa"},"16":{"title":"Procesamiento inteligente de documentos y visión artificial","kick":"Episodio 16 · IA + Datos · Lección completa"},"17":{"title":"Integración de sistemas: APIs, webhooks y conectores empresariales","kick":"Episodio 17 · Integración · Lección completa"},"18":{"title":"Agentes conversacionales: automatización de chats y llamadas telefónicas","kick":"Episodio 18 · Agentes · Lección completa"},"19":{"title":"Interacción con avatares inteligentes","kick":"Episodio 19 · IA + Video · Lección completa"},"20":{"title":"Orquestación avanzada de procesos y agentes","kick":"Episodio 20 · Arquitectura · Lección completa"},"21":{"title":"Marco legal, normativo y de ciberseguridad en la automatización","kick":"Episodio 21 · Gobernanza · Lección completa"},"22":{"title":"Ética, transparencia y mitigación de riesgos en IA","kick":"Episodio 22 · Ética · Lección completa"}};
window.LESSONS={"1":[{"type":"title","dur":20,"eyeb":"Bienvenido","h2":"Todo equipo tiene un trabajo que alguien repite sin parar","sub":"Copiar datos, armar reportes, responder los mismos mensajes. Necesario, pero mecánico.","cap":"En todo equipo hay tareas que alguien repite una y otra vez: necesario, pero mecánico. Esta lección trata de cómo liberarte de eso.","narr":"Bienvenido a la primera lección. Empecemos por algo que seguramente reconoce: en todo equipo hay tareas que alguien repite una y otra vez. Copiar datos, armar reportes, responder los mismos mensajes. Trabajo necesario, pero mecánico. Esta lección trata de cómo liberarte de eso."},{"type":"list","dur":16,"eyeb":"Qué va a aprender","h2":"Tres cosas, en pocos minutos","items":[["1","Qué es la hiperautomatización","y en qué se diferencia de automatizar"],["2","Qué es un flujo","y de qué cuatro piezas está hecho"],["3","Un flujo real","funcionando, paso a paso"]],"cap":"En esta lección: qué es la hiperautomatización, qué es un flujo y sus piezas, y un flujo real paso a paso.","narr":"En los próximos minutos vas a entender tres cosas: qué es realmente la hiperautomatización, qué es un flujo y de qué está hecho, y cómo se ve un flujo funcionando en un caso real."},{"type":"compare","dur":19,"eyeb":"La distinción","h2":"Automatizar no es lo mismo que hiperautomatizar","colA":["Automatización","Una tarea suelta","Que una acción puntual ocurra sola, con reglas fijas. Ej.: enviar un correo automático."],"colB":["Hiperautomatización","Procesos completos + IA","Conectar varias tareas y sumarles inteligencia artificial, para resolver un proceso entero con criterio."],"cap":"Automatizar = una tarea suelta con reglas fijas. Hiperautomatizar = procesos completos conectados, con IA y criterio.","narr":"Primero, una distinción importante. Automatizar es hacer que una tarea puntual ocurra sola, con reglas fijas: por ejemplo, que un correo se envíe sin que lo escribas cada vez. La hiperautomatización va más allá: conecta varias de esas tareas y les suma inteligencia artificial, para que procesos enteros se resuelvan de principio a fin, con criterio, no solo con reglas rígidas."},{"type":"list","dur":16,"eyeb":"Por qué importa","h2":"No es moda: resuelve tres problemas reales","items":[["⏱","Recupera horas","El tiempo que hoy se va en tareas repetitivas"],["🎯","Menos errores","Se acaban las fallas de copiar y pegar a mano"],["📈","Escala sin más esfuerzo","Crece el trabajo, no su carga manual"]],"cap":"Importa por tres razones: recupera horas, reduce errores humanos y te deja escalar sin sumar trabajo manual.","narr":"¿Por qué molestarte con esto? Por tres razones muy concretas: recuperas horas que hoy se pierden en tareas repetitivas, reduces los errores humanos de copiar y pegar, y puedes crecer sin sumar más trabajo manual cada vez."},{"type":"define","dur":15,"eyeb":"El concepto central","h2":"Todo se construye sobre una idea: el flujo","def":"Un <b>flujo</b> es una secuencia de pasos que se ejecutan <b>solos</b>, en orden, para lograr un resultado — sin que intervengas.","cap":"Un flujo es una secuencia de pasos que se ejecutan solos, en orden, para lograr un resultado, sin que intervengas.","narr":"Toda hiperautomatización se construye sobre una idea simple: el flujo. Un flujo es una secuencia de pasos que se ejecutan solos, en orden, para lograr un resultado, sin que intervengas en el medio."},{"type":"pieces","dur":15,"eyeb":"La anatomía","h2":"Existen miles de flujos, pero todos tienen 4 piezas","pieces":[["⏰","Detonante","Qué lo activa"],["📊","Datos","De dónde saca"],["🤖","Criterio","Qué decide (IA)"],["📧","Resultado","Qué entrega"]],"cap":"Aunque existan miles de flujos distintos, todos comparten la misma anatomía: cuatro piezas.","narr":"Y aunque existan miles de flujos distintos, todos comparten la misma anatomía: cuatro piezas. Vamos a verlas una por una, porque entenderlas es entender el curso entero."},{"type":"spot","dur":15,"snum":"Pieza 1 de 4","sic":"⏰","stitle":"El detonante","stext":"Es lo que pone el flujo en marcha. Sin detonante, nada arranca.","sex":"Una hora · un correo que llega · un formulario enviado","cap":"Pieza 1: el detonante. Lo que pone el flujo en marcha: una hora, un correo, un formulario.","narr":"La primera pieza es el detonante: lo que pone el flujo en marcha. Puede ser una hora del día, un correo que llega, un formulario que alguien envía. Sin un detonante, el flujo nunca arranca."},{"type":"spot","dur":13,"snum":"Pieza 2 de 4","sic":"📊","stitle":"Los datos","stext":"De dónde toma la información con la que va a trabajar.","sex":"Una planilla · una base · un mensaje","cap":"Pieza 2: los datos. De dónde toma la información: una planilla, una base, un mensaje.","narr":"La segunda pieza son los datos: de dónde toma la información con la que va a trabajar. Una planilla, una base de datos, el contenido de un mensaje. El flujo va a buscarlos donde ya viven."},{"type":"spot","dur":16,"snum":"Pieza 3 de 4","sic":"🤖","stitle":"El criterio","stext":"Qué decide o transforma con esos datos. Aquí entra la inteligencia artificial.","sex":"Resume · clasifica · redacta · decide","cap":"Pieza 3: el criterio. Qué se decide o transforma. Aquí entra la IA: resume, clasifica, redacta.","narr":"La tercera pieza es el criterio: qué se decide o se transforma con esos datos. Y aquí es donde entra la inteligencia artificial. En lugar de reglas rígidas, la IA puede resumir, clasificar, redactar o decidir, adaptándose a cada caso."},{"type":"spot","dur":13,"snum":"Pieza 4 de 4","sic":"📧","stitle":"El resultado","stext":"Lo que el flujo finalmente entrega, ya terminado.","sex":"Un correo · un registro · una alerta","cap":"Pieza 4: el resultado. Lo que el flujo entrega, ya terminado: un correo, un registro, una alerta.","narr":"Y la cuarta pieza es el resultado: lo que el flujo finalmente entrega, ya terminado. Un correo enviado, un registro guardado, una alerta que salta. El objetivo por el que existe todo el flujo."},{"type":"flow","dur":19,"eyeb":"Ejemplo 1","h2":"El reporte del lunes, pieza por pieza","nodes":[["⏰","Detonante","Lunes 9:00"],["📊","Datos","Tu planilla"],["🤖","Criterio","IA resume"],["📧","Resultado","Correo al equipo"]],"cap":"Ejemplo: cada lunes a las 9 (detonante) lee tu planilla (datos), la IA resume (criterio) y envía el correo al equipo (resultado). Cero intervención.","narr":"Juntemos las cuatro piezas en un caso real: el reporte de ventas de cada lunes. El detonante: lunes a las nueve. Los datos: tu planilla de ventas. El criterio: la inteligencia artificial la resume en tres líneas. El resultado: el correo sale al equipo. Cuatro piezas, cero intervención tuya."},{"type":"flow","dur":19,"eyeb":"Ejemplo 2","h2":"El mismo esquema sirve para atención al cliente","nodes":[["💬","Detonante","Llega un mensaje"],["📇","Datos","Historial del cliente"],["🤖","Criterio","IA redacta respuesta"],["📤","Resultado","Respuesta enviada"]],"cap":"El mismo esquema: llega un mensaje (detonante), se lee el historial (datos), la IA redacta (criterio) y se responde (resultado).","narr":"Y no sirve solo para reportes. El mismo esquema resuelve, por ejemplo, la atención de consultas: llega un mensaje, ese es el detonante; se lee el historial del cliente, esos son los datos; la inteligencia artificial redacta una respuesta adecuada, ese es el criterio; y se envía, ese es el resultado. Las mismas cuatro piezas, otro problema resuelto."},{"type":"chips","dur":16,"eyeb":"Dónde vive esto","h2":"Se arma conectando bloques, sin programar","chips":[["🔗","Make"],["⚙️","n8n"],["⚡","Zapier"],["🧠","GPT"],["➕","y más"]],"cap":"Se construye en herramientas visuales (Make, n8n, Zapier) sumando modelos de IA. No necesitas programar: necesitas entender la lógica.","narr":"Todo esto se arma en herramientas visuales donde se conectan bloques, como Make, n8n o Zapier, sumándoles modelos de inteligencia artificial. La buena noticia: no necesitas programar. Necesitas entender la lógica que acabas de ver."},{"type":"myth","dur":16,"eyeb":"A tener en cuenta","h2":"Tres cosas que conviene entender bien","myths":[["No es magia"," ni una fórmula para hacerse rico"],["No reemplaza tu criterio"," lo potencia"],["No arregla el desorden"," primero entiendes el proceso, después lo automatizas"]],"cap":"La IA no es magia ni una fórmula de riqueza. No reemplaza tu criterio, lo potencia. Y no automatiza el caos: primero entiendes el proceso.","narr":"Un punto importante antes de seguir. La hiperautomatización no es magia ni una fórmula para hacerse rico. No reemplaza tu criterio: lo potencia. Y no funciona automatizando el desorden: primero entiendes bien el proceso, y después lo automatizas."},{"type":"pieces","dur":14,"eyeb":"Recapitulemos","h2":"Si reconoce estas 4 piezas, entiende cualquier flujo","pieces":[["⏰","Detonante","Qué lo activa"],["📊","Datos","De dónde saca"],["🤖","Criterio","Qué decide (IA)"],["📧","Resultado","Qué entrega"]],"cap":"Recap: todo flujo tiene detonante, datos, criterio y resultado. Reconocerlas es poder leer y diseñar cualquier automatización.","narr":"Recapitulemos. Todo flujo tiene cuatro piezas: detonante, datos, criterio y resultado. Si reconoces esas cuatro, ya puedes leer y diseñar cualquier automatización que se cruce en tu camino."},{"type":"title","dur":15,"eyeb":"En resumen","h2":"Un flujo no es magia: es criterio ordenado","sub":"Ya sabes qué es. En un momento lo vas a ver construirse, y después lo vas a armar tú mismo.","cap":"Un flujo es criterio bien ordenado. Ya sabes qué es. Sigue: verlo construirse y después armarlo tú mismo.","narr":"Eso es un flujo, y ese es el corazón de todo el curso. No es magia: es criterio bien ordenado. En un momento vas a ver uno construirse paso a paso, y después lo vas a armar tú mismo. Nos vemos en la práctica."}],"2":[{"type":"title","dur":18,"eyeb":"Bienvenido","h2":"La IA generativa cambió las reglas de la automatización","sub":"Antes automatizabas tareas rígidas. Ahora puedes darle criterio a un programa.","cap":"La IA generativa permite automatizar con criterio, no solo con reglas fijas. Eso cambia todo.","narr":"Bienvenido a esta lección. Hasta hace poco, automatizar era encadenar reglas rígidas. La inteligencia artificial generativa cambió las reglas del juego: ahora puedes darle criterio a un programa, para que decida y redacte casi como lo harías tú. En los próximos minutos vas a entender por qué."},{"type":"list","dur":16,"eyeb":"Qué vas a aprender","h2":"Cuatro ideas, en pocos minutos","items":[["1","Qué es un LLM","y cómo genera sus respuestas"],["2","Del chatbot al agente","la escalera de autonomía"],["3","La anatomía de un agente","de qué piezas está hecho"]],"cap":"En esta lección: qué es un LLM, la diferencia entre chatbot y agente, y de qué piezas está hecho un agente.","narr":"Vas a entender cuatro cosas: qué es un modelo de lenguaje y cómo genera sus respuestas, en qué se diferencia un chatbot de un agente, de qué piezas está hecho un agente, y dónde conviene usarlos de verdad."},{"type":"define","dur":15,"eyeb":"El concepto base","h2":"Primero, qué es un LLM","def":"Un <b>LLM</b> (modelo de lenguaje) es un programa entrenado con enormes cantidades de texto que <b>predice la siguiente palabra</b>, una tras otra, para formar respuestas coherentes.","cap":"Un LLM es un modelo entrenado con mucho texto que predice la siguiente palabra para formar respuestas.","narr":"Empecemos por la base. Un modelo de lenguaje grande, o LLM, es un programa entrenado con enormes cantidades de texto. En el fondo hace algo simple: predice la siguiente palabra, una tras otra. De esa predicción, repetida millones de veces, salen respuestas que suenan coherentes y útiles."},{"type":"pieces","dur":16,"eyeb":"Cómo funciona por dentro","h2":"Cuatro palabras que conviene que manejes","pieces":[["🧩","Token","Un pedazo de palabra"],["🪟","Contexto","Lo que puede leer a la vez"],["🌡️","Temperatura","Qué tan creativo responde"],["🌀","Alucinación","Cuando inventa con seguridad"]],"cap":"Token = pedazo de palabra. Contexto = lo que lee a la vez. Temperatura = creatividad. Alucinación = inventar con seguridad.","narr":"Cuatro palabras te van a servir siempre. Token: el modelo no lee letras ni palabras enteras, sino pedazos, y en tokens se mide todo. Contexto: cuánto texto puede tener presente a la vez. Temperatura: qué tan creativo o predecible responde. Y alucinación: cuando inventa un dato con total seguridad. Conocerlas te evita muchos errores."},{"type":"compare","dur":18,"eyeb":"La distinción clave","h2":"Un chatbot no es lo mismo que un agente","colA":["Chatbot","Responde y ya","Contesta lo que le preguntas. No actúa ni recuerda: cada mensaje empieza de cero."],"colB":["Agente","Persigue un objetivo","Planifica, usa herramientas y da varios pasos por su cuenta hasta lograr lo que le pediste."],"cap":"Chatbot: responde y ya. Agente: persigue un objetivo, planifica, usa herramientas y da varios pasos solo.","narr":"Aquí está la distinción que más importa. Un chatbot responde lo que le preguntas y ahí termina: no actúa ni recuerda. Un agente es otra cosa: le das un objetivo y, por su cuenta, planifica, usa herramientas y da varios pasos hasta lograrlo. El chatbot conversa; el agente trabaja."},{"type":"flow","dur":17,"eyeb":"La escalera de autonomía","h2":"Del que solo reacciona al equipo de agentes","nodes":[["💬","Reactivo","Responde"],["🧑‍💼","Asistente","Ayuda con contexto"],["🤖","Agente","Actúa solo"],["🕹️","Multiagente","Varios coordinados"]],"cap":"La autonomía sube por peldaños: reactivo, asistente, agente autónomo y varios agentes coordinados.","narr":"La autonomía no es de golpe: sube por peldaños. Primero el reactivo, que solo responde. Luego el asistente, que ayuda usando contexto. Después el agente, que actúa solo para cumplir una meta. Y arriba, varios agentes coordinados, cada uno con su tarea. Saber en qué peldaño estás te dice qué esperar."},{"type":"pieces","dur":16,"eyeb":"La anatomía","h2":"Un agente está hecho de cuatro piezas","pieces":[["🧠","Modelo","El que razona"],["🔧","Herramientas","Con qué actúa"],["📇","Memoria","Qué recuerda"],["🗺️","Planificación","Cómo se organiza"]],"cap":"Un agente = modelo (razona) + herramientas (actúa) + memoria (recuerda) + planificación (se organiza).","narr":"Todo agente, por complejo que parezca, tiene cuatro piezas. El modelo, que razona y decide. Las herramientas, con las que actúa en el mundo real: buscar, enviar, calcular. La memoria, que le permite recordar lo que ya pasó. Y la planificación, con la que se organiza en pasos. Reconoce estas cuatro y entiendes cualquier agente."},{"type":"spot","dur":16,"snum":"El motor del agente","sic":"🔁","stitle":"Razonar, actuar, observar","stext":"El agente piensa un paso, usa una herramienta, mira el resultado y decide el siguiente. Repite hasta terminar.","sex":"razona · actúa · observa · repite","cap":"El agente razona un paso, actúa con una herramienta, observa el resultado y repite hasta lograr la meta.","narr":"¿Y cómo hace todo eso? Con un ciclo muy simple que se repite. El agente razona el siguiente paso, usa una herramienta para ejecutarlo, observa qué resultado obtuvo, y con eso decide el paso siguiente. Razonar, actuar, observar, y otra vez. Ese bucle, repetido, es lo que hace que un agente parezca inteligente."},{"type":"flow","dur":18,"eyeb":"Un ejemplo real","h2":"Un agente que responde una consulta difícil","nodes":[["🎯","Objetivo","Responder al cliente"],["🗺️","Planea","Qué necesita saber"],["🔧","Consulta","Busca en tus datos"],["📤","Resuelve","Redacta y responde"]],"cap":"Ejemplo: recibe el objetivo, planea qué necesita, consulta tus datos con una herramienta y redacta la respuesta.","narr":"Veámoslo con un caso. Un cliente hace una pregunta compleja. El agente recibe el objetivo: responderle bien. Planea qué información necesita. Usa una herramienta para consultarla en tus datos. Y con eso redacta y envía la respuesta. Nadie le dictó cada paso: los decidió él para cumplir la meta."},{"type":"list","dur":16,"eyeb":"Dónde sí genera valor","h2":"No sirve para todo, pero brilla en esto","items":[["📨","Atención","Responder y clasificar consultas"],["🗂️","Back-office","Ordenar, resumir y registrar"],["📊","Análisis","Leer mucho y sacar conclusiones"]],"cap":"Brilla en atención al cliente, back-office (ordenar y resumir) y análisis de mucha información.","narr":"¿Dónde conviene usarlo? Donde hay mucho texto y criterio repetible. En atención, respondiendo y clasificando consultas. En el back-office, ordenando, resumiendo y registrando. Y en análisis, leyendo grandes volúmenes para sacar conclusiones. En cambio, para cálculos exactos o reglas fijas, hay mejores herramientas."},{"type":"myth","dur":16,"eyeb":"A tener en cuenta","h2":"Tres cosas para no llevarte una sorpresa","myths":[["No piensa como tú",", predice texto muy bien"],["No siempre acierta",", puede alucinar datos"],["No se deja sin vigilar",", necesita tu criterio"]],"cap":"El agente no piensa como un humano: predice texto. Puede alucinar. Y necesita tu supervisión.","narr":"Antes de seguir, tres advertencias sanas. Un modelo no piensa como tú: predice texto, y lo hace muy bien, pero no entiende como un humano. No siempre acierta: puede inventar un dato con seguridad. Y no se deja funcionando sin vigilancia: necesita tu criterio para las decisiones que importan. Bien usado, potencia tu trabajo; mal usado, te mete en problemas."},{"type":"title","dur":15,"eyeb":"En resumen","h2":"Un agente es un modelo con objetivo, herramientas y memoria","sub":"Ya sabes qué es y de qué está hecho. Sigue: verlo en acción y practicarlo tú mismo.","cap":"Un agente es un modelo con objetivo, herramientas y memoria. Sigue: verlo en acción y practicarlo.","narr":"Recapitulemos. Un modelo de lenguaje predice texto. Un agente es ese modelo con un objetivo, herramientas para actuar y memoria para recordar, moviéndose en un ciclo de razonar y actuar. Ya sabes qué es y de qué está hecho. Ahora sigue lo mejor: verlo en acción y armar el tuyo. Nos vemos en la práctica."}],"3":[{"type":"title","dur":18,"eyeb":"Bienvenido","h2":"Un agente hace exactamente lo que le pediste, no lo que querías","sub":"La diferencia entre un agente que sirve y uno que falla casi nunca está en el modelo: está en cómo lo instruyes.","cap":"Un agente hace lo que le pides, no lo que quieres. La calidad casi siempre está en la instrucción, no en el modelo.","narr":"Bienvenido a esta lección. Algo que descubres rápido al trabajar con agentes: hacen lo que les pides, no lo que tú querías. Y la diferencia entre uno que sirve y uno que falla casi nunca está en el modelo. Está en cómo lo instruyes."},{"type":"list","dur":16,"eyeb":"Qué vas a aprender","h2":"Tres cosas, en pocos minutos","items":[["1","Un prompt profesional","de qué seis partes está hecho"],["2","Subir la precisión","con ejemplos y razonamiento por pasos"],["3","Blindar tu agente","salidas fijas y contra manipulación"]],"cap":"En esta lección: la estructura de un prompt profesional, técnicas para subir la precisión y cómo proteger tu agente.","narr":"En los próximos minutos vas a entender tres cosas: de qué partes se arma un prompt profesional, cómo subir su precisión sin cambiar de modelo, y cómo proteger tu agente para que entregue siempre lo que esperas."},{"type":"define","dur":15,"eyeb":"El concepto base","h2":"Primero, qué es un system prompt","def":"El <b>system prompt</b> es la instrucción fija que define quién es tu agente y cómo debe comportarse, <b>en cada conversación</b>, antes de que el usuario diga nada.","cap":"El system prompt es la instrucción fija que define quién es el agente y cómo se comporta, en cada conversación.","narr":"Empecemos por la base. El system prompt es la instrucción fija que le das a tu agente: define quién es y cómo se comporta. Se aplica en cada conversación, antes de que el usuario escriba una sola palabra. Es su carácter y sus reglas."},{"type":"pieces","dur":17,"eyeb":"La anatomía","h2":"Un buen prompt tiene seis partes: RCTFE","pieces":[["🎭","Rol","Quién es"],["🗂️","Contexto","Qué debe saber"],["🎯","Tarea","Qué tiene que hacer"],["🚧","Restricciones","Qué no debe hacer"],["📐","Formato","Cómo entregarlo"],["📎","Ejemplos","Cómo se ve bien"]],"cap":"Un prompt profesional tiene seis partes: rol, contexto, tarea, restricciones, formato y ejemplos.","narr":"Un prompt profesional no es un párrafo suelto: tiene seis partes. El rol, que dice quién es. El contexto, lo que debe saber. La tarea, qué tiene que hacer. Las restricciones, qué no debe hacer. El formato, cómo entregarlo. Y los ejemplos, cómo se ve bien hecho. Reconoce esas seis y sabrás leer y escribir cualquier prompt."},{"type":"spot","dur":16,"snum":"La pieza que más cambia","sic":"🚧","stitle":"Las restricciones","stext":"Decir qué NO hacer evita más problemas que decir qué hacer. Aquí acotas al agente para que no se salga del carril.","sex":"no inventes datos · no des precios · deriva si dudas","cap":"Las restricciones (qué NO hacer) previenen más fallas que las instrucciones positivas. Acotan al agente.","narr":"De esas seis, hay una que casi todos olvidan y es la que más problemas evita: las restricciones. Decirle qué no debe hacer acota al agente para que no se salga del carril. No inventes datos, no prometas precios, deriva a un humano si dudas. Un límite claro vale más que diez instrucciones."},{"type":"compare","dur":18,"eyeb":"La primera técnica","h2":"Explicar no es lo mismo que mostrar","colA":["Zero-shot","Solo describes","Le dices qué quieres con palabras y esperas que lo interprete bien. A veces basta, a veces no."],"colB":["Few-shot","Muestras ejemplos","Le das dos o tres ejemplos de entrada y salida. El agente copia el patrón y acierta mucho más."],"cap":"Zero-shot: solo describes la tarea. Few-shot: le muestras ejemplos y el agente copia el patrón. Acierta más.","narr":"La primera técnica para subir la precisión es simple: en vez de solo describir lo que quieres, muéstralo. Sin ejemplos, el agente interpreta a su manera. Con dos o tres ejemplos de entrada y salida, copia el patrón y acierta mucho más. A eso se le llama few-shot, y suele ser el arreglo más rápido."},{"type":"define","dur":16,"eyeb":"La segunda técnica","h2":"Pídele que piense antes de responder","def":"<b>Chain-of-thought</b> es pedirle al modelo que razone paso a paso antes de dar la respuesta. Al pensar en voz alta, comete menos errores en tareas con lógica.","cap":"Chain-of-thought: pedirle que razone paso a paso antes de responder. Reduce errores en tareas con lógica.","narr":"La segunda técnica se llama chain-of-thought, o cadena de razonamiento. Consiste en pedirle que piense paso a paso antes de responder. Igual que una persona, cuando el modelo razona en voz alta en vez de contestar de golpe, comete bastantes menos errores en tareas que llevan lógica."},{"type":"spot","dur":15,"snum":"Un paso más","sic":"🗳️","stitle":"Self-consistency","stext":"En decisiones difíciles, le pides varias respuestas y te quedas con la que más se repite. La mayoría suele tener razón.","sex":"pregunta 3 veces · compara · elige la común","cap":"Self-consistency: generar varias respuestas a la misma pregunta y quedarte con la mayoritaria. Sube la fiabilidad.","narr":"Y hay un paso más para lo importante: self-consistency. En vez de fiarte de una sola respuesta, le pides varias a la misma pregunta y te quedas con la que más se repite. Como en un jurado, la mayoría suele acertar. Cuesta un poco más, pero en decisiones difíciles vale la pena."},{"type":"flow","dur":18,"eyeb":"Salidas estructuradas","h2":"Cuando otro sistema lee la respuesta, el formato manda","nodes":[["💬","Instrucción","Pides JSON"],["🤖","Modelo","Razona y arma"],["📐","Formato","Estructura fija"],["🔗","Sistema","Lo usa sin fallar"]],"cap":"Si otro sistema consume la respuesta, pides un formato fijo como JSON para que se conecte sin romperse.","narr":"Hasta aquí hablamos de texto para leer. Pero muchas veces la respuesta la consume otro sistema, no una persona. Ahí el formato manda: le pides una estructura fija, como un JSON con campos definidos. Así el modelo entrega algo que la siguiente herramienta puede usar sin romperse."},{"type":"define","dur":16,"eyeb":"Conectar con el mundo","h2":"Function calling: del texto a la acción","def":"Con <b>function calling</b>, en vez de responder texto, el modelo elige una herramienta y arma los datos para usarla: buscar, agendar, enviar. Así el agente actúa.","cap":"Function calling: el modelo elige una herramienta y prepara sus datos, en vez de solo responder texto. Así actúa.","narr":"Y de ahí a la acción hay un paso: function calling. En lugar de contestar con palabras, el modelo elige una herramienta disponible y prepara los datos para usarla: buscar un dato, agendar, enviar un correo. Esta es la pieza que convierte a un modelo que conversa en un agente que hace cosas."},{"type":"spot","dur":16,"snum":"La amenaza","sic":"🛡️","stitle":"Prompt injection","stext":"Alguien esconde instrucciones en un mensaje o documento para que tu agente ignore sus reglas y haga otra cosa.","sex":"'ignora lo anterior' · texto oculto · datos con trampa","cap":"Prompt injection: instrucciones ocultas en la entrada del usuario para que el agente desobedezca sus reglas.","narr":"Ahora la parte que casi nadie enseña: la seguridad. El ataque más común se llama prompt injection. Alguien esconde instrucciones dentro de un mensaje o un documento para que tu agente ignore sus reglas y haga otra cosa. Un clásico: un texto que dice ignora todo lo anterior. Si tu agente lee datos de fuera, estás expuesto."},{"type":"list","dur":17,"eyeb":"Cómo blindarlo","h2":"Tres defensas que sí funcionan","items":[["🧱","Separa instrucciones y datos","que el agente sepa qué es orden y qué es contenido"],["🚧","Reglas que no se negocian","escritas en el system prompt, por encima de todo"],["👤","Humano en decisiones críticas","nada irreversible sin una revisión"]],"cap":"Defensas: separa instrucciones de datos, fija reglas innegociables en el system prompt y mantén un humano en lo crítico.","narr":"¿Cómo lo blindas? Con tres defensas que sí funcionan. Primero, separa las instrucciones de los datos, para que el agente sepa qué es una orden tuya y qué es solo contenido a procesar. Segundo, deja reglas innegociables en el system prompt, por encima de todo. Y tercero, para lo irreversible, siempre un humano revisando."},{"type":"myth","dur":16,"eyeb":"A tener en cuenta","h2":"Tres cosas para no llevarte una sorpresa","myths":[["No hay prompt perfecto",", se prueba y se ajusta"],["Más largo no es mejor",", claro le gana a extenso"],["El prompt no borra el riesgo",", lo reduce, no lo elimina"]],"cap":"No existe el prompt perfecto: se itera. Más largo no es mejor. Y ningún prompt elimina el riesgo del todo.","narr":"Antes de cerrar, tres advertencias honestas. No existe el prompt perfecto: se prueba, se mide y se ajusta con el uso. Más largo no es mejor; un prompt claro y corto casi siempre gana a uno extenso. Y ojo: un buen prompt reduce el riesgo de fallas y ataques, pero no lo elimina. Por eso tu criterio sigue siendo indispensable."},{"type":"title","dur":15,"eyeb":"En resumen","h2":"Instruir bien es la mitad del trabajo de un agente","sub":"Ya sabes estructurar, subir la precisión y proteger. Sigue: escribir tus propios prompts y probarlos.","cap":"Instruir bien es la mitad del trabajo. Sigue: escribir tus propios prompts, medirlos y ajustarlos.","narr":"Recapitulemos. Un buen prompt tiene rol, contexto, tarea, restricciones, formato y ejemplos. Subes su precisión con ejemplos y razonamiento por pasos, fijas el formato para conectarlo con otros sistemas, y lo blindas contra manipulación. Instruir bien es la mitad del trabajo. Ahora sigue lo mejor: escribir los tuyos y probarlos. Nos vemos en la práctica."}],"4":[{"type":"title","dur":18,"eyeb":"Bienvenido","h2":"Hay decenas de herramientas de IA, y todas dicen ser la mejor","sub":"Texto, imagen, voz, video. El problema no es que falten opciones: es elegir bien.","cap":"Sobran herramientas de IA generativa. El reto real no es encontrarlas: es elegir la adecuada para cada tarea.","narr":"Bienvenido a esta lección. Hoy hay decenas de herramientas de inteligencia artificial, y todas se anuncian como la mejor. El problema ya no es que falten opciones: es saber elegir la correcta para cada tarea. Eso es lo que vas a aprender aquí."},{"type":"list","dur":16,"eyeb":"Qué vas a aprender","h2":"Tres cosas, en pocos minutos","items":[["1","El mapa de modelos","texto, imagen, voz y video"],["2","Cómo elegir bien","coste, calidad y privacidad"],["3","Cómo se conectan","APIs dentro de tus flujos"]],"cap":"En esta lección: el mapa de modelos por tipo, los criterios para elegir y cómo conectar una IA a tus flujos.","narr":"En los próximos minutos vas a entender tres cosas: cómo se organiza el mapa de modelos por tipo, qué criterios usar para elegir con cabeza, y cómo una herramienta de IA se conecta a tus automatizaciones."},{"type":"pieces","dur":16,"eyeb":"El mapa","h2":"Los modelos se agrupan por lo que producen","pieces":[["✍️","Texto","Escribe y razona"],["🎨","Imagen","Crea o edita visuales"],["🎙️","Voz","Habla y transcribe"],["🎬","Video","Genera clips"]],"cap":"Los modelos se agrupan por lo que producen: texto, imagen, voz y video. Cada familia resuelve un tipo de tarea.","narr":"Empecemos por ordenar el terreno. Los modelos se agrupan por lo que producen. Los de texto escriben y razonan. Los de imagen crean o editan visuales. Los de voz hablan y transcriben. Y los de video generan clips. Ubicar tu tarea en una de estas familias ya es medio camino."},{"type":"list","dur":18,"eyeb":"Modelos de texto","h2":"Los tres grandes que vas a escuchar nombrar","items":[["🟠","Claude","Fuerte en escritura larga y razonamiento cuidado"],["🟢","GPT","Versátil, con amplio ecosistema de herramientas"],["🔵","Gemini","Integrado con Google y buen manejo multimodal"]],"cap":"En texto, los tres nombres frecuentes son Claude, GPT y Gemini. Cada uno con fortalezas distintas.","narr":"En texto vas a escuchar sobre todo tres nombres. Claude destaca en escritura larga y razonamiento cuidado. GPT es muy versátil y tiene un ecosistema enorme. Y Gemini se integra con Google y maneja bien lo multimodal. No hay uno mejor para todo: hay uno mejor para cada caso."},{"type":"chips","dur":16,"eyeb":"Más allá del texto","h2":"Para imagen, voz y video también hay especialistas","chips":[["🎨","Midjourney"],["🖼️","DALL·E"],["🎙️","ElevenLabs"],["📝","Whisper"],["🎬","Runway"]],"cap":"Para imagen, voz y video hay herramientas especializadas: Midjourney, DALL-E, ElevenLabs, Whisper, Runway y más.","narr":"Fuera del texto hay especialistas muy buenos. Para imagen, Midjourney o DALL·E. Para voz, ElevenLabs genera locución natural y Whisper transcribe con precisión. Para video, Runway y similares. No necesitas memorizarlos: basta saber que cada tarea tiene su herramienta fuerte."},{"type":"compare","dur":18,"eyeb":"La primera decisión","h2":"En la nube o en tu propio equipo","colA":["En la nube","Rápido y potente","Usas modelos de última generación sin instalar nada. Pagas por uso y tus datos salen a un tercero."],"colB":["Local","Privado y bajo tu control","Corre en tu equipo o servidor. Más privacidad y sin costo por uso, pero exige hardware y mantenimiento."],"cap":"Nube: potente y sin instalar, pero tus datos salen. Local: privado y bajo tu control, pero exige hardware.","narr":"La primera gran decisión es dónde corre el modelo. En la nube tienes lo más potente sin instalar nada, pagando por uso, pero tus datos salen hacia un tercero. En local corre en tu propio equipo: más privacidad y sin costo por uso, aunque exige hardware y mantenimiento. La respuesta depende de qué tan sensibles sean tus datos."},{"type":"pieces","dur":17,"eyeb":"Cómo elegir","h2":"Tres criterios que sostienen toda decisión","pieces":[["💰","Coste","Cuánto cuesta cada uso"],["🎯","Calidad","Qué tan bueno es el resultado"],["🔒","Privacidad","Adónde van tus datos"]],"cap":"Toda elección se reduce a equilibrar tres cosas: coste por uso, calidad del resultado y privacidad de los datos.","narr":"Para elegir sin marearte, mide siempre tres cosas. El coste: cuánto pagas por cada uso. La calidad: qué tan bueno es el resultado para tu tarea. Y la privacidad: adónde van tus datos. Casi ninguna herramienta gana en las tres a la vez, así que eliges según lo que más pesa en tu caso."},{"type":"define","dur":15,"eyeb":"Un factor que se pasa por alto","h2":"La ventana de contexto también decide","def":"La <b>ventana de contexto</b> es cuánto texto puede leer el modelo de una sola vez. Si tu tarea usa documentos largos, <b>necesitas una ventana grande</b>.","cap":"La ventana de contexto es cuánto texto lee el modelo de una vez. Con documentos largos, necesitas una grande.","narr":"Hay un factor que muchos ignoran: la ventana de contexto. Es cuánto texto puede leer el modelo de una sola vez. Si vas a resumir un contrato de cien páginas, necesitas una ventana grande; si solo respondes mensajes cortos, una pequeña sobra. Elegir esto bien te ahorra errores y dinero."},{"type":"flow","dur":18,"eyeb":"Multimodal en la práctica","h2":"De una idea a un video, encadenando modelos","nodes":[["📝","Brief","Tu idea inicial"],["✍️","Texto","La IA escribe el guion"],["🎙️","Voz","Otra IA lo narra"],["🎬","Video","Se arma el clip"]],"cap":"Ejemplo multimodal: de un brief, un modelo escribe el guion, otro lo narra y otro genera el video.","narr":"Lo interesante es combinarlos. Mira un flujo real: partes de un brief, tu idea. Un modelo de texto escribe el guion. Un modelo de voz lo narra. Y un modelo de video arma el clip. Cada pieza la resuelve el especialista adecuado, y tú orquestas. Eso es generación multimodal en la práctica."},{"type":"spot","dur":16,"snum":"La pieza que une todo","sic":"🔌","stitle":"La API","stext":"Es la puerta por la que tu flujo le habla al modelo: le manda la petición y recibe la respuesta.","sex":"clave · petición · respuesta","cap":"La API es la puerta por la que tu automatización le habla al modelo: envía la petición y recibe la respuesta.","narr":"¿Y cómo conectas todo esto a tus automatizaciones? Con una API. Piensa en ella como la puerta por la que tu flujo le habla al modelo: le envías una petición con tu clave de acceso, y recibes la respuesta. Es el mismo mecanismo, sin importar si el modelo hace texto, voz o imagen."},{"type":"flow","dur":17,"eyeb":"Cómo se conecta","h2":"Una llamada a la API, paso a paso","nodes":[["🔑","Clave","Autentica quién eres"],["📨","Petición","Envías tu instrucción"],["🧠","Modelo","Procesa y genera"],["📥","Respuesta","Vuelve a tu flujo"]],"cap":"Una llamada a la API: te autenticas con tu clave, envías la petición, el modelo genera y la respuesta vuelve a tu flujo.","narr":"Veamos esa llamada por dentro. Primero te autenticas con una clave, que dice quién eres y habilita el cobro. Luego mandas la petición con tu instrucción. El modelo la procesa y genera el resultado. Y la respuesta vuelve a tu flujo, lista para el siguiente paso. En Make o n8n esto es un solo nodo."},{"type":"myth","dur":17,"eyeb":"A tener en cuenta","h2":"Tres cosas para no equivocarte al elegir","myths":[["La más cara no es la mejor",", la mejor es la que resuelve tu tarea"],["No cases tu flujo con un solo proveedor",", deja espacio para cambiar"],["El modelo no cuida tus datos por ti",", eso lo decides tú"]],"cap":"La más cara no siempre gana. No dependas de un solo proveedor. Y la privacidad de tus datos la decides tú.","narr":"Antes de cerrar, tres advertencias honestas. La herramienta más cara no es siempre la mejor: la mejor es la que resuelve tu tarea al menor costo razonable. No cases tu flujo con un solo proveedor: deja espacio para cambiar cuando salga algo mejor. Y recuerda que la privacidad de tus datos la decides tú, no el modelo."},{"type":"title","dur":15,"eyeb":"En resumen","h2":"Elegir bien vale más que usar la herramienta de moda","sub":"Ya tienes el mapa y los criterios. Sigue: conectar tu primera API y verla trabajar.","cap":"Con el mapa de modelos y los tres criterios, ya eliges con criterio. Sigue: conectar tu primera API.","narr":"Recapitulemos. Los modelos se agrupan por lo que producen, eliges equilibrando coste, calidad y privacidad, y los conectas a tus flujos mediante una API. Elegir con criterio vale más que usar la herramienta de moda. Ahora sigue lo práctico: conectar tu primera API y verla trabajar. Nos vemos ahí."}],"5":[{"type":"title","dur":18,"eyeb":"Bienvenido","h2":"Ya entiendes los flujos: ahora vas a construirlos","sub":"n8n es el lienzo donde conectas bloques y armas agentes reales, sin escribir código.","cap":"n8n es la herramienta donde conectas bloques y construyes flujos y agentes reales, sin programar.","narr":"Bienvenido a esta lección. Ya sabes qué es un flujo y de qué piezas está hecho. Ahora toca lo bueno: construirlo con tus manos. La herramienta se llama n8n, un lienzo donde conectas bloques y armas agentes reales, sin escribir código."},{"type":"list","dur":16,"eyeb":"Qué vas a aprender","h2":"Cuatro cosas, paso a paso","items":[["1","Qué es n8n","y cómo lo pones a andar"],["2","Tu primer flujo","trigger, lógica y acción"],["3","El nodo AI Agent","cómo le sumas inteligencia"]],"cap":"En esta lección: qué es n8n, cómo armar tu primer flujo, y cómo integrar el nodo de IA.","narr":"En los próximos minutos vas a entender cuatro cosas: qué es n8n y cómo lo pones en marcha, cómo se arma tu primer flujo de principio a fin, cómo le sumas un agente de inteligencia artificial, y cómo lo dejas corriendo sin sorpresas."},{"type":"define","dur":15,"eyeb":"El concepto base","h2":"Primero, qué es n8n","def":"<b>n8n</b> es una plataforma visual donde arrastras y conectas <b>nodos</b>. Cada nodo hace una cosa, y el flujo pasa de uno al siguiente.","cap":"n8n es una plataforma visual de nodos: cada nodo hace una cosa y el flujo pasa de uno al siguiente.","narr":"Empecemos por la base. n8n es una plataforma visual donde arrastras bloques, llamados nodos, y los conectas con una línea. Cada nodo hace una sola cosa: leer datos, decidir, enviar algo. El flujo pasa de un nodo al siguiente, en orden. Eso es todo."},{"type":"compare","dur":18,"eyeb":"La primera decisión","h2":"En la nube o en tu propio servidor","colA":["n8n Cloud","Listo en minutos","Te registras y empiezas. Ellos se encargan del servidor. Ideal para arrancar y aprender rápido."],"colB":["Self-hosted","Tú lo controlas","Lo instalas en tu propio servidor. Más control y privacidad de datos, a cambio de más trabajo de mantenimiento."],"cap":"n8n Cloud: listo en minutos, ellos manejan el servidor. Self-hosted: más control y privacidad, más mantenimiento.","narr":"Lo primero que vas a decidir es dónde corre n8n. En la nube, te registras y empiezas en minutos: ellos manejan el servidor. O en tu propio servidor, lo que llaman self-hosted: más control y más privacidad de tus datos, a cambio de encargarte del mantenimiento. Para aprender, la nube es el camino más corto."},{"type":"pieces","dur":16,"eyeb":"El vocabulario","h2":"Cuatro palabras que vas a usar todo el tiempo","pieces":[["🧩","Nodo","Un paso del flujo"],["⚡","Trigger","El nodo que arranca todo"],["🔑","Credencial","Tu acceso a otra app"],["▶️","Ejecución","Una corrida del flujo"]],"cap":"Nodo = un paso. Trigger = el que arranca. Credencial = tu acceso a una app. Ejecución = una corrida del flujo.","narr":"Cuatro palabras te van a acompañar siempre en n8n. Nodo: cada paso del flujo. Trigger: el nodo especial que lo pone en marcha, el detonante que ya conoces. Credencial: el acceso guardado a otra app, como tu correo o una base. Y ejecución: cada vez que el flujo corre de principio a fin. Con estas cuatro te mueves con soltura."},{"type":"flow","dur":18,"eyeb":"Tu primer flujo","h2":"Trigger, lógica y acción: la estructura base","nodes":[["⚡","Trigger","Algo lo dispara"],["🔀","Lógica","IF o Switch decide"],["🌐","Acción","HTTP o app externa"],["✅","Resultado","Queda hecho"]],"cap":"Todo flujo sigue la misma estructura: un trigger lo dispara, la lógica decide, una acción ejecuta y entrega el resultado.","narr":"Todo primer flujo sigue la misma columna vertebral. Un trigger lo dispara: por ejemplo, un webhook que recibe un aviso. Un nodo de lógica decide el camino, con un IF o un Switch. Un nodo de acción ejecuta, como un HTTP Request que llama a otra app. Y el resultado queda hecho. Esa estructura se repite en casi todo lo que vas a construir."},{"type":"spot","dur":16,"snum":"El corazón de los datos","sic":"🔗","stitle":"Cada nodo recibe lo del anterior","stext":"Los datos viajan en JSON de un nodo al siguiente. Un nodo usa lo que produjo el que va antes.","sex":"nodo 1 produce · nodo 2 lo usa · y así sigue","cap":"Los datos viajan en JSON de un nodo al siguiente: cada nodo trabaja con lo que produjo el anterior.","narr":"Aquí está la idea que hace clic con todo. Los datos viajan de un nodo al siguiente en un formato llamado JSON. Cada nodo recibe lo que produjo el anterior y trabaja con eso. El trigger trae la información, el siguiente nodo la transforma, el que sigue la usa. Si entiendes ese hilo, entiendes cómo piensa n8n por dentro."},{"type":"define","dur":15,"eyeb":"La pieza estrella","h2":"El nodo que lo cambia todo: AI Agent","def":"El nodo <b>AI Agent</b> mete un agente de IA dentro de tu flujo. Le das un objetivo y herramientas, y él decide los pasos.","cap":"El nodo AI Agent mete un agente de IA en tu flujo: le das objetivo y herramientas, y él decide los pasos.","narr":"Y llegamos a la pieza estrella. n8n tiene un nodo llamado AI Agent, que mete un agente de inteligencia artificial dentro de tu flujo. En lugar de programar cada decisión, le das un objetivo y unas herramientas. El agente decide por su cuenta qué pasos dar para cumplirlo. Aquí es donde el criterio entra a tu automatización."},{"type":"pieces","dur":17,"eyeb":"Cómo se arma el agente","h2":"Al nodo AI Agent le conectas tres cosas","pieces":[["🧠","Modelo","El LLM que razona"],["📇","Memoria","Recuerda la conversación"],["🔧","Tools","Con qué puede actuar"]],"cap":"Al nodo AI Agent le conectas un modelo (razona), memoria (recuerda) y tools (con qué actúa).","narr":"Armar ese agente es más simple de lo que parece. Al nodo AI Agent le conectas tres piezas, las mismas que ya viste. Un modelo, el LLM que razona y decide. Una memoria, para que recuerde lo hablado. Y las tools, las herramientas con las que puede actuar: buscar en tus datos, enviar un mensaje, consultar una API. Tres conexiones, y tienes un agente funcionando."},{"type":"flow","dur":18,"eyeb":"Un ejemplo completo","h2":"Un agente que atiende consultas por webhook","nodes":[["💬","Trigger","Llega una consulta"],["🧠","AI Agent","Razona con tools"],["🔧","Tool","Busca en tu base"],["📤","Respuesta","Contesta al cliente"]],"cap":"Ejemplo: un webhook recibe la consulta, el AI Agent razona, usa una tool para buscar en tu base y responde.","narr":"Juntemos todo en un caso real. Un cliente manda una consulta y un webhook la recibe: ese es el trigger. El nodo AI Agent la lee y razona qué necesita. Usa una tool para buscar la respuesta en tu base de datos. Y con eso redacta y contesta. Un flujo corto, pero es un agente completo trabajando solo."},{"type":"list","dur":17,"eyeb":"Antes de producción","h2":"Un flujo que corre solo tiene que aguantar fallos","items":[["🔁","Reintentos","Si un paso falla, que lo intente de nuevo"],["🚨","Error workflow","Un flujo aparte que te avisa cuando algo truena"],["👁️","Ejecuciones","Revisa el historial para ver qué pasó"]],"cap":"Para producción: configura reintentos, un workflow de error que avise, y revisa el historial de ejecuciones.","narr":"Antes de dejarlo corriendo solo, un flujo serio tiene que aguantar fallos. Configura reintentos, para que un paso que falla lo intente de nuevo antes de rendirse. Arma un workflow de error, un flujo aparte que te avisa cuando algo truena. Y revisa el historial de ejecuciones, donde n8n guarda qué pasó en cada corrida. Eso separa un experimento de algo confiable."},{"type":"myth","dur":16,"eyeb":"A tener en cuenta","h2":"Tres cosas honestas antes de lanzarte","myths":[["No es magia sin errores",", vas a depurar y ajustar"],["No lo dejes sin vigilar",", revisa sus ejecuciones"],["No automatices el caos",", primero el proceso claro"]],"cap":"n8n no elimina los errores: vas a depurar. No lo dejes sin vigilar. Y primero ordena el proceso.","narr":"Un punto honesto antes de lanzarte. n8n no es magia sin errores: vas a probar, fallar y ajustar, y eso es normal. No lo dejes funcionando sin mirar: revisa sus ejecuciones, sobre todo al inicio. Y no automatices el desorden: si el proceso no está claro en tu cabeza, tampoco lo estará en el lienzo. La herramienta potencia tu criterio, no lo reemplaza."},{"type":"chips","dur":15,"eyeb":"Lo que ya tienes","h2":"Con esto ya puedes armar tu primer agente","chips":[["⚡","Trigger"],["🔀","Lógica"],["🌐","Acción"],["🧠","AI Agent"],["🔁","Errores"]],"cap":"Ya tienes las piezas: trigger, lógica, acción, el nodo AI Agent y el manejo de errores.","narr":"Recapitulemos lo que ya llevas. Sabes qué es n8n y dónde corre. Conoces el trigger, la lógica y la acción. Sabes armar el nodo AI Agent con su modelo, memoria y tools. Y sabes prepararlo para producción con reintentos y avisos. Son todas las piezas de tu primer agente."},{"type":"title","dur":15,"eyeb":"En resumen","h2":"n8n es donde tu criterio se vuelve un flujo que corre solo","sub":"Ya conoces las piezas. Sigue lo mejor: abrir n8n y construir tu primer agente paso a paso.","cap":"n8n convierte tu criterio en un flujo que corre solo. Sigue: abrirlo y construir tu primer agente.","narr":"Eso es n8n. No es solo una herramienta bonita: es donde tu criterio se convierte en un flujo que corre solo, una y otra vez, sin ti en el medio. Ya conoces las piezas. Ahora sigue lo mejor: abrir n8n y construir tu primer agente, paso a paso. Nos vemos en la práctica."}],"6":[{"type":"title","dur":18,"eyeb":"Bienvenido","h2":"Make convierte una idea en un flujo que ves moverse","sub":"Su editor visual muestra los datos viajando de un módulo al siguiente, en vivo.","cap":"Make es una herramienta visual donde armas automatizaciones conectando módulos y ves los datos moverse entre ellos.","narr":"Bienvenido a esta lección. Make es una herramienta para armar automatizaciones sin programar. Su gracia es visual: conectas módulos con líneas y ves los datos viajar de uno al siguiente. En los próximos minutos vas a entender cómo piensa Make y cuándo conviene usarlo."},{"type":"list","dur":16,"eyeb":"Qué vas a aprender","h2":"Cuatro ideas, en pocos minutos","items":[["1","Make frente a n8n","cuándo conviene cada uno"],["2","Escenarios y módulos","cómo viajan los datos"],["3","Routers, filtros e iteradores","para ramificar y recorrer"]],"cap":"En esta lección: Make frente a n8n, cómo fluyen los datos entre módulos, y cómo ramificar y recorrer colecciones.","narr":"Vas a entender cuatro cosas: en qué se diferencia Make de n8n y cuándo elegir cada uno, cómo se arma un escenario y viajan los datos, cómo ramificar y recorrer listas, y cómo sumarle inteligencia artificial cuidando el consumo."},{"type":"define","dur":15,"eyeb":"El concepto base","h2":"Primero, qué es un escenario","def":"Un <b>escenario</b> en Make es tu automatización completa: una cadena de <b>módulos</b> conectados que se ejecutan en orden cuando algo la dispara.","cap":"Un escenario es la automatización completa: módulos conectados que se ejecutan en orden al dispararse.","narr":"Empecemos por la palabra clave. En Make, tu automatización entera se llama escenario. Es una cadena de módulos conectados que se ejecutan en orden cuando algo la dispara. Cada módulo hace una cosa, y el escenario es la película completa."},{"type":"pieces","dur":16,"eyeb":"La anatomía","h2":"Todo escenario se arma con estas piezas","pieces":[["▶️","Disparador","El primer módulo"],["🧩","Módulo","Una acción o app"],["📦","Bundle","Un paquete de datos"],["🔗","Conexión","La línea que los une"]],"cap":"Escenario = disparador (arranca) + módulos (cada acción) + bundles (los datos que pasan) + conexiones (las líneas).","narr":"Un escenario tiene cuatro piezas. El disparador, el primer módulo que lo pone en marcha. Los módulos, cada uno una acción o una app. Los bundles, los paquetes de datos que pasan de un módulo al siguiente. Y las conexiones, las líneas que los unen. Reconoce estas cuatro y lees cualquier escenario."},{"type":"compare","dur":18,"eyeb":"La decisión práctica","h2":"Make y n8n resuelven lo mismo, distinto","colA":["Make","Visual y guiado","Editor muy intuitivo y cientos de apps listas. Cobra por operación: cada acción de cada módulo cuenta."],"colB":["n8n","Flexible y técnico","Más control, self-hosting y nodos de código. Cobra por ejecución, no por paso: sale mejor a gran volumen."],"cap":"Make: más visual y guiado, cobra por operación. n8n: más flexible y técnico, cobra por ejecución; conviene a gran volumen.","narr":"¿Make o n8n? Los dos conectan apps y suman inteligencia artificial. Make es más visual y guiado, con cientos de apps listas, y cobra por operación: cada paso cuenta. n8n da más control, permite alojarlo tú mismo y escribir código, y cobra por ejecución. Para empezar rápido, Make. Para gran volumen o control fino, n8n."},{"type":"define","dur":15,"eyeb":"La unidad que se paga","h2":"La palabra que decide tu factura: operación","def":"Una <b>operación</b> es cada vez que un módulo hace su trabajo. Tu plan trae un número de operaciones al mes: menos módulos y menos vueltas, menos consumo.","cap":"Una operación es cada vez que un módulo actúa. Tu plan incluye un tope mensual, así que el diseño afecta el costo.","narr":"Antes de seguir, una palabra que impacta tu bolsillo: operación. Cada vez que un módulo hace su trabajo, cuenta una operación. Tu plan trae un tope mensual. Por eso el diseño importa: cuantos más módulos y más vueltas, más operaciones consumes. Diseñar con cabeza es diseñar barato."},{"type":"flow","dur":18,"eyeb":"Un escenario completo","h2":"Un pedido nuevo, de principio a fin","nodes":[["🛒","Disparador","Entra un pedido"],["📇","Busca","Datos del cliente"],["🤖","IA","Redacta el aviso"],["📧","Actúa","Envía y registra"]],"cap":"Ejemplo: entra un pedido (disparador), se buscan los datos del cliente, la IA redacta el aviso y otro módulo lo envía y registra.","narr":"Veámoslo junto. Entra un pedido nuevo: ese es el disparador. Un módulo busca los datos del cliente. Otro, con inteligencia artificial, redacta un aviso claro. Y el último lo envía y lo registra en tu planilla. Cuatro módulos conectados, un proceso entero resuelto sin que toques nada."},{"type":"pieces","dur":17,"eyeb":"Las herramientas de control","h2":"Tres piezas para que el flujo decida y recorra","pieces":[["🔀","Router","Parte el flujo en rutas"],["🔎","Filtro","Deja pasar solo lo que cumple"],["🔁","Iterador","Recorre uno por uno"]],"cap":"Router: divide el flujo en rutas. Filtro: deja pasar solo lo que cumple una condición. Iterador: recorre una lista uno por uno.","narr":"Un escenario no siempre es una línea recta. Tres piezas le dan lógica. El router parte el flujo en varias rutas. El filtro pone una condición y deja pasar solo lo que la cumple. Y el iterador toma una lista y la recorre elemento por elemento. Con estas tres, tu escenario decide y procesa en volumen."},{"type":"spot","dur":16,"snum":"Router más filtro","sic":"🔀","stitle":"Ramificar con criterio","stext":"El router abre caminos y cada ruta lleva su filtro: cada dato sigue solo el camino que le corresponde.","sex":"pedido grande → una ruta · pedido chico → otra","cap":"El router abre varios caminos y cada ruta puede llevar un filtro, para que cada dato siga la ruta que le corresponde.","narr":"Router y filtro trabajan juntos y valen oro. El router abre varios caminos, y en cada ruta pones un filtro con su condición. Así, un pedido grande sigue una ruta, uno chico sigue otra, y una queja va directa a una persona. Cada dato toma solo el camino que le corresponde, sin que escribas una sola línea de código."},{"type":"spot","dur":16,"snum":"El iterador","sic":"🔁","stitle":"Cuando llegan muchos a la vez","stext":"Si un módulo trae una lista, el iterador la parte en elementos sueltos y el resto del flujo actúa sobre cada uno.","sex":"10 facturas en un correo → procesar una por una","cap":"Si un módulo devuelve una lista, el iterador la separa en elementos sueltos para tratar cada uno por su cuenta.","narr":"El iterador resuelve algo muy común. A veces un módulo trae una lista entera: diez facturas en un correo, varias filas de una tabla. El iterador parte esa lista en elementos sueltos, y el resto del flujo actúa sobre cada uno por separado. Eso sí, recuerda: cada vuelta consume operaciones, así que úsalo con intención."},{"type":"list","dur":16,"eyeb":"IA y control de consumo","h2":"Sumar inteligencia sin dispararte la factura","items":[["🧠","Módulo de IA","Un paso más que resume o redacta"],["🔎","Filtra antes","Que la IA solo procese lo que vale"],["🧯","Maneja errores","Reintenta o desvía en vez de romper"]],"cap":"Integra IA como un módulo más, filtra antes para no procesar de más, y agrega manejo de errores para que un fallo no rompa todo.","narr":"Sumar inteligencia artificial en Make es agregar un módulo más que resume, clasifica o redacta. Dos consejos para no dispararte la factura ni los problemas. Filtra antes: que la IA procese solo lo que de verdad vale la pena. Y maneja los errores: agrega rutas que reintenten o desvíen, para que un fallo no rompa el escenario entero."},{"type":"myth","dur":16,"eyeb":"A tener en cuenta","h2":"Tres cosas para no llevarte una sorpresa","myths":[["No es gratis a escala",", cada operación se cuenta"],["Más módulos no es mejor",", suma costo y puntos de falla"],["La IA no se deja sola",", revisa lo que decide"]],"cap":"A escala cada operación cuenta; más módulos suman costo y fallas; y la IA necesita tu revisión en lo que importa.","narr":"Antes de cerrar, tres advertencias sanas. Make no es gratis a escala: cada operación se cuenta, y un escenario descuidado se vuelve caro. Más módulos no siempre es mejor: suman costo y más puntos donde algo puede fallar. Y la inteligencia artificial no se deja sola: revisa lo que decide en lo que de verdad importa."},{"type":"title","dur":15,"eyeb":"En resumen","h2":"Un escenario es criterio ordenado en módulos que ves moverse","sub":"Ya sabes cómo piensa Make. Sigue: armar tu primer escenario y verlo correr paso a paso.","cap":"Un escenario es criterio ordenado en módulos. Ya sabes cómo piensa Make; sigue armar el tuyo y verlo correr.","narr":"Recapitulemos. En Make, un escenario es una cadena de módulos por la que viajan datos. Los routers, filtros e iteradores le dan lógica. Y todo cuesta operaciones, así que diseñas con cabeza. Ya sabes cómo piensa Make. Ahora sigue lo mejor: armar tu primer escenario y verlo correr. Nos vemos en la práctica."}],"7":[{"type":"title","dur":18,"eyeb":"Bienvenido","h2":"Ahora puedes construir software describiendo lo que quieres","sub":"Claude escribe y corrige el código; tú pones la intención y el criterio.","cap":"Con Claude puedes crear automatizaciones y software describiendo lo que necesitas, sin ser programador experto.","narr":"Bienvenido a esta lección. Durante años, automatizar de verdad exigía saber programar. Eso cambió. Hoy puedes describir lo que quieres en tu idioma y Claude escribe el código por ti. A eso se le llama vibe coding, y aquí vas a entender cómo se hace bien."},{"type":"list","dur":16,"eyeb":"Qué vas a aprender","h2":"Cuatro ideas, en pocos minutos","items":[["1","Qué es el vibe coding","y cuándo conviene usarlo"],["2","Claude como copiloto","para generar y corregir código"],["3","Qué es MCP","cómo conectar Claude a tus herramientas"]],"cap":"En esta lección: qué es el vibe coding, Claude como copiloto de automatización, y cómo conectarlo a tus herramientas con MCP.","narr":"Vas a entender cuatro cosas: qué es el vibe coding y cuándo funciona, cómo usar a Claude de copiloto para generar y corregir código, qué es el protocolo MCP para conectarlo a tus herramientas, y cómo se ve todo esto en un proyecto real."},{"type":"define","dur":16,"eyeb":"El concepto base","h2":"Primero, qué es el vibe coding","def":"El <b>vibe coding</b> es construir software describiendo tu intención en <b>lenguaje natural</b>: tú dices qué quieres lograr y la IA escribe el código que lo hace.","cap":"Vibe coding es construir describiendo tu intención en lenguaje natural: tú dices el qué, la IA escribe el cómo.","narr":"Empecemos por la base. El vibe coding es construir software describiendo tu intención en lenguaje natural. Tú explicas qué quieres lograr, con tus palabras, y la inteligencia artificial traduce esa idea a código que funciona. Tú pones el qué; ella resuelve el cómo."},{"type":"compare","dur":18,"eyeb":"La distinción clave","h2":"No es lo mismo escribir código que dirigirlo","colA":["Programar a mano","Tú escribes cada línea","Necesitas dominar la sintaxis y recordar cada detalle. Avanzas al ritmo de lo que ya sabes."],"colB":["Vibe coding","Tú diriges, la IA escribe","Describes la meta y revisas el resultado. Avanzas más rápido, pero tu criterio sigue mandando."],"cap":"Programar a mano: escribes cada línea. Vibe coding: describes la meta, revisas el resultado y tu criterio manda.","narr":"Aquí está la diferencia. Programar a mano es escribir cada línea tú mismo: avanzas al ritmo de lo que ya dominas. En el vibe coding tú diriges y la IA escribe: describes la meta, revisas lo que entrega y corriges el rumbo. Vas más rápido, pero tu criterio sigue al mando. Ese matiz lo es todo."},{"type":"spot","dur":16,"snum":"La regla de oro","sic":"🔍","stitle":"Genera rápido, pero revisa siempre","stext":"Claude puede equivocarse con total seguridad. Tú lees, pruebas y validas lo que entrega antes de confiar en ello.","sex":"describe · genera · prueba · valida","cap":"Claude puede equivocarse con seguridad. Genera rápido, pero tú siempre lees, pruebas y validas antes de confiar.","narr":"Y aquí la regla de oro del vibe coding disciplinado. Claude escribe rápido, pero puede equivocarse con total seguridad. Por eso el ciclo es: describe, genera, prueba y valida. Nunca uses en producción algo que no probaste. La IA acelera tu trabajo; tu revisión evita que ese código te falle."},{"type":"list","dur":16,"eyeb":"Cuándo funciona","h2":"Brilla aquí, y conviene evitarlo allá","items":[["✅","Prototipos y scripts","Probar una idea o resolver una tarea puntual"],["🔗","Integraciones y datos","Conectar servicios, transformar y limpiar información"],["⚠️","Sistemas críticos","Ahí exige revisión experta, no confíes a ciegas"]],"cap":"Brilla en prototipos, scripts e integraciones. En sistemas críticos exige revisión experta: no confíes a ciegas.","narr":"¿Cuándo conviene? Brilla en prototipos y scripts, para probar una idea o resolver una tarea puntual. También en integraciones y manejo de datos, conectando servicios y limpiando información. ¿Dónde tener cuidado? En sistemas críticos, donde un error cuesta caro: ahí el código de la IA necesita revisión experta antes de confiar."},{"type":"pieces","dur":16,"eyeb":"Claude como copiloto","h2":"Cuatro tareas donde te ahorra horas","pieces":[["✍️","Genera","Escribe el script desde tu idea"],["🐞","Depura","Encuentra y corrige errores"],["🔄","Transforma","Convierte y limpia datos"],["💡","Explica","Te dice qué hace cada parte"]],"cap":"Claude copiloto: genera scripts, depura errores, transforma datos y te explica qué hace cada parte del código.","narr":"Como copiloto, Claude te sirve en cuatro frentes. Genera: escribe un script partiendo de tu idea. Depura: le pegas un error y te dice cómo corregirlo. Transforma: convierte y limpia datos entre formatos. Y explica: te aclara qué hace cada parte, para que aprendas mientras construyes. Cuatro tareas, muchas horas ahorradas."},{"type":"flow","dur":18,"eyeb":"Cómo trabajas con él","h2":"El ciclo de construir con Claude, paso a paso","nodes":[["🗣️","Describe","Explicas la tarea"],["⚙️","Genera","Claude escribe"],["▶️","Prueba","Corres y revisas"],["🔁","Ajusta","Corriges e iteras"]],"cap":"El ciclo: describes la tarea, Claude genera, tú pruebas el resultado y ajustas iterando hasta que funcione.","narr":"Trabajar con Claude es un ciclo simple que se repite. Describes la tarea con claridad. Claude genera el código. Tú lo corres y revisas si hace lo que esperabas. Y ajustas: le pides un cambio, corriges un detalle, e iteras. Cuanto más claro describes, menos vueltas necesitas. La claridad es tu mejor herramienta."},{"type":"define","dur":16,"eyeb":"Conectar Claude al mundo","h2":"Qué es MCP","def":"El <b>MCP</b> es un protocolo que le da a Claude <b>herramientas</b>: le permite leer tus archivos, consultar APIs y usar servicios, no solo conversar.","cap":"MCP es un protocolo que conecta Claude a herramientas: archivos, APIs y servicios. Deja de solo conversar y actúa.","narr":"Hasta aquí Claude solo escribe texto y código. Para que actúe en tu mundo existe el MCP, el protocolo de contexto de modelo. Es un estándar que le da herramientas: leer tus archivos, consultar una API, usar un servicio. Con MCP, Claude deja de solo conversar y empieza a hacer cosas por ti."},{"type":"flow","dur":17,"eyeb":"MCP en acción","h2":"De una petición tuya a una acción real","nodes":[["🗣️","Pides","Ordena esta carpeta"],["🧠","Razona","Claude decide qué hacer"],["🔧","Usa la tool","Lee y mueve archivos"],["✅","Resuelve","Carpeta ordenada"]],"cap":"Con MCP: le pides ordenar una carpeta, Claude razona, usa la herramienta para leer y mover archivos, y lo resuelve.","narr":"Veámoslo en acción. Le pides a Claude: ordena esta carpeta. Con MCP, razona qué hacer, usa una herramienta para leer los archivos y moverlos donde corresponde, y te devuelve la carpeta ordenada. No describió los pasos: los ejecutó. Ese salto, de hablar a actuar, es lo que hace tan potente al MCP."},{"type":"chips","dur":15,"eyeb":"A qué se conecta","h2":"Con MCP, Claude alcanza tus herramientas","chips":[["📁","Archivos"],["🌐","APIs"],["🗄️","Bases de datos"],["💬","Slack"],["➕","y más"]],"cap":"Mediante MCP, Claude se conecta a tus archivos, APIs, bases de datos y apps como Slack, entre muchas otras.","narr":"¿A qué se conecta? A tus archivos locales, a las APIs de los servicios que ya usas, a bases de datos, a apps como Slack, y a muchas más cada mes. La idea es sencilla: en lugar de copiar y pegar entre sistemas, Claude los alcanza directo y trabaja con ellos por ti."},{"type":"flow","dur":18,"eyeb":"Proyecto guiado","h2":"Automatizar una tarea real, de la idea al flujo","nodes":[["💡","Idea","Reporte diario de ventas"],["📝","Describe","Se lo explicas a Claude"],["⚙️","Construye","Genera el script y lo conecta"],["🚀","Corre","Se ejecuta solo cada día"]],"cap":"Proyecto: partes de una idea, se la describes a Claude, él construye y conecta el script, y termina corriendo solo.","narr":"Juntemos todo en un proyecto real. Idea: quieres un reporte de ventas cada mañana. Se lo describes a Claude con detalle. Él construye el script, lo conecta a tus datos vía MCP y lo prueba contigo. Al final, el reporte se genera solo cada día. De una idea en tu cabeza a un flujo funcionando, iterando paso a paso."},{"type":"myth","dur":16,"eyeb":"A tener en cuenta","h2":"Tres cosas para no llevarte una sorpresa","myths":[["No te vuelve programador senior",", te da un copiloto que hay que dirigir"],["No siempre acierta",", su código se prueba antes de usar"],["No entiende tu negocio",", el criterio y el contexto los pones tú"]],"cap":"El vibe coding no te vuelve senior ni acierta siempre: su código se prueba. Y no entiende tu negocio: eso lo pones tú.","narr":"Antes de cerrar, tres advertencias honestas. El vibe coding no te convierte en programador senior de un día para otro: te da un copiloto que hay que saber dirigir. No siempre acierta, así que su código se prueba antes de usarlo. Y no entiende tu negocio: el contexto y el criterio los sigues poniendo tú. Bien usado, multiplica lo que puedes construir."},{"type":"title","dur":15,"eyeb":"En resumen","h2":"Describes la intención; Claude escribe, tú validas","sub":"Ya sabes qué es el vibe coding y cómo conectar Claude con MCP. Sigue: construirlo tú mismo.","cap":"Vibe coding: tú describes la intención, Claude escribe y tú validas. Con MCP, además actúa. Sigue: practicarlo.","narr":"Recapitulemos. El vibe coding es construir describiendo tu intención: Claude escribe el código y tú lo validas. Con MCP, además, se conecta a tus herramientas y actúa. Ya tienes el mapa completo. Ahora sigue lo mejor: sentarte a construir tu primera automatización con él. Nos vemos en la práctica."}],"8":[{"type":"title","dur":18,"eyeb":"Bienvenido","h2":"Antes de automatizar, hay que entender el proceso de verdad","sub":"El error más caro no es elegir mal la herramienta: es automatizar un proceso que nadie entendió bien.","cap":"El error más caro no es la herramienta, sino automatizar un proceso que nadie entendió bien. Empecemos por entenderlo.","narr":"Bienvenido a esta lección. El error más caro en automatización no es elegir mal la herramienta. Es automatizar un proceso que nadie entendió del todo. Antes de tocar nada, hay que levantar el proceso real y detectar dónde conviene actuar. Eso vamos a aprender."},{"type":"list","dur":16,"eyeb":"Qué vas a aprender","h2":"Cuatro pasos, en pocos minutos","items":[["1","Levantar el proceso real","con entrevistas y observación"],["2","Encontrar los cuellos de botella","con datos, no con intuición"],["3","Priorizar qué automatizar","impacto contra complejidad"]],"cap":"En esta lección: levantar el proceso real, encontrar cuellos de botella con datos y priorizar qué automatizar primero.","narr":"Vas a aprender cuatro pasos. Levantar el proceso real como de verdad ocurre. Encontrar los cuellos de botella con datos, no con corazonadas. Priorizar qué automatizar primero. Y convertir ese hallazgo en una propuesta que la dirección apruebe."},{"type":"compare","dur":18,"eyeb":"La distinción clave","h2":"El proceso documentado no es el proceso real","colA":["AS-IS documentado","Lo que dice el manual","El diagrama oficial: pasos limpios, ordenados, como debería funcionar en teoría."],"colB":["AS-IS real","Lo que la gente hace","Los atajos, los reprocesos y el Excel paralelo que nadie anotó, pero que sostienen el día a día."],"cap":"El proceso documentado es la teoría limpia. El real incluye atajos, reprocesos y Excels paralelos. Automatizas el real.","narr":"Aquí está la distinción que más importa. El proceso documentado es la teoría: pasos limpios, como debería funcionar. El proceso real es otra cosa: los atajos, los reprocesos, el Excel paralelo que nadie anotó. Tú vas a automatizar el real, así que a ese tienes que descubrirlo."},{"type":"pieces","dur":16,"eyeb":"Cómo levantar el proceso","h2":"Tres técnicas que se complementan","pieces":[["🎤","Entrevista","Preguntas al que lo hace"],["👀","Observación","Miras cómo trabaja"],["📄","Evidencia","Revisas los documentos"]],"cap":"Para levantar bien un proceso: entrevistas a quien lo ejecuta, observas cómo trabaja y revisas la evidencia real.","narr":"Para levantar un proceso usas tres técnicas que se complementan. La entrevista: le preguntas a quien lo ejecuta cada día. La observación: te sientas al lado y miras cómo trabaja de verdad. Y la evidencia: revisas los archivos, correos y planillas que deja el proceso. Ninguna sola alcanza; juntas te dan la foto completa."},{"type":"spot","dur":16,"snum":"El error más común","sic":"🗣️","stitle":"Preguntar mal en la entrevista","stext":"Si preguntas cómo debería hacerse, te describen el manual. Pregunta cómo lo hiciste hoy, con el último caso concreto.","sex":"¿Qué hiciste con el último pedido que entró?","cap":"No preguntes cómo debería hacerse: te recitan el manual. Pregunta por el último caso concreto que resolvieron.","narr":"Cuidado con un error muy común. Si preguntas cómo debería hacerse, te describen el manual, no la realidad. En vez de eso, pregunta por el último caso concreto: qué hiciste con el último pedido que entró hoy. Con casos reales aparecen los atajos y las excepciones que nunca están en el diagrama."},{"type":"define","dur":15,"eyeb":"Cuando hay datos","h2":"Otra vía: el process mining","def":"El <b>process mining</b> reconstruye el proceso real a partir de los <b>registros que dejan tus sistemas</b> — quién hizo qué, cuándo y en qué orden.","cap":"El process mining reconstruye el proceso real a partir de los registros que dejan tus sistemas: quién hizo qué y cuándo.","narr":"Cuando el proceso vive en sistemas, hay otra vía muy potente: el process mining. En lugar de preguntar, reconstruye el proceso a partir de los registros que esos sistemas ya guardan: quién hizo qué, cuándo, y en qué orden. Los datos no maquillan la realidad como a veces lo hacen las personas."},{"type":"flow","dur":17,"eyeb":"Dónde mirar","h2":"Los cuellos de botella dejan huella","nodes":[["⏳","Esperas","Tareas que se estancan"],["🔁","Reprocesos","Lo que se rehace"],["✋","Traspasos","De una mano a otra"],["🐢","Manual","Lo lento y repetitivo"]],"cap":"Los cuellos de botella se ven en esperas largas, reprocesos, traspasos entre personas y pasos manuales lentos.","narr":"¿Dónde están los cuellos de botella? Dejan huella en cuatro lugares. Las esperas, donde una tarea se estanca por días. Los reprocesos, lo que se rehace por errores. Los traspasos, cada vez que el trabajo pasa de una mano a otra. Y lo manual, esos pasos lentos y repetitivos. Ahí es donde vale la pena mirar."},{"type":"define","dur":15,"eyeb":"El criterio del consultor","h2":"No todo lo molesto se debe automatizar","def":"Prioriza cruzando dos ejes: el <b>impacto</b> que genera resolverlo y la <b>complejidad</b> de automatizarlo. Lo demás es opinión.","cap":"Prioriza cruzando dos ejes: cuánto impacto genera resolverlo y qué tan complejo es automatizarlo.","narr":"Ahora, con la lista de oportunidades, aparece la tentación de automatizar lo que más molesta. Pero no todo lo molesto conviene. El criterio del consultor es cruzar dos ejes: el impacto que genera resolver algo, y la complejidad de automatizarlo. Todo lo demás es opinión."},{"type":"compare","dur":18,"eyeb":"La matriz de priorización","h2":"Por dónde empezar y qué dejar para después","colA":["Quick wins","Alto impacto, baja complejidad","Empieza por aquí. Resultado visible, esfuerzo bajo: así ganas confianza y presupuesto."],"colB":["Grandes proyectos","Alto impacto, alta complejidad","Valen la pena, pero planifícalos. No arranques por lo más difícil y largo."],"cap":"Empieza por los quick wins: alto impacto y baja complejidad. Los proyectos grandes valen, pero se planifican aparte.","narr":"Al cruzar esos ejes aparece el orden. Arriba a un lado, los quick wins: mucho impacto, poca complejidad. Empieza siempre por ahí, porque das un resultado visible con poco esfuerzo y ganas confianza. Los grandes proyectos, de alto impacto pero difíciles, valen la pena, pero se planifican aparte. No arranques por lo más largo."},{"type":"flow","dur":17,"eyeb":"El paso final","h2":"Del hallazgo al caso de negocio","nodes":[["🔍","Hallazgo","La oportunidad detectada"],["📐","Medición","Horas y errores hoy"],["💰","ROI","Ahorro contra costo"],["📊","Propuesta","Defendible ante la dirección"]],"cap":"Una oportunidad se vuelve propuesta midiendo horas y errores actuales, calculando el ROI y presentándolo con números.","narr":"El último paso convierte el hallazgo en una propuesta. Tomas la oportunidad detectada. Mides cuánto cuesta hoy: horas y errores. Calculas el retorno: cuánto ahorras contra lo que cuesta automatizarlo. Y lo presentas con números. Una oportunidad con ROI defendible se aprueba; una intuición, no."},{"type":"myth","dur":16,"eyeb":"A tener en cuenta","h2":"Tres cosas para no equivocarte","myths":[["El process mining no reemplaza hablar",", los datos dicen qué, la gente dice por qué"],["Más automatizable no es más prioritario",", primero mide el impacto"],["La IA no decide qué automatizar",", ordena tus datos, decides tú"]],"cap":"Los datos dicen qué pasa; la gente, por qué. Lo fácil no es lo prioritario. Y la IA ordena, pero decides tú.","narr":"Antes de cerrar, tres advertencias sanas. El process mining no reemplaza hablar con la gente: los datos te dicen qué pasa, las personas te dicen por qué. Que algo sea fácil de automatizar no lo hace prioritario: primero mide el impacto. Y la inteligencia artificial puede ordenar y resumir tus hallazgos, pero la decisión de qué automatizar es tuya."},{"type":"title","dur":15,"eyeb":"En resumen","h2":"Primero entiendes el proceso, después lo automatizas","sub":"Ya sabes levantar, medir y priorizar. En la práctica vas a armar tu propio pipeline de oportunidades.","cap":"Levantas el proceso real, mides con datos y priorizas por impacto. Sigue: armar tu pipeline de oportunidades.","narr":"Recapitulemos. Levantas el proceso real con entrevistas, observación y datos. Encuentras los cuellos de botella. Priorizas cruzando impacto y complejidad. Y conviertes el hallazgo en un caso de negocio con números. Primero entiendes, después automatizas. En la práctica vas a armar tu propio pipeline. Nos vemos ahí."}],"9":[{"type":"title","dur":18,"eyeb":"Bienvenido","h2":"Una buena idea mal documentada termina en caos","sub":"Detectaste una oportunidad. Ahora hay que convertirla en una solución clara que cualquiera pueda construir.","cap":"Detectar una oportunidad no basta: hay que traducirla en una solución documentada que el equipo pueda construir sin adivinar.","narr":"Bienvenido a esta lección. Ya sabes detectar procesos que vale la pena automatizar. Pero una buena idea, mal documentada, termina en caos: cada quien la entiende distinto. Aquí vas a aprender a traducir esa idea en una solución clara, y a llevar el proyecto de principio a fin."},{"type":"list","dur":16,"eyeb":"Qué vas a aprender","h2":"Cuatro cosas, en pocos minutos","items":[["1","PDD y SDD","los documentos que evitan el caos"],["2","El diseño TO-BE","cómo se ve el proceso mejorado"],["3","El ciclo de vida","del análisis al go-live"]],"cap":"En esta lección: qué son el PDD y el SDD, cómo diseñar el TO-BE, el ciclo de vida del proyecto y cómo validar antes de salir a producción.","narr":"Vas a entender cuatro cosas: qué son el PDD y el SDD y para qué sirven, cómo se diseña el estado mejorado de un proceso, cuáles son las fases de un proyecto de automatización, y cómo validar con el negocio antes de salir a producción."},{"type":"compare","dur":18,"eyeb":"Los dos documentos clave","h2":"PDD y SDD responden preguntas distintas","colA":["PDD","El qué","Process Definition Document. Describe el proceso: qué hace, con qué reglas, paso a paso. Lo escribe el analista con el negocio."],"colB":["SDD","El cómo","Solution Design Document. Describe la solución técnica: cómo se va a construir. Lo escribe quien diseña la automatización."],"cap":"El PDD documenta QUÉ hace el proceso y con qué reglas. El SDD documenta CÓMO se va a construir la solución técnica.","narr":"Empecemos por los dos documentos que evitan el caos. El PDD, o Process Definition Document, describe el qué: cómo funciona el proceso, con qué reglas, paso a paso. El SDD, o Solution Design Document, describe el cómo: la forma técnica de construirlo. Uno es el mapa del proceso; el otro, el plano de la solución."},{"type":"pieces","dur":16,"eyeb":"Anatomía del PDD","h2":"Un buen PDD tiene cuatro partes","pieces":[["🎯","Objetivo","Qué resuelve y por qué"],["👣","Pasos","El proceso, acción por acción"],["📏","Reglas","Qué decidir en cada caso"],["⚠️","Excepciones","Qué hacer cuando algo falla"]],"cap":"Un PDD sólido cubre: objetivo del proceso, pasos detallados, reglas de negocio y qué hacer ante las excepciones.","narr":"Un buen PDD tiene cuatro partes. El objetivo: qué resuelve y por qué importa. Los pasos: el proceso descrito acción por acción, sin dar nada por obvio. Las reglas de negocio: qué decidir en cada situación. Y las excepciones: qué hacer cuando algo se sale de lo normal. Si esas cuatro están claras, quien construya no tendrá que adivinar."},{"type":"define","dur":15,"eyeb":"El concepto central","h2":"Antes de automatizar, diseña el TO-BE","def":"El <b>TO-BE</b> es cómo <b>debería</b> funcionar el proceso una vez mejorado, en contraste con el <b>AS-IS</b>, que es cómo funciona hoy con todos sus defectos.","cap":"El AS-IS es el proceso como es hoy; el TO-BE es como debería quedar, ya rediseñado y libre de los pasos inútiles.","narr":"Aquí va una idea central. El AS-IS es cómo funciona el proceso hoy, con todos sus rodeos y defectos. El TO-BE es cómo debería funcionar una vez mejorado. La regla de oro: nunca automatices el AS-IS tal cual. Primero rediseñas, y después construyes."},{"type":"spot","dur":16,"snum":"La trampa más común","sic":"🚫","stitle":"No automatices el desorden","stext":"Si automatizas un proceso torpe, obtienes un proceso torpe... pero más rápido. El error se multiplica, no desaparece.","sex":"primero ordena · después automatiza","cap":"Automatizar un proceso desordenado solo lo vuelve un desorden más rápido: primero simplificas, luego automatizas.","narr":"Cuidado con la trampa más común. Si automatizas un proceso torpe, no lo arreglas: obtienes lo mismo, pero más rápido. El error se multiplica en lugar de desaparecer. Por eso el TO-BE va primero: eliminas pasos inútiles, simplificas las reglas, y recién entonces automatizas lo que de verdad vale la pena."},{"type":"flow","dur":17,"eyeb":"Del AS-IS al TO-BE","h2":"Rediseñar es quitar, no solo mover","nodes":[["📋","AS-IS","El proceso actual"],["✂️","Depura","Quita pasos inútiles"],["🧠","Añade criterio","Dónde entra la IA"],["✨","TO-BE","El proceso mejorado"]],"cap":"Se pasa del AS-IS al TO-BE depurando pasos que no aportan y sumando IA donde aporta criterio, no en todos lados.","narr":"Veamos cómo se pasa de uno al otro. Tomas el proceso actual, el AS-IS. Le quitas los pasos que no aportan valor. Identificas dónde la inteligencia artificial suma criterio de verdad, no en todos lados. Y con eso llegas al TO-BE, el proceso mejorado. Rediseñar es, sobre todo, quitar; no solo mover cajas de lugar."},{"type":"flow","dur":18,"eyeb":"El ciclo de vida","h2":"Todo proyecto recorre las mismas fases","nodes":[["🔍","Análisis","Entender y documentar"],["📐","Diseño","PDD, SDD y TO-BE"],["🛠️","Desarrollo","Construir y probar"],["🚀","Producción","Salir y estabilizar"]],"cap":"El proyecto va de análisis (entender) a diseño (documentar), desarrollo (construir) y producción (salir a operar).","narr":"Con los documentos y el TO-BE listos, el proyecto avanza por fases. Análisis: entender y documentar el proceso. Diseño: el PDD, el SDD y el TO-BE que acabamos de ver. Desarrollo: construir la automatización y probarla. Y producción: salir a operar. Cada fase entrega algo concreto a la siguiente; saltarse una se paga caro después."},{"type":"define","dur":15,"eyeb":"La prueba con el negocio","h2":"El UAT es el examen final del proyecto","def":"El <b>UAT</b> (User Acceptance Testing) es la prueba donde el <b>negocio</b>, no el equipo técnico, valida que la solución hace lo que se pidió, con casos reales.","cap":"En el UAT es el usuario del negocio quien prueba la solución con casos reales y confirma que resuelve lo que se pidió.","narr":"Antes de salir a producción hay un examen final: el UAT, o prueba de aceptación del usuario. Aquí no prueba el equipo técnico, sino el negocio: la persona que usa el proceso todos los días. Con casos reales, confirma que la solución hace lo que pidió. Si el negocio no aprueba, no se sale. Así de simple."},{"type":"list","dur":17,"eyeb":"Criterios de aceptación","h2":"Aprobar no puede ser una opinión","items":[["✅","Medibles","Se cumplen o no, sin ambigüedad"],["📝","Acordados antes","Se definen al inicio, no al final"],["🎯","Sobre el resultado","Qué debe lograr, no cómo"]],"cap":"Los criterios de aceptación deben ser medibles, acordados desde el inicio y centrados en el resultado esperado, no en gustos.","narr":"Para que el UAT no dependa del humor de nadie, defines criterios de aceptación. Tienen que ser medibles: se cumplen o no, sin discusión. Acordados desde el inicio, no inventados al final. Y centrados en el resultado esperado, no en gustos personales. Un criterio claro convierte aprobar en un hecho, no en una opinión."},{"type":"spot","dur":16,"snum":"Después del go-live","sic":"🩺","stitle":"El hypercare","stext":"Los primeros días en producción se vigila de cerca: fallos reales aparecen con datos reales. Es parte del proyecto, no un extra.","sex":"acompañar · corregir · estabilizar","cap":"Tras el go-live viene el hypercare: un periodo de vigilancia cercana para corregir lo que solo aparece con datos reales.","narr":"El proyecto no termina el día que sale a producción. Justo después viene el hypercare: unos días de vigilancia cercana. Con datos reales aparecen situaciones que ninguna prueba anticipó. Acompañas, corriges y estabilizas. Planéalo desde el inicio: el hypercare es parte del proyecto, no un favor que haces al final."},{"type":"myth","dur":16,"eyeb":"A tener en cuenta","h2":"Tres cosas para no tropezar","myths":[["El papeleo no frena",", te ahorra retrabajo caro"],["La IA no diseña por ti",", ordena tu criterio, no lo reemplaza"],["Documentar no es de una vez",", el documento vive y se actualiza"]],"cap":"Documentar no es burocracia: evita retrabajo. La IA agiliza, no decide el diseño. Y el PDD es un documento vivo, no una foto.","narr":"Tres advertencias sanas antes de cerrar. Documentar no es burocracia que frena: te ahorra retrabajo carísimo más adelante. La inteligencia artificial ayuda a redactar y ordenar, pero no diseña la solución por ti: tu criterio manda. Y el documento no se escribe una sola vez: vive y se actualiza mientras el proceso cambia."},{"type":"pieces","dur":14,"eyeb":"Recapitulemos","h2":"El camino completo, en cuatro hitos","pieces":[["📄","Documenta","PDD y SDD"],["✨","Rediseña","El TO-BE"],["🔄","Ejecuta","El ciclo de vida"],["✅","Valida","UAT y go-live"]],"cap":"Recap: documenta con PDD y SDD, rediseña con el TO-BE, ejecuta el ciclo de vida y valida con UAT antes del go-live.","narr":"Recapitulemos el camino. Documentas el qué y el cómo con el PDD y el SDD. Rediseñas el proceso con el TO-BE antes de tocar nada. Ejecutas las fases del ciclo de vida en orden. Y validas con el negocio en el UAT antes del go-live. Cuatro hitos que convierten una idea en una solución que aguanta."},{"type":"title","dur":15,"eyeb":"En resumen","h2":"Una solución bien diseñada se construye una vez","sub":"Ya sabes documentar, rediseñar y llevar el proyecto de punta a punta. Sigue: aplicarlo en un caso real.","cap":"Documentar bien y rediseñar antes de automatizar hace que la solución se construya una vez y funcione: ahora toca aplicarlo.","narr":"Eso es el diseño funcional. Una solución bien documentada y bien rediseñada se construye una vez, y funciona; una improvisada se rehace tres veces. Ya sabes redactar los documentos, diseñar el TO-BE y llevar el proyecto de punta a punta. Ahora sigue lo importante: aplicarlo en un caso real. Nos vemos en la práctica."}],"10":[{"type":"title","dur":18,"eyeb":"Bienvenido","h2":"Antes de automatizar un proceso, hay que dibujarlo bien","sub":"Si negocio y quien automatiza no hablan el mismo idioma, el proyecto se tuerce desde el inicio.","cap":"Antes de automatizar un proceso hay que dibujarlo con claridad, en un idioma que todos entiendan.","narr":"Bienvenido a esta lección. Antes de automatizar cualquier proceso, hay que dibujarlo con claridad. Cuando el negocio y quien automatiza no hablan el mismo idioma, el proyecto se tuerce desde el arranque. Para eso existe BPMN, y hoy lo vas a entender."},{"type":"list","dur":16,"eyeb":"Qué vas a aprender","h2":"Tres cosas, en pocos minutos","items":[["1","Qué es BPMN","y por qué es la lengua franca del proceso"],["2","Sus piezas base","eventos, tareas y compuertas"],["3","Un proceso completo","modelado y listo para automatizar"]],"cap":"En esta lección: qué es BPMN, sus piezas base y cómo se ve un proceso completo listo para automatizar.","narr":"En los próximos minutos vas a entender tres cosas. Qué es BPMN y por qué se volvió la lengua franca de los procesos. De qué piezas básicas está hecho. Y cómo se ve un proceso completo, modelado y listo para automatizar."},{"type":"define","dur":16,"eyeb":"El concepto base","h2":"Primero, qué es BPMN","def":"<b>BPMN 2.0</b> es un estándar visual para dibujar procesos con símbolos fijos, de modo que <b>negocio y tecnología</b> lean exactamente lo mismo en el mismo diagrama.","cap":"BPMN 2.0 es un estándar visual con símbolos fijos para que negocio y tecnología lean lo mismo.","narr":"Empecemos por la base. BPMN, en su versión dos punto cero, es un estándar visual para dibujar procesos. Su gracia es que usa símbolos fijos, con un significado acordado. Así el área de negocio y quien lo va a automatizar leen exactamente lo mismo en el mismo diagrama."},{"type":"pieces","dur":17,"eyeb":"La anatomía","h2":"Casi todo BPMN se arma con cuatro piezas","pieces":[["⭕","Evento","Algo que pasa: inicio o fin"],["🔲","Tarea","Un trabajo que se hace"],["🔷","Compuerta","Una decisión o bifurcación"],["➡️","Flujo","La flecha que conecta todo"]],"cap":"BPMN se arma con eventos (algo pasa), tareas (un trabajo), compuertas (una decisión) y flujos (las flechas).","narr":"Aunque BPMN tiene muchos símbolos, casi todo se arma con cuatro piezas. El evento: algo que ocurre, como el inicio o el fin. La tarea: un trabajo que se realiza. La compuerta: una decisión que bifurca el camino. Y el flujo: la flecha que conecta todo en orden."},{"type":"spot","dur":15,"snum":"Pieza 1 de 3","sic":"⭕","stitle":"Los eventos","stext":"Marcan que algo sucede. El círculo fino inicia el proceso; el grueso lo termina.","sex":"Llega un pedido · se vence un plazo · termina el flujo","cap":"Los eventos marcan que algo sucede: el círculo fino inicia el proceso y el grueso lo termina.","narr":"Veamos las tres piezas clave, una por una. Primero, los eventos: marcan que algo sucede. Un círculo de línea fina inicia el proceso, por ejemplo, cuando llega un pedido. Uno de línea gruesa lo termina. Entre medio pueden aparecer eventos intermedios, como el vencimiento de un plazo."},{"type":"spot","dur":15,"snum":"Pieza 2 de 3","sic":"🔲","stitle":"Las tareas","stext":"Cada rectángulo es un trabajo concreto. Un pequeño ícono indica quién lo hace: persona o sistema.","sex":"Revisar la factura · enviar el correo · registrar el dato","cap":"Cada tarea es un rectángulo: un trabajo concreto, hecho por una persona o por un sistema.","narr":"Segunda pieza, las tareas. Cada rectángulo es un trabajo concreto: revisar una factura, enviar un correo, registrar un dato. Un pequeño ícono dentro te dice quién la ejecuta: una persona o un sistema. Ese detalle importa cuando decides qué parte se puede automatizar."},{"type":"spot","dur":16,"snum":"Pieza 3 de 3","sic":"🔷","stitle":"Las compuertas","stext":"El rombo decide el camino. Según una condición, el flujo va por una rama o por otra.","sex":"¿Monto mayor a mil? · ¿cliente nuevo? · ¿aprobado o rechazado?","cap":"La compuerta es un rombo que decide el camino: según una condición, el flujo va por una rama u otra.","narr":"Tercera pieza, las compuertas, dibujadas como un rombo. Aquí el proceso decide. Según una condición, el flujo toma una rama u otra. ¿El monto supera los mil pesos? ¿El cliente es nuevo? Estas preguntas, bien puestas, son las que hacen que un proceso refleje la realidad y no una versión ideal."},{"type":"compare","dur":18,"eyeb":"Las compuertas más usadas","h2":"No todas las compuertas deciden igual","colA":["Exclusiva","Elige un solo camino","Toma una sola rama según la condición. O una, o la otra. Es la decisión de siempre."],"colB":["Paralela","Abre varios a la vez","Dispara todas las ramas al mismo tiempo y luego espera a que terminen. Sin condición."],"cap":"Compuerta exclusiva: elige un solo camino. Compuerta paralela: dispara varias ramas a la vez y las espera.","narr":"Conviene distinguir dos compuertas. La exclusiva elige un solo camino: o una rama, o la otra, según la condición. Es la decisión de toda la vida. La paralela es distinta: abre varias ramas al mismo tiempo, sin condición, y luego espera a que todas terminen. Confundirlas cambia por completo el resultado."},{"type":"flow","dur":18,"eyeb":"Quién hace qué","h2":"Pools y lanes: cada actor en su carril","nodes":[["🏊","Pool","El proceso completo"],["🛣️","Lane","Un actor: área o sistema"],["👤","Ventas","Su tarea"],["🤖","Sistema","Su tarea"]],"cap":"El pool es todo el proceso; cada lane es un actor. Así se ve, de un vistazo, quién hace cada tarea.","narr":"Un proceso real involucra a varios. Para mostrarlo, BPMN usa carriles. El pool es el proceso completo, la piscina. Dentro, cada lane, o carril, es un actor: un área o un sistema. Colocas cada tarea en el carril de quien la hace. Así, de un vistazo, se ve quién es responsable de qué."},{"type":"flow","dur":19,"eyeb":"Un proceso real","h2":"Aprobación de una solicitud, de inicio a fin","nodes":[["⭕","Inicio","Llega la solicitud"],["🔲","Revisar","Se valida el monto"],["🔷","¿Aprobado?","Sí o no"],["⭕","Fin","Se notifica"]],"cap":"Ejemplo: llega la solicitud, se revisa el monto, la compuerta decide aprobado o no, y se notifica el resultado.","narr":"Juntemos todo en un caso. Llega una solicitud, ese es el evento de inicio. Una tarea revisa el monto. Una compuerta pregunta si se aprueba: si sí, se registra; si no, se rechaza. En ambos casos se notifica al solicitante y el proceso termina. Piezas simples, proceso completo."},{"type":"chips","dur":15,"eyeb":"Con qué se dibuja","h2":"Herramientas para modelar en BPMN","chips":[["✏️","bpmn.io"],["🧩","Camunda"],["🔷","Bizagi"],["📐","Lucidchart"],["➕","y más"]],"cap":"Se modela en herramientas visuales como bpmn.io, Camunda, Bizagi o Lucidchart. Todas usan los mismos símbolos.","narr":"Todo esto se dibuja en herramientas visuales, como bpmn.io, Camunda, Bizagi o Lucidchart. Como BPMN es un estándar, los símbolos son iguales en todas. Aprendes la notación una vez y la puedes leer en cualquier lugar donde trabajes."},{"type":"myth","dur":17,"eyeb":"A tener en cuenta","h2":"Tres cosas que conviene entender bien","myths":[["No es un dibujo bonito",", es un acuerdo entre negocio y tecnología"],["Un buen modelo no lo hace la IA sola",", ella ordena, tú validas la realidad"],["Modelar no es automatizar",", primero el proceso claro, después el bot"]],"cap":"BPMN es un acuerdo, no un adorno. La IA ordena el borrador, tú validas. Y modelar bien va antes de automatizar.","narr":"Un punto importante antes de cerrar. Un diagrama BPMN no es un dibujo bonito: es un acuerdo entre negocio y tecnología. La inteligencia artificial puede ordenarte un primer borrador, pero eres tú quien valida que refleje la realidad. Y modelar no es automatizar: primero el proceso claro, después el bot."},{"type":"title","dur":15,"eyeb":"En resumen","h2":"Un buen BPMN es el plano de tu automatización","sub":"Ya sabes leer eventos, tareas y compuertas. Sigue: modelar un proceso tuyo y prepararlo para automatizar.","cap":"Un buen BPMN es el plano de tu automatización. Sigue: modelar un proceso propio y prepararlo para el bot.","narr":"Recapitulemos. BPMN dibuja procesos con eventos, tareas y compuertas, y los ordena por carriles según quién hace qué. Ese diagrama es el plano de tu automatización. Ya sabes leerlo; ahora sigue lo mejor: modelar un proceso tuyo y prepararlo para el bot. Nos vemos en la práctica."}],"11":[{"type":"title","dur":18,"eyeb":"Bienvenido","h2":"Hay sistemas viejos que no tienen forma de conectarse por fuera","sub":"Sin API, sin integración. Alguien los opera a mano, clic por clic, todos los días.","cap":"Muchos sistemas empresariales no tienen API. El RPA los opera como lo haría una persona: por la pantalla.","narr":"Bienvenido a esta lección. En muchas empresas hay sistemas viejos que no ofrecen ninguna forma de conectarse por fuera. Nadie los integra: alguien los opera a mano, clic por clic, todos los días. El RPA nace justo para eso: un robot que usa la pantalla igual que tú."},{"type":"list","dur":16,"eyeb":"Qué vas a aprender","h2":"Tres ideas, en pocos minutos","items":[["1","Qué es el RPA","y de qué piezas está hecho"],["2","Cómo ve la pantalla","selectores que no se rompen"],["3","Atendido o desatendido","cuándo usar cada uno"]],"cap":"En esta lección: qué es el RPA y su arquitectura, cómo identifica lo que hay en pantalla, y bots atendidos frente a desatendidos.","narr":"Vas a entender tres cosas. Qué es el RPA y de qué piezas se compone. Cómo hace un robot para reconocer lo que hay en pantalla sin equivocarse. Y la diferencia entre un bot atendido y uno desatendido, para saber cuál te conviene."},{"type":"define","dur":16,"eyeb":"El concepto base","h2":"Primero, qué es el RPA","def":"El <b>RPA</b> es un software que imita a una persona usando la computadora: <b>abre programas, hace clic, copia datos y escribe</b>, siguiendo los pasos que le enseñaste.","cap":"El RPA es un robot de software que opera aplicaciones como lo haría una persona: clics, teclas y datos por la pantalla.","narr":"Empecemos por la base. RPA significa automatización robótica de procesos. Es un software que imita a una persona usando la computadora: abre programas, hace clic, copia datos y escribe en los campos. No entiende el sistema por dentro; lo opera por fuera, tal como lo harías tú."},{"type":"pieces","dur":17,"eyeb":"La arquitectura","h2":"Toda plataforma de RPA tiene tres piezas","pieces":[["🎬","Studio","Donde diseñas el robot"],["🤖","Robot","El que ejecuta la tarea"],["🎛️","Orchestrator","Quien lo agenda y vigila"]],"cap":"Studio para diseñar el proceso, el Robot que lo ejecuta, y el Orchestrator que lo agenda, reparte y monitorea.","narr":"Toda plataforma de RPA se arma con tres piezas. El Studio, donde diseñas el proceso paso a paso. El robot, que es quien ejecuta esa tarea en la máquina. Y el Orchestrator, el panel central que agenda ejecuciones, reparte trabajo y vigila que todo corra bien."},{"type":"compare","dur":18,"eyeb":"Dónde encaja","h2":"El RPA no compite con las APIs: las complementa","colA":["Integración por API","La vía preferida","Cuando el sistema tiene API, conéctate por ahí: es más rápido, estable y limpio."],"colB":["RPA por pantalla","El plan B necesario","Cuando no hay API, el robot opera la interfaz. Llega donde la integración no puede."],"cap":"Si hay API, úsala: es más estable. El RPA es para los sistemas cerrados donde no queda otra que ir por la pantalla.","narr":"Aquí conviene un matiz honesto. Si un sistema tiene API, conéctate por ahí: es más rápido, estable y limpio. El RPA no reemplaza eso. Su lugar es el otro: los sistemas cerrados, sin integración posible, donde la única puerta es la pantalla. Ahí es insustituible."},{"type":"spot","dur":17,"snum":"El corazón del RPA","sic":"🎯","stitle":"El selector","stext":"Es la dirección con la que el robot encuentra un botón o un campo en la pantalla, aunque la ventana cambie de lugar.","sex":"identifica · apunta · hace clic","cap":"El selector es la referencia que usa el robot para localizar cada botón o campo exacto en la pantalla antes de actuar.","narr":"Aquí está el corazón del RPA: el selector. Es la dirección con la que el robot encuentra un botón o un campo específico en la pantalla. Gracias a él sabe dónde hacer clic, aunque la ventana se abra en otro lugar. Si el selector falla, el robot se pierde."},{"type":"compare","dur":18,"eyeb":"Por qué se rompen los bots","h2":"Un selector frágil contra uno robusto","colA":["Frágil","Se ata a lo que cambia","Depende de la posición o de un texto que varía. Cualquier cambio mínimo y el robot deja de encontrarlo."],"colB":["Robusto","Se ancla a lo estable","Usa atributos fijos y anclas cercanas. Aguanta cambios de diseño y sigue funcionando."],"cap":"El selector frágil se ata a la posición o a textos variables y se rompe fácil. El robusto se ancla a atributos estables.","narr":"La razón número uno por la que un bot se rompe es un selector frágil. Ese se ata a lo que cambia: una posición en pantalla, un texto variable. Cualquier ajuste mínimo y falla. El robusto se ancla a atributos fijos y a elementos cercanos estables. Ese aguanta."},{"type":"flow","dur":18,"eyeb":"Un ejemplo real","h2":"Cargar una factura en el sistema contable","nodes":[["📥","Detonante","Llega la factura"],["📂","Lee","Abre el sistema"],["⌨️","Captura","Escribe los datos"],["✅","Confirma","Guarda y registra"]],"cap":"Ejemplo: llega una factura, el robot abre el sistema contable, captura los datos en cada campo y guarda el registro.","narr":"Veámoslo en un caso típico. Llega una factura por correo. El robot abre el sistema contable, ubica cada campo con sus selectores y escribe los datos uno por uno. Al final guarda y registra la operación. La misma captura tediosa que hacía una persona, ahora sin errores de dedo."},{"type":"pieces","dur":16,"eyeb":"Con qué trabaja por dentro","h2":"El robot maneja datos con cuatro elementos","pieces":[["📦","Variables","Guardan un dato del momento"],["📨","Argumentos","Datos que entran y salen"],["🔀","Condiciones","Deciden el camino a seguir"],["🔁","Bucles","Repiten sobre una lista"]],"cap":"Por dentro el robot usa variables, argumentos que entran y salen, condiciones que ramifican y bucles que recorren listas.","narr":"Por dentro, el robot maneja datos con cuatro elementos. Las variables guardan un dato del momento, como el total de una factura. Los argumentos pasan información de entrada y salida entre procesos. Las condiciones deciden qué camino tomar. Y los bucles repiten los mismos pasos sobre una lista entera."},{"type":"compare","dur":18,"eyeb":"Los dos tipos de bot","h2":"Atendido y desatendido resuelven cosas distintas","colA":["Atendido","Trabaja contigo","Corre en tu equipo y lo disparas tú, cuando lo necesitas. Te asiste en una tarea puntual."],"colB":["Desatendido","Trabaja solo","Corre en un servidor sin nadie presente. Se agenda y procesa volumen de fondo, día y noche."],"cap":"El bot atendido lo disparas tú y te asiste en el momento. El desatendido corre solo en un servidor, agendado y sin supervisión.","narr":"Hay dos tipos de bot y resuelven cosas distintas. El atendido corre en tu equipo y lo disparas tú, cuando lo necesitas: te asiste en el momento. El desatendido vive en un servidor, sin nadie presente. Se agenda y procesa grandes volúmenes de fondo, día y noche."},{"type":"chips","dur":15,"eyeb":"Dónde se construye","h2":"Las plataformas más usadas de RPA","chips":[["🟠","UiPath"],["🔵","Automation Anywhere"],["🟢","Power Automate"],["🔴","Blue Prism"],["➕","y más"]],"cap":"El RPA se construye en plataformas como UiPath, Automation Anywhere, Power Automate o Blue Prism, entre otras.","narr":"Todo esto se construye en plataformas dedicadas. Las más usadas son UiPath, Automation Anywhere, Power Automate y Blue Prism. Cambian los nombres y los botones, pero los conceptos que viste hoy son los mismos en todas. Aprende la lógica y te mueves en cualquiera."},{"type":"myth","dur":17,"eyeb":"A tener en cuenta","h2":"Tres cosas para no llevarte una sorpresa","myths":[["No es plug and play",", un bot se diseña, se prueba y se mantiene"],["No aguanta el caos",", si el proceso es un desorden, el robot lo hereda"],["No se olvida y ya",", si el sistema cambia, hay que ajustarlo"]],"cap":"El RPA no es instalar y olvidar: se diseña, prueba y mantiene. No arregla procesos desordenados y se ajusta cuando el sistema cambia.","narr":"Antes de cerrar, tres advertencias honestas. El RPA no es instalar y listo: un bot se diseña, se prueba y se mantiene. No aguanta el caos: si el proceso está desordenado, el robot hereda ese desorden. Y cuando el sistema cambia, alguien tiene que ajustarlo."},{"type":"title","dur":15,"eyeb":"En resumen","h2":"El RPA opera la pantalla; tú pones el proceso y el criterio","sub":"Ya sabes qué es, cómo ve la pantalla y qué tipos hay. Sigue: diseñar tu primer robot.","cap":"El RPA es un robot que opera aplicaciones por la pantalla, con selectores robustos. Sigue: construir tu primer bot.","narr":"Recapitulemos. El RPA es un robot que opera aplicaciones por la pantalla, apoyado en selectores robustos, y puede ser atendido o desatendido. Es la pieza que llega donde las APIs no alcanzan. Ya tienes el mapa. Ahora sigue lo mejor: diseñar tu primer robot. Nos vemos en la práctica."}],"12":[{"type":"title","dur":18,"eyeb":"Bienvenido","h2":"Casi todo tu trabajo empieza con datos atrapados en algún lado","sub":"En un PDF, en un Excel, en una página web. Esta lección trata de liberarlos y ponerlos a trabajar.","cap":"La mayoría de los procesos arrancan con datos atrapados en PDFs, hojas de cálculo y páginas web. Aquí aprendes a liberarlos.","narr":"Bienvenido a esta lección. Piensa en cuántas veces el trabajo empieza con datos encerrados en un PDF, una hoja de cálculo o una página web. Alguien los copia a mano, uno por uno. Aquí vas a entender cómo automatizar esa extracción y hacerla confiable."},{"type":"list","dur":16,"eyeb":"Qué vas a aprender","h2":"Cuatro ideas, en pocos minutos","items":[["1","Automatizar documentos","leer y escribir Excel, CSV y PDF"],["2","Limpiar y transformar","el proceso ETL, sin misterio"],["3","Web scraping","extraer datos de páginas, con responsabilidad"]],"cap":"En esta lección: automatizar documentos, limpiar datos con ETL y extraer información web con scraping responsable.","narr":"Vas a entender cuatro cosas: cómo automatizar la lectura y escritura de documentos, cómo limpiar y transformar datos con el proceso ETL, cómo extraer información de páginas web con scraping, y cuándo conviene usar una API en lugar de raspar."},{"type":"pieces","dur":16,"eyeb":"Los formatos del día a día","h2":"Tres formatos que vas a manejar todo el tiempo","pieces":[["📊","Excel","Ordenado en filas y columnas"],["📄","CSV","Texto plano, ligero y universal"],["📕","PDF","Diseñado para leerse, no para extraerse"]],"cap":"Excel: filas y columnas. CSV: texto plano y universal. PDF: hecho para leer, difícil de extraer.","narr":"Empecemos por los formatos que verás siempre. El Excel guarda datos ordenados en filas y columnas. El CSV es lo mismo, pero en texto plano: ligero y compatible con todo. Y el PDF: pensado para que una persona lo lea, no para sacarle datos con facilidad. Ese último es el que más cuesta."},{"type":"spot","dur":16,"snum":"El reto del PDF","sic":"📕","stitle":"No todos los PDF son iguales","stext":"Uno con texto seleccionable se lee directo. Uno escaneado es una imagen: ahí necesitas OCR para reconocer las letras.","sex":"texto real · escaneado · OCR","cap":"Un PDF con texto se lee directo. Un PDF escaneado es una imagen y necesita OCR para reconocer las letras.","narr":"El PDF merece una pausa. Si tiene texto seleccionable, puedes leerlo directo. Pero si es un documento escaneado, en realidad es una imagen: las letras son píxeles, no texto. Ahí necesitas OCR, la tecnología que reconoce caracteres. Saber distinguir uno de otro te evita horas de frustración."},{"type":"define","dur":16,"eyeb":"El concepto central","h2":"Qué es ETL","def":"El <b>ETL</b> son tres pasos: <b>Extraer</b> los datos de su origen, <b>Transformarlos</b> para dejarlos limpios y ordenados, y <b>Cargarlos</b> donde los vas a usar.","cap":"ETL = Extraer los datos, Transformarlos para limpiarlos y Cargarlos donde los usarás. Tres pasos, un dato confiable.","narr":"Los datos casi nunca vienen listos para usar. Por eso existe el ETL, que son tres pasos: extraer los datos de donde estén, transformarlos para dejarlos limpios y ordenados, y cargarlos en el destino donde los vas a usar. Extraer, transformar, cargar. Ese es el camino de un dato confiable."},{"type":"list","dur":17,"eyeb":"La T de transformar","h2":"Limpiar datos es sobre todo esto","items":[["🧹","Normalizar","Un mismo formato para fechas, montos y textos"],["♊","Deduplicar","Quitar los registros repetidos"],["✅","Validar","Confirmar que cada dato tiene sentido"]],"cap":"Transformar datos es normalizar formatos, eliminar duplicados y validar que cada dato tenga sentido.","narr":"El paso que más trabajo da es la transformación. Limpiar datos es, sobre todo, tres cosas. Normalizar: que las fechas, los montos y los textos sigan un mismo formato. Deduplicar: quitar los registros repetidos que ensucian todo. Y validar: confirmar que cada dato tiene sentido antes de usarlo. Datos sucios producen decisiones equivocadas."},{"type":"flow","dur":18,"eyeb":"Un ejemplo real","h2":"De cien facturas en PDF a una tabla lista","nodes":[["📥","Extrae","Lee los cien PDF"],["🔎","Estructura","Saca fecha, monto, proveedor"],["🧹","Limpia","Normaliza y quita repetidos"],["📊","Carga","Todo en una sola hoja"]],"cap":"Ejemplo ETL: lee cien facturas en PDF, extrae los campos clave, los limpia y los deja en una tabla ordenada.","narr":"Veámoslo con un caso. Te llegan cien facturas en PDF cada mes. El flujo las lee todas, extrae de cada una la fecha, el monto y el proveedor, normaliza los formatos y elimina las repetidas. Al final tienes una sola tabla ordenada, lista para analizar. Lo que tomaba un día, ahora toma minutos."},{"type":"define","dur":15,"eyeb":"Datos que viven en la web","h2":"Qué es el web scraping","def":"El <b>web scraping</b> es extraer datos de páginas web de forma automática: un programa abre la página, localiza la información y la guarda estructurada.","cap":"Web scraping es extraer datos de páginas web con un programa que las abre, ubica la información y la guarda ordenada.","narr":"A veces el dato no está en un archivo tuyo, sino en una página web. Ahí entra el web scraping: extraer esa información de forma automática. Un programa abre la página, localiza los datos que te interesan y los guarda estructurados. Es como copiar y pegar, pero a gran escala y sin manos."},{"type":"pieces","dur":17,"eyeb":"Los retos del scraping","h2":"Cuatro obstáculos que vas a encontrar","pieces":[["🎯","Selectores","Cómo señalar el dato exacto"],["📃","Paginación","Recorrer varias páginas de resultados"],["⚡","Contenido dinámico","Datos que cargan con el navegador"],["🚧","Bloqueos","Sitios que detectan a los robots"]],"cap":"Scraping en la práctica: usar selectores, recorrer la paginación, manejar contenido dinámico y sortear bloqueos.","narr":"Raspar suena simple, pero tiene sus retos. Los selectores: cómo le indicas al programa cuál es el dato exacto. La paginación: recorrer varias páginas de resultados. El contenido dinámico: datos que solo aparecen cuando el navegador ejecuta código. Y los bloqueos: sitios que detectan robots y los frenan. Conocerlos te ahorra sorpresas."},{"type":"compare","dur":18,"eyeb":"La decisión clave","h2":"Antes de raspar, pregunta si hay una API","colA":["API","La puerta oficial","El sitio te entrega los datos ya estructurados y con permiso. Estable, limpio y pensado para esto."],"colB":["Scraping","La puerta de atrás","Extraes de la página visible. Útil cuando no hay API, pero frágil: si cambian el diseño, se rompe."],"cap":"API: la vía oficial, estable y con permiso. Scraping: útil cuando no hay API, pero frágil ante cambios del sitio.","narr":"Antes de raspar, hazte una pregunta clave: ¿existe una API? Una API es la puerta oficial: el sitio te entrega los datos ya estructurados y con permiso, de forma estable. El scraping es la puerta de atrás: extraes de la página visible. Sirve cuando no hay API, pero es frágil, porque si cambian el diseño, se rompe. Siempre revisa primero si hay API."},{"type":"myth","dur":17,"eyeb":"A tener en cuenta","h2":"Tres cosas para hacerlo con responsabilidad","myths":[["No todo se puede raspar",", revisa el robots.txt y los términos del sitio"],["No es gratis para el sitio",", cada visita consume sus recursos, no lo satures"],["No confíes ciegamente en el dato",", extraído no es lo mismo que verificado"]],"cap":"Scraping responsable: respeta robots.txt y los términos, no satures el sitio, y valida los datos antes de confiar en ellos.","narr":"Antes de cerrar, tres advertencias honestas. No todo se puede raspar: revisa el archivo robots punto txt y los términos de servicio del sitio. No es gratis para nadie: cada visita consume recursos del servidor, así que no lo satures con miles de peticiones. Y un dato extraído no es un dato verificado: valida siempre antes de confiar. La técnica no te exime del criterio."},{"type":"chips","dur":15,"eyeb":"Con qué se hace","h2":"Herramientas para extraer y transformar","chips":[["🐼","Pandas"],["🤖","RPA"],["🌐","Scrapers"],["🧠","IA"],["➕","y más"]],"cap":"Esto se construye con librerías de datos como Pandas, bots de RPA, herramientas de scraping y modelos de IA para casos difíciles.","narr":"¿Con qué se hace todo esto? Con librerías de datos como Pandas para transformar, con bots de RPA que leen documentos y pantallas, con herramientas de scraping para la web, y cada vez más con inteligencia artificial para los casos donde el dato viene desordenado. La lógica que viste es la misma; solo cambia la herramienta."},{"type":"title","dur":15,"eyeb":"En resumen","h2":"Extraer, limpiar y estructurar: el trabajo invisible que sostiene todo","sub":"Ya conoces el camino del dato. Sigue: verlo funcionar y armar tu propio flujo de extracción.","cap":"Extraer, limpiar y estructurar datos es la base de toda automatización. Sigue: verlo en acción y practicarlo tú mismo.","narr":"Recapitulemos. Los datos viven atrapados en documentos y páginas web. Con ETL los extraes, los limpias y los estructuras; con scraping o API los traes de la web, siempre con responsabilidad. Es un trabajo invisible, pero sostiene toda automatización seria. Ahora sigue lo mejor: verlo en acción y armar el tuyo. Nos vemos en la práctica."}],"13":[{"type":"title","dur":18,"eyeb":"Bienvenido","h2":"Una automatización de verdad no es la que funciona, es la que no se rompe","sub":"El día que algo falla —y va a fallar— tu flujo tiene que saber qué hacer.","cap":"Una buena automatización no es la que funciona en la demo, sino la que resiste cuando algo sale mal en producción.","narr":"Bienvenido a esta lección. Cualquiera arma un flujo que funciona el día de la demo. Lo difícil es que siga funcionando el martes a las tres de la mañana, cuando un sistema se cae. Hoy vas a aprender a diseñar automatizaciones que no se rompen."},{"type":"list","dur":16,"eyeb":"Qué vas a aprender","h2":"Cuatro ideas, en pocos minutos","items":[["1","Dos tipos de error","de negocio y de sistema, se tratan distinto"],["2","Reintentos seguros","timeouts e idempotencia sin duplicar"],["3","Logs y recuperación","registrar bien y volver de un fallo"]],"cap":"En esta lección: los dos tipos de excepción, reintentos seguros con idempotencia, y cómo registrar y recuperarte de un fallo.","narr":"Vas a entender cuatro cosas: por qué hay dos tipos de error muy distintos, cómo reintentar sin causar daños, qué registrar para diagnosticar en minutos, y cómo hacer que un fallo a mitad de proceso no deje todo hecho un desastre."},{"type":"define","dur":16,"eyeb":"El concepto base","h2":"Primero, qué es una excepción","def":"Una <b>excepción</b> es cualquier cosa que se sale del camino feliz: un dato inválido, un sistema caído, una respuesta que nunca llega. Diseñar robusto es <b>planear para eso</b>.","cap":"Una excepción es todo lo que se sale del camino esperado. Diseñar robusto es planear para esos casos, no ignorarlos.","narr":"Empecemos por la base. Una excepción es cualquier cosa que se sale del camino esperado: un dato mal escrito, un servidor caído, una respuesta que tarda demasiado. El camino feliz es fácil. Un buen diseño se define por cómo trata todo lo demás."},{"type":"compare","dur":19,"eyeb":"La distinción clave","h2":"No es lo mismo un error de negocio que uno de sistema","colA":["Error de negocio","El dato no cumple una regla","La factura no tiene RFC, el saldo es negativo. El flujo funcionó: los datos no califican. Reintentar no sirve."],"colB":["Error de sistema","Algo técnico falló","La API no responde, se cayó la red, expiró la sesión. Nada malo con los datos. Reintentar casi siempre lo resuelve."],"cap":"Error de negocio: el dato no cumple una regla, reintentar no sirve. Error de sistema: falla técnica, reintentar suele resolverlo.","narr":"Aquí está la distinción que ordena todo. Un error de negocio es cuando el dato no cumple una regla: la factura sin identificación fiscal, un saldo negativo. Reintentar no sirve, porque el dato nunca va a calificar. Un error de sistema es técnico: la interfaz no responde, se cayó la red. Ahí reintentar casi siempre lo arregla. Confundirlos es el error más común."},{"type":"pieces","dur":15,"eyeb":"Cómo tratar cada uno","h2":"Cada tipo de error tiene su salida","pieces":[["🚫","De negocio","Se aparta y se revisa"],["🔁","De sistema","Se reintenta con cuidado"],["🙋","La duda","Escala a un humano"],["📝","Siempre","Se registra qué pasó"]],"cap":"Un error de negocio se aparta para revisión, uno de sistema se reintenta, la duda se escala a un humano y todo se registra.","narr":"¿Y qué haces con cada uno? El error de negocio se aparta en una bandeja para que alguien lo revise. El de sistema se reintenta con cuidado. Cuando no está claro, se escala a una persona. Y pase lo que pase, todo queda registrado. Nunca dejes que un flujo falle en silencio."},{"type":"spot","dur":16,"snum":"El reflejo peligroso","sic":"⚠️","stitle":"Reintentar sin pensar puede duplicar el daño","stext":"Si el pago sí se procesó pero la respuesta se perdió, reintentar cobra dos veces. El reintento necesita una red de seguridad.","sex":"cobrar dos veces · enviar dos correos · duplicar un registro","cap":"Reintentar a ciegas es peligroso: si la acción sí ocurrió y solo se perdió la respuesta, la repites y duplicas el daño.","narr":"Cuidado con un reflejo peligroso. Ante un error de sistema, la reacción es reintentar. Pero imagina que el pago sí se procesó y solo se perdió la respuesta. Si reintentas a ciegas, cobras dos veces. Reintentar sin una red de seguridad no arregla el problema: lo duplica."},{"type":"define","dur":16,"eyeb":"La red de seguridad","h2":"Esa red se llama idempotencia","def":"Una operación es <b>idempotente</b> si ejecutarla una o cinco veces da el <b>mismo resultado</b>. Marcas cada acción con un identificador único, y si ya se hizo, no se repite.","cap":"Idempotencia: repetir la operación no cambia el resultado. Con un identificador único, una acción ya hecha no se vuelve a ejecutar.","narr":"La red de seguridad se llama idempotencia. Una operación es idempotente si ejecutarla una vez o cinco veces produce el mismo resultado. ¿Cómo se logra? Le pones a cada acción un identificador único. Antes de ejecutar, el sistema revisa si esa acción ya se hizo. Si ya ocurrió, no la repite. Así reintentar deja de dar miedo."},{"type":"flow","dur":18,"eyeb":"Reintentos que sí sirven","h2":"Cómo reintentar bien, paso a paso","nodes":[["⏱️","Timeout","Corta si tarda de más"],["🔁","Reintenta","Pocas veces, no infinitas"],["📈","Espera creciente","Cada intento espera más"],["📥","Se rinde","Va a la bandeja de fallos"]],"cap":"Reintento sano: corta con un timeout, reintenta pocas veces, espera cada vez más entre intentos y, si no cede, lo aparta para revisión.","narr":"Un reintento sano tiene cuatro reglas. Primero, un timeout que corta si la respuesta tarda demasiado, para no quedar colgado. Segundo, reintentar pocas veces, no de forma infinita. Tercero, esperar cada vez un poco más entre intentos, para no golpear un sistema que ya está sufriendo. Y cuarto, si nada funciona, rendirse con elegancia y apartar el caso para revisión."},{"type":"pieces","dur":16,"eyeb":"Diagnosticar en minutos","h2":"Un buen log responde cuatro preguntas","pieces":[["🕐","Cuándo","La hora exacta del paso"],["🔖","Qué caso","El identificador del proceso"],["📍","Qué paso","En qué punto iba"],["💥","Qué pasó","El error, con su detalle"]],"cap":"Un log útil dice cuándo ocurrió, de qué caso se trata, en qué paso iba y qué falló exactamente. Así diagnosticas en minutos.","narr":"Cuando algo falla, un buen registro es la diferencia entre resolver en minutos o en horas. Un log útil responde cuatro preguntas: cuándo pasó, con la hora exacta; qué caso era, con su identificador; en qué paso iba el flujo; y qué falló, con el detalle del error. Un mensaje que solo dice error no le sirve a nadie."},{"type":"spot","dur":15,"snum":"El otro extremo","sic":"🔕","stitle":"Registrar de más también te ciega","stext":"Si todo es una alerta, ninguna importa. Registra todo, pero alerta solo lo que de verdad necesita una persona ahora.","sex":"guardar todo · alertar poco · nunca datos sensibles","cap":"Alertar por todo cansa y esconde lo grave. Registra todo, pero alerta solo lo que necesita atención humana inmediata.","narr":"Y cuidado con el otro extremo. Si cada detalle dispara una alerta, terminas ignorándolas todas, y la que importa se pierde en el ruido. La regla: registra todo para poder investigar después, pero alerta solo lo que de verdad necesita a una persona ahora. Y nunca guardes datos sensibles, como contraseñas, en tus logs."},{"type":"flow","dur":18,"eyeb":"Cuando falla a mitad de camino","h2":"Transacción: todo o nada","nodes":[["1️⃣","Cobra","Registra el pago"],["2️⃣","Reserva","Aparta el producto"],["💥","Falla","Se cae en el paso 3"],["↩️","Rollback","Deshace lo anterior"]],"cap":"Si un proceso falla a la mitad, el rollback deshace los pasos ya hechos para no dejar un cobro sin producto ni datos a medias.","narr":"El caso más delicado: fallar a mitad de un proceso. Imagina que cobras, reservas el producto, y en el tercer paso todo se cae. Quedó un cliente cobrado sin su producto. Para eso existe la transacción: o se completan todos los pasos, o no se completa ninguno. Si algo falla, un rollback deshace lo ya hecho y deja todo como al inicio."},{"type":"myth","dur":17,"eyeb":"A tener en cuenta","h2":"Tres verdades honestas sobre la robustez","myths":[["No existe el flujo que nunca falla",", existe el que falla bien"],["La IA no adivina tus reglas",", tú defines qué es un error válido"],["Robustez no es paranoia",", es proteger lo que de verdad duele"]],"cap":"Ningún flujo es infalible: se diseña para fallar bien. La IA no inventa tus reglas de negocio, y proteges lo crítico, no todo por igual.","narr":"Antes de cerrar, tres verdades honestas. Primero: no existe el flujo que nunca falla; existe el que falla bien, de forma controlada. Segundo: la IA puede ayudarte a detectar y clasificar errores, pero no adivina las reglas de tu negocio; esas las defines tú. Y tercero: robustez no es blindar todo por miedo, es proteger con cuidado lo que de verdad duele si falla."},{"type":"title","dur":15,"eyeb":"En resumen","h2":"Un flujo robusto asume que algo va a fallar, y ya sabe qué hacer","sub":"Distingue el error, reintenta con idempotencia, registra útil y sabe volver atrás. Sigue: aplicarlo tú.","cap":"Robustez es distinguir el error, reintentar sin duplicar, registrar lo útil y saber deshacer. Sigue: llevarlo a tu propio flujo.","narr":"Recapitulemos. Un flujo robusto distingue el error de negocio del de sistema, reintenta sin duplicar gracias a la idempotencia, registra lo justo para diagnosticar rápido, y sabe deshacer un proceso a medias. No espera que todo salga bien: ya sabe qué hacer cuando algo sale mal. Ahora sigue lo mejor: aplicarlo en tu propio flujo. Nos vemos en la práctica."}],"14":[{"type":"title","dur":18,"eyeb":"Bienvenido","h2":"Un robot que funciona es solo el principio; el reto es gobernar muchos","sub":"Publicar, programar, repartir el trabajo y vigilarlo todo, desde un solo lugar.","cap":"Tener un robot que funciona es el principio. El reto real es gobernar muchos a escala, con orden.","narr":"Bienvenido a esta lección. Construir un robot que funciona es un gran paso, pero es apenas el principio. El verdadero reto llega cuando tienes varios corriendo a la vez. ¿Quién los lanza, quién reparte el trabajo, quién avisa si uno falla? De eso se encarga UiPath Orchestrator, y aquí vas a entender cómo."},{"type":"list","dur":16,"eyeb":"Qué vas a aprender","h2":"Cuatro ideas, en pocos minutos","items":[["1","Qué es Orchestrator","y cómo se organiza por dentro"],["2","Publicar y proteger","procesos, assets y credenciales"],["3","Colas y triggers","para repartir y disparar el trabajo"]],"cap":"En esta lección: qué es Orchestrator, cómo publicar procesos con seguridad, y cómo repartir y disparar el trabajo.","narr":"Vas a entender cuatro cosas: qué es Orchestrator y cómo se organiza, cómo publicar procesos y proteger sus credenciales, cómo repartir trabajo con colas, y cómo programar y vigilar toda la operación."},{"type":"define","dur":16,"eyeb":"El concepto base","h2":"Primero, qué es Orchestrator","def":"El <b>Orchestrator</b> es el centro de control desde donde <b>publicas, ejecutas, programas y vigilas</b> todos tus robots, en un solo panel.","cap":"Orchestrator es el centro de control: publicas, ejecutas, programas y vigilas todos tus robots desde un panel.","narr":"Empecemos por la base. El Orchestrator es el centro de control de tus robots. Desde un solo panel publicas los procesos, decides qué robot ejecuta cada uno, programas cuándo corren y vigilas cómo van. En lugar de lanzar bots a mano en cada máquina, los gobiernas todos desde ahí."},{"type":"pieces","dur":16,"eyeb":"Cómo se organiza","h2":"Cuatro piezas que ordenan todo","pieces":[["🏢","Tenant","Tu organización aislada"],["📁","Folder","Separa áreas y permisos"],["💻","Máquina","Donde corre el robot"],["🤖","Robot","La identidad que ejecuta"]],"cap":"Se organiza en tenant (tu organización), folders (áreas y permisos), máquinas (dónde corre) y robots (quién ejecuta).","narr":"Orchestrator se organiza en cuatro piezas. El tenant es tu organización, aislada del resto. Los folders separan áreas y quién puede ver cada cosa: finanzas por un lado, recursos humanos por otro. La máquina es el equipo donde corre el bot. Y el robot es la identidad que ejecuta el trabajo. Con eso, todo queda ordenado."},{"type":"compare","dur":18,"eyeb":"La distinción clave","h2":"No es lo mismo un bot suelto que una flota gobernada","colA":["Bot suelto","En una sola máquina","Corre en tu equipo, lo lanzas a mano y, si algo falla de madrugada, nadie se entera."],"colB":["Con Orchestrator","Gobernado y a escala","Publicas una vez, lo ejecutan varios robots, se dispara solo y ves el estado de todo en un panel."],"cap":"Bot suelto: una máquina, lanzado a mano. Con Orchestrator: publicas una vez, corre a escala y lo ves todo.","narr":"Aquí está la diferencia que importa. Un bot suelto vive en una máquina: lo lanzas a mano y, si falla de madrugada, nadie se entera hasta el otro día. Con Orchestrator publicas una vez, varios robots ejecutan, el proceso se dispara solo y ves el estado de todo en un panel. Ese salto es lo que permite escalar."},{"type":"spot","dur":16,"snum":"Del Studio a producción","sic":"📦","stitle":"Publicar y versionar","stext":"Subes el proceso como un paquete con número de versión. Si una versión falla, vuelves a la anterior en segundos.","sex":"publica · versiona · asigna · revierte","cap":"Publicas el proceso como un paquete versionado. Si una versión falla, revertir a la anterior toma segundos.","narr":"Cuando tu proceso está listo, lo publicas como un paquete con un número de versión. Orchestrator guarda cada versión. Si sacas una nueva y algo sale mal, vuelves a la anterior en segundos, sin tocar código. Versionar no es burocracia: es tu red de seguridad para producción."},{"type":"define","dur":17,"eyeb":"Fuera del código","h2":"Assets y credenciales","def":"Los <b>assets</b> son valores compartidos (una ruta, un correo, un límite) y las <b>credenciales</b> guardan usuarios y contraseñas <b>cifrados</b>, nunca dentro del proceso.","cap":"Assets: valores compartidos como rutas o límites. Credenciales: usuarios y contraseñas cifrados, fuera del código.","narr":"Dos elementos te evitan problemas serios. Los assets son valores compartidos que el robot lee al correr: una ruta, un correo, un límite. Cambias el valor una vez y todos los robots lo usan. Las credenciales guardan usuarios y contraseñas cifrados, fuera del proceso. Nunca escribas una contraseña dentro del código: para eso existen."},{"type":"define","dur":16,"eyeb":"Repartir el trabajo","h2":"Qué es una cola","def":"Una <b>cola</b> es una lista de trabajos pendientes. Cada elemento es una <b>transacción</b> que un robot toma, procesa y marca como hecha.","cap":"Una cola es una lista de pendientes. Cada elemento es una transacción que un robot toma, procesa y cierra.","narr":"Para escalar de verdad necesitas las colas. Una cola es simplemente una lista de trabajos pendientes. Cada elemento es una transacción: una factura por procesar, un pedido por registrar. El robot toma un elemento, lo procesa y lo marca como hecho. Así el trabajo no depende de un solo bot corriendo en fila."},{"type":"flow","dur":18,"eyeb":"Colas en acción","h2":"Quinientas facturas, repartidas entre varios robots","nodes":[["📥","Entran","500 facturas"],["🗂️","Cola","Guarda cada transacción"],["🤖","Varios robots","Toman en paralelo"],["✅","Se vacía","Trabajo repartido"]],"cap":"Ejemplo: entran 500 facturas a la cola y varios robots las procesan en paralelo hasta vaciarla. Escala real.","narr":"Veámoslo con un caso. Entran quinientas facturas. En lugar de un robot procesándolas una por una, todas van a una cola. Varios robots toman transacciones en paralelo, cada uno la suya, sin pisarse. La cola se vacía en una fracción del tiempo. Si mañana son cinco mil, sumas robots y listo. Eso es escalar sin reescribir nada."},{"type":"list","dur":16,"eyeb":"Cuándo arranca cada proceso","h2":"Tres formas de disparar un robot","items":[["⏰","Por horario","A una hora o fecha fija"],["📥","Por cola","Cuando entra trabajo nuevo"],["🔔","Por evento","Cuando otro sistema lo pide"]],"cap":"Un robot se dispara por horario, por trabajo que entra a la cola, o por un evento de otro sistema.","narr":"¿Y cuándo arrancan los robots? Los triggers lo definen. Por horario: cada día a las siete, o el primero de cada mes. Por cola: en cuanto entra trabajo nuevo, un robot lo toma. Y por evento: cuando otro sistema avisa que algo pasó. Eliges el disparador según el proceso, y ya nadie tiene que lanzarlo a mano."},{"type":"chips","dur":15,"eyeb":"Vigilar la operación","h2":"Ves la salud de todo sin estar encima","chips":[["📊","Dashboard"],["📜","Logs"],["🚨","Alertas"],["💓","Estado de robots"],["➕","y más"]],"cap":"Monitoreas con dashboard, logs, alertas y el estado de cada robot. Ves la salud de la operación de un vistazo.","narr":"Con todo corriendo, necesitas verlo. Orchestrator te da un dashboard con el estado de cada proceso, logs con el detalle de cada ejecución, y alertas que te avisan cuando algo falla. En vez de revisar máquina por máquina, ves la salud de toda la operación de un vistazo, y actúas antes de que el problema crezca."},{"type":"myth","dur":16,"eyeb":"A tener en cuenta","h2":"Tres cosas para no llevarte una sorpresa","myths":[["No corre solo para siempre",", alguien vigila y ajusta"],["No arregla un proceso mal diseñado",", ordena el que ya funciona"],["No sustituye tu supervisión",", te da los datos para decidir"]],"cap":"Orchestrator no se mantiene solo, no arregla un proceso mal hecho y no sustituye tu supervisión: la respalda con datos.","narr":"Antes de cerrar, tres advertencias honestas. Orchestrator no corre solo para siempre: alguien vigila los logs y ajusta cuando cambia un sistema. No arregla un proceso mal diseñado: solo ordena y escala el que ya funciona. Y no sustituye tu supervisión: te da los datos para decidir mejor. La herramienta gobierna los robots; el criterio lo sigues poniendo tú."},{"type":"title","dur":15,"eyeb":"En resumen","h2":"Un robot ejecuta; Orchestrator gobierna la flota","sub":"Ya sabes cómo publicar, repartir con colas y vigilar. Sigue: montarlo tú mismo.","cap":"Orchestrator publica, reparte con colas, dispara con triggers y vigila. Sigue: montarlo tú mismo en la práctica.","narr":"Recapitulemos. Orchestrator es el centro de control: publicas procesos versionados, proteges sus credenciales, repartes el trabajo con colas, lo disparas con triggers y vigilas todo en un panel. Un robot ejecuta; Orchestrator gobierna la flota entera. Ya tienes el mapa. Ahora sigue lo mejor: montarlo tú mismo. Nos vemos en la práctica."}],"15":[{"type":"title","dur":18,"eyeb":"Bienvenido","h2":"Puedes crear una app de negocio sin escribir código","sub":"La Power Platform de Microsoft te deja construir apps y flujos sobre los datos que tu empresa ya usa.","cap":"Con la Power Platform construyes apps y flujos empresariales sin ser programador, conectados a tus datos reales.","narr":"Bienvenido a esta lección. Muchas empresas ya viven dentro de Microsoft 365: correo, Excel, SharePoint. La Power Platform aprovecha eso: te deja crear apps y automatizar procesos sobre esos mismos datos, sin escribir código. Aquí vas a entender cómo encaja cada pieza."},{"type":"list","dur":16,"eyeb":"Qué vas a aprender","h2":"Cuatro ideas, en pocos minutos","items":[["1","Qué es la Power Platform","y de qué componentes está hecha"],["2","PowerApps y Power Automate","para qué sirve cada uno"],["3","Dónde viven los datos","Dataverse, SharePoint y 365"]],"cap":"En esta lección: qué es la Power Platform, qué hace PowerApps y qué hace Power Automate, y dónde viven los datos.","narr":"Vas a entender cuatro cosas: qué es la Power Platform y sus componentes, qué resuelve PowerApps, qué resuelve Power Automate, y dónde se guardan los datos que usan tus apps y flujos."},{"type":"define","dur":16,"eyeb":"El concepto base","h2":"Primero, qué es la Power Platform","def":"La <b>Power Platform</b> es un conjunto de herramientas de Microsoft para <b>crear apps y automatizar procesos</b> con poco o ningún código, conectadas a los datos de tu empresa.","cap":"La Power Platform es el conjunto de herramientas de Microsoft para crear apps y automatizar procesos con bajo código.","narr":"Empecemos por la base. La Power Platform es un conjunto de herramientas de Microsoft pensado para gente de negocio, no solo para programadores. Con ellas creas aplicaciones y automatizas procesos usando bloques visuales, conectados directo a los datos que tu empresa ya maneja."},{"type":"pieces","dur":16,"eyeb":"Sus componentes","h2":"Cuatro piezas que trabajan juntas","pieces":[["📱","PowerApps","Crea las apps"],["⚙️","Power Automate","Automatiza los flujos"],["🗄️","Dataverse","Guarda los datos"],["🔌","Conectores","Enlazan servicios"]],"cap":"La plataforma tiene cuatro piezas: PowerApps crea apps, Power Automate automatiza, Dataverse guarda datos y los conectores enlazan.","narr":"La plataforma tiene cuatro piezas que se apoyan entre sí. PowerApps, para construir las aplicaciones. Power Automate, para automatizar los procesos. Dataverse, la base donde se guardan los datos. Y los conectores, que enlazan todo con los servicios que ya usas. Reconoce estas cuatro y entiendes el resto."},{"type":"compare","dur":18,"eyeb":"La distinción clave","h2":"PowerApps y Power Automate no hacen lo mismo","colA":["PowerApps","La cara visible","Construye la pantalla con la que la persona interactúa: formularios, botones y listas para capturar y ver datos."],"colB":["Power Automate","El motor detrás","Ejecuta el proceso solo: aprobaciones, avisos y tareas que ocurren sin que nadie abra una pantalla."],"cap":"PowerApps es la cara visible: la pantalla con la que interactúas. Power Automate es el motor que ejecuta el proceso solo.","narr":"Aquí está la distinción que más importa. PowerApps es la cara visible: la pantalla donde una persona captura o consulta información, con botones y formularios. Power Automate es el motor de atrás: ejecuta el proceso por su cuenta, aprobaciones y avisos, sin que nadie abra nada. Uno se ve; el otro trabaja en silencio."},{"type":"compare","dur":17,"eyeb":"Dos formas de app","h2":"Canvas y basada en modelo","colA":["App canvas","Diseño libre","Arrastras controles sobre un lienzo en blanco. Tú decides cómo se ve cada pantalla. Ideal para apps simples y a medida."],"colB":["Basada en modelo","Guiada por datos","Se genera a partir de tu modelo de datos en Dataverse. Más estructurada, ideal para procesos complejos y con muchos registros."],"cap":"App canvas: diseño libre sobre un lienzo, ideal para apps simples. Basada en modelo: se genera desde tus datos, para procesos complejos.","narr":"Dentro de PowerApps hay dos caminos. La app canvas es diseño libre: arrastras controles sobre un lienzo en blanco y tú mandas en cada pantalla. Buena para apps simples y a medida. La basada en modelo se genera a partir de tus datos en Dataverse: más estructurada, pensada para procesos complejos con muchos registros. Eliges según el caso."},{"type":"flow","dur":18,"eyeb":"Construir una app canvas","h2":"De un lienzo en blanco a una app útil","nodes":[["🖼️","Pantallas","Armas las vistas"],["🎛️","Controles","Botones y campos"],["🧮","Fórmulas","Defines la lógica"],["🔗","Datos","Conectas la fuente"]],"cap":"Construir una app canvas: armas las pantallas, agregas controles, defines la lógica con fórmulas y conectas la fuente de datos.","narr":"Construir una app canvas sigue cuatro pasos. Armas las pantallas, las vistas que verá la persona. Agregas controles: botones, campos, listas. Defines la lógica con fórmulas, parecidas a las de Excel. Y conectas la fuente de datos, para que la app lea y guarde de verdad. Cuatro pasos y ya tienes algo funcional."},{"type":"spot","dur":15,"snum":"El lenguaje de PowerApps","sic":"🧮","stitle":"Fórmulas tipo Excel","stext":"La lógica se escribe con funciones parecidas a las de una hoja de cálculo. Si usaste Excel, ya llevas medio camino.","sex":"If · Filter · Patch · Navigate","cap":"La lógica de PowerApps se escribe con fórmulas parecidas a Excel. Si ya usaste hojas de cálculo, partes con ventaja.","narr":"Un detalle que te ahorra tiempo. La lógica en PowerApps no se programa con código: se escribe con fórmulas muy parecidas a las de Excel. Filtrar una lista, guardar un registro, navegar entre pantallas. Si alguna vez usaste una hoja de cálculo, ya llevas medio camino recorrido."},{"type":"flow","dur":18,"eyeb":"Un flujo real","h2":"Una aprobación con Power Automate","nodes":[["📝","Detonante","Llega una solicitud"],["📋","Acción","Se pide aprobación"],["🔀","Decisión","Aprobado o no"],["📤","Resultado","Se avisa y registra"]],"cap":"Ejemplo con Power Automate: llega una solicitud, se pide aprobación, se decide y el flujo avisa y registra el resultado.","narr":"Veamos Power Automate con un caso típico: una aprobación de gasto. El detonante: alguien envía una solicitud desde la app. La acción: el flujo pide la aprobación al responsable. La decisión: aprobado o rechazado. Y el resultado: avisa a la persona y guarda el registro. Todo el ida y vuelta ocurre solo."},{"type":"list","dur":16,"eyeb":"Cloud y desktop","h2":"Power Automate tiene dos caras","items":[["☁️","Flujos en la nube","Conectan servicios: correo, aprobaciones, avisos, 365"],["🖥️","Flujos de escritorio","RPA: automatizan apps viejas sin API en tu equipo"],["🤝","Se combinan","La nube dispara el bot de escritorio cuando hace falta"]],"cap":"Power Automate cloud conecta servicios en línea. El de escritorio hace RPA en tu equipo. Y se combinan entre sí.","narr":"Power Automate tiene dos caras. Los flujos en la nube conectan servicios en línea: correo, aprobaciones, avisos, todo Microsoft 365. Los flujos de escritorio hacen RPA: automatizan programas viejos que no tienen conexión moderna, actuando sobre la pantalla de tu equipo. Y se combinan: la nube puede disparar al bot de escritorio cuando hace falta."},{"type":"pieces","dur":16,"eyeb":"Dónde viven los datos","h2":"Tres lugares donde se guarda la información","pieces":[["🗄️","Dataverse","La base robusta y segura"],["📄","SharePoint","Listas y documentos"],["📊","Excel y 365","Lo que ya tienes hoy"]],"cap":"Tus datos pueden vivir en Dataverse, la base robusta; en SharePoint, para listas; o en Excel y 365, lo que ya usas.","narr":"¿Y de dónde salen los datos? De tres lugares habituales. Dataverse: la base robusta y segura, pensada para apps serias con reglas y permisos. SharePoint: cómodo para listas y documentos de equipo. Y Excel o el resto de 365: lo que tu empresa ya tiene hoy. Empiezas con lo que hay y creces hacia Dataverse."},{"type":"chips","dur":15,"eyeb":"Gobernanza","h2":"Con poder libre hace falta orden","chips":[["🔐","Permisos"],["🛡️","Políticas DLP"],["🌐","Entornos"],["📜","Auditoría"],["➕","y más"]],"cap":"Cuando cualquiera puede crear apps, la gobernanza importa: permisos, políticas DLP, entornos separados y auditoría.","narr":"Un tema que no se puede saltar: la gobernanza. Cuando cualquiera puede crear apps y flujos, hace falta orden. Permisos para saber quién ve qué. Políticas de prevención de fugas, que evitan mezclar datos de la empresa con servicios personales. Entornos separados para pruebas y producción. Y auditoría, para rastrear quién hizo qué."},{"type":"myth","dur":16,"eyeb":"A tener en cuenta","h2":"Tres cosas para no llevarte una sorpresa","myths":[["No es gratis del todo",", las funciones potentes piden licencias"],["No reemplaza al área de sistemas",", necesita gobernanza y reglas claras"],["No arregla un proceso desordenado",", primero lo ordenas, después lo llevas a la app"]],"cap":"La Power Platform no es del todo gratis, no reemplaza a sistemas y no ordena el caos: primero entiendes el proceso.","narr":"Antes de cerrar, tres advertencias honestas. La Power Platform no es del todo gratis: las funciones más potentes, como Dataverse, piden licencias. No reemplaza al área de sistemas: necesita gobernanza y reglas claras para no volverse un caos. Y no arregla un proceso desordenado: primero lo entiendes y lo ordenas, después lo llevas a la app."},{"type":"title","dur":15,"eyeb":"En resumen","h2":"PowerApps pone la cara; Power Automate, el motor","sub":"Ya sabes qué es cada pieza y dónde viven los datos. Sigue: construir tu primera app y tu primer flujo.","cap":"PowerApps es la cara; Power Automate, el motor; Dataverse, los datos. Sigue: construir tu primera app y flujo.","narr":"Recapitulemos. La Power Platform te deja crear sin código: PowerApps pone la cara visible, Power Automate es el motor que trabaja solo, y tus datos viven en Dataverse o SharePoint. Con gobernanza, escala sano. Ya tienes el mapa. Ahora sigue lo mejor: armar tu primera app y tu primer flujo. Nos vemos en la práctica."}],"16":[{"type":"title","dur":18,"eyeb":"Bienvenido","h2":"La mitad de tu información vive atrapada en documentos","sub":"Facturas, contratos y formularios en PDF o papel. Datos valiosos que ningún sistema puede leer solo.","cap":"Gran parte de tus datos vive atrapada en documentos no estructurados. Esta lección trata de cómo liberarlos.","narr":"Bienvenido a esta lección. Buena parte de tu información valiosa vive atrapada en documentos: facturas, contratos, formularios en PDF o papel. Un humano los lee sin problema, pero ningún sistema los entiende solo. Aquí vas a ver cómo extraer esos datos de forma fiable."},{"type":"list","dur":16,"eyeb":"Qué vas a aprender","h2":"Cuatro ideas, en pocos minutos","items":[["1","OCR frente a IDP","de píxeles a datos con sentido"],["2","Extraer de documentos","facturas, contratos y formularios"],["3","Human-in-the-loop","cuándo revisa una persona"]],"cap":"En esta lección: la diferencia entre OCR e IDP, cómo extraer datos de documentos y cuándo revisa un humano.","narr":"Vas a entender cuatro cosas: la diferencia entre OCR e IDP, cómo se extraen datos de facturas y contratos, cuándo debe revisar una persona, y cómo la visión artificial suma valor a tus procesos."},{"type":"define","dur":16,"eyeb":"El concepto base","h2":"Primero, qué es el OCR","def":"El <b>OCR</b> es la tecnología que reconoce texto dentro de una imagen: convierte los <b>píxeles</b> de un documento escaneado en <b>caracteres</b> que una máquina puede leer.","cap":"El OCR reconoce texto dentro de una imagen: convierte los píxeles de un escaneo en caracteres legibles por la máquina.","narr":"Empecemos por la base. El OCR, reconocimiento óptico de caracteres, es la tecnología que detecta texto dentro de una imagen. Toma los píxeles de un documento escaneado y los convierte en letras y números que una máquina puede leer. Es el primer paso, pero no el último."},{"type":"compare","dur":18,"eyeb":"La distinción clave","h2":"Leer texto no es lo mismo que entenderlo","colA":["OCR","Transcribe","Convierte la imagen en texto plano. Te da las palabras, pero no sabe qué significa cada una."],"colB":["IDP","Comprende","Suma IA al OCR: identifica qué campo es el total, la fecha o el proveedor, y lo estructura."],"cap":"OCR transcribe la imagen a texto plano. IDP suma IA: entiende qué campo es cada dato y lo estructura.","narr":"Aquí está la distinción que más importa. El OCR transcribe: te entrega el texto, pero no sabe qué significa. El IDP, procesamiento inteligente de documentos, suma inteligencia artificial encima: identifica qué número es el total, cuál es la fecha y quién es el proveedor. El OCR lee; el IDP entiende."},{"type":"flow","dur":18,"eyeb":"Cómo funciona el IDP","h2":"De un documento a datos listos para usar","nodes":[["📄","Documento","Factura escaneada"],["🔤","OCR","Extrae el texto"],["🧠","IA","Identifica los campos"],["🗂️","Estructura","Datos ordenados"]],"cap":"El IDP: parte de un documento, el OCR extrae el texto, la IA identifica los campos y entrega datos estructurados.","narr":"Veamos el recorrido completo. Entra una factura escaneada. El OCR extrae todo su texto. La inteligencia artificial identifica qué es cada dato: total, fecha, proveedor. Y al final entrega datos estructurados, listos para tu sistema. Un pipeline de cuatro pasos que convierte una imagen en información usable."},{"type":"pieces","dur":16,"eyeb":"Formas de extraer","h2":"Tres enfoques según tu documento","pieces":[["📐","Plantillas","Para documentos siempre iguales"],["📦","Preentrenados","Modelos que ya conocen facturas"],["🎯","Personalizados","Los entrenas con tus casos"]],"cap":"Tres enfoques: plantillas para documentos fijos, modelos preentrenados para tipos comunes y modelos que entrenas tú.","narr":"Hay tres formas de extraer datos. Plantillas: sirven cuando el documento siempre tiene el mismo formato. Modelos preentrenados: ya vienen listos para tipos comunes, como facturas o identificaciones. Y modelos personalizados: los entrenas con tus propios documentos cuando ninguno de los anteriores encaja. Eliges según cuánto varían tus papeles."},{"type":"spot","dur":16,"snum":"El dato que lo decide todo","sic":"📊","stitle":"El nivel de confianza","stext":"Por cada campo, el modelo te dice qué tan seguro está. Ese número decide si el dato pasa solo o lo revisa alguien.","sex":"98% pasa solo · 60% va a revisión","cap":"El modelo asigna a cada dato un nivel de confianza. Ese porcentaje decide si pasa directo o necesita revisión humana.","narr":"Aquí un concepto clave. Por cada dato que extrae, el modelo te dice qué tan seguro está: su nivel de confianza. Si el total tiene noventa y ocho por ciento, pasa solo. Si tiene sesenta, algo dudó, y conviene que alguien lo revise. Ese número es el que gobierna todo el flujo."},{"type":"define","dur":16,"eyeb":"Cerrar el bucle","h2":"Qué es el human-in-the-loop","def":"El <b>human-in-the-loop</b> es incluir a una persona en el flujo: la IA procesa sola lo que domina y <b>deriva a un humano</b> solo los casos de baja confianza.","cap":"Human-in-the-loop: la IA procesa lo que domina y deriva a una persona solo los casos dudosos, de baja confianza.","narr":"De ahí nace una idea central: el human-in-the-loop, o humano en el bucle. En lugar de revisar todo o confiar en todo, la inteligencia artificial procesa sola los casos claros y deriva a una persona solo los dudosos. Así aprovechas la velocidad de la máquina sin perder el control sobre lo que importa."},{"type":"flow","dur":18,"eyeb":"Human-in-the-loop en acción","h2":"El caso dudoso llega a manos expertas","nodes":[["🧾","Extrae","La IA lee la factura"],["📊","Evalúa","Mide su confianza"],["🙋","Revisa","Un humano corrige"],["✅","Aprende","El modelo mejora"]],"cap":"El flujo: la IA extrae, evalúa su confianza, deriva lo dudoso a una persona y con esa corrección el modelo mejora.","narr":"Veámoslo funcionando. La IA lee la factura y extrae los datos. Evalúa su confianza en cada campo. Los casos dudosos llegan a una persona, que corrige lo necesario en segundos. Y esa corrección alimenta al modelo, que la próxima vez acierta más. Cada revisión humana hace al sistema un poco mejor."},{"type":"pieces","dur":16,"eyeb":"Más allá del texto","h2":"La visión artificial ve, no solo lee","pieces":[["🏷️","Clasifica","Distingue tipos de imagen"],["🔍","Detecta","Encuentra objetos o firmas"],["✔️","Verifica","Controla calidad visual"]],"cap":"La visión artificial va más allá del texto: clasifica imágenes, detecta objetos o firmas y verifica calidad visual.","narr":"El texto no es todo. La visión artificial trabaja con la imagen misma. Clasifica: distingue si una foto es una factura o un contrato. Detecta: encuentra una firma, un sello o un objeto. Y verifica: controla que una pieza no tenga defectos. Es leer el mundo visual, no solo las letras."},{"type":"flow","dur":17,"eyeb":"Un ejemplo real","h2":"Control de calidad en una línea de producción","nodes":[["📷","Capta","Cámara sobre la pieza"],["🧠","Analiza","La IA busca defectos"],["⚖️","Decide","¿Pasa o se rechaza?"],["🔔","Actúa","Aparta la defectuosa"]],"cap":"Ejemplo: una cámara capta cada pieza, la IA busca defectos, decide si pasa y aparta automáticamente las defectuosas.","narr":"Un caso concreto de visión artificial. Una cámara capta cada pieza en la línea de producción. La inteligencia artificial analiza la imagen buscando defectos. Decide si la pieza pasa o se rechaza. Y actúa: aparta las defectuosas sin que nadie las mire una por una. Control de calidad a la velocidad de la máquina."},{"type":"myth","dur":16,"eyeb":"A tener en cuenta","h2":"Tres cosas para no llevarte una sorpresa","myths":[["No lee perfecto todo",", un escaneo malo la confunde"],["No elimina al humano",", lo reserva para los casos difíciles"],["No entiende tu negocio",", las reglas de validación las pones tú"]],"cap":"El IDP no lee perfecto un mal escaneo, no elimina al humano y no conoce tus reglas de negocio: eso lo defines tú.","narr":"Antes de cerrar, tres advertencias honestas. Esta tecnología no lee perfecto cualquier cosa: un escaneo borroso o torcido la confunde. No elimina al humano: lo reserva para los casos que de verdad lo necesitan. Y no entiende tu negocio: qué dato es válido y qué hacer con él lo defines tú. Bien usada, te ahorra horas de captura manual."},{"type":"title","dur":15,"eyeb":"En resumen","h2":"OCR lee, IDP entiende y tu criterio valida","sub":"Ya sabes cómo sacar datos de documentos con confianza. Sigue: configurarlo tú mismo.","cap":"OCR transcribe, IDP entiende y tu criterio valida los casos dudosos. Sigue: configurar tu propia extracción.","narr":"Recapitulemos. El OCR transcribe el texto, el IDP entiende qué es cada dato, y el nivel de confianza decide qué revisa una persona. La visión artificial extiende todo esto a las imágenes. Ya tienes el mapa. Ahora sigue lo mejor: configurar tu propia extracción paso a paso. Nos vemos en la práctica."}],"17":[{"type":"title","dur":18,"eyeb":"Bienvenido","h2":"Ninguna automatización vive sola: todas necesitan conectarse","sub":"APIs, webhooks y conectores son el pegamento que une tus sistemas para que trabajen juntos.","cap":"Toda automatización real necesita hablar con otros sistemas. Ese pegamento son las APIs, los webhooks y los conectores.","narr":"Bienvenido a esta lección. Una automatización aislada sirve de poco: el valor aparece cuando tus sistemas hablan entre sí. Ese pegamento tiene nombre: APIs, webhooks y conectores. En los próximos minutos vas a entender cómo funcionan y cómo se conectan las piezas."},{"type":"list","dur":16,"eyeb":"Qué vas a aprender","h2":"Cuatro ideas, en pocos minutos","items":[["1","Qué es una API REST","y cómo pides datos a otro sistema"],["2","Autenticación segura","API keys, tokens y OAuth2"],["3","Webhooks","recibir eventos en tiempo real"]],"cap":"En esta lección: qué es una API REST, cómo autenticarte de forma segura y qué es un webhook para eventos en tiempo real.","narr":"Vas a entender cuatro cosas: qué es una API REST y cómo pides datos con ella, cómo autenticarte de forma segura, qué es un webhook para recibir eventos al instante, y cómo se sincronizan dos sistemas sin romper nada."},{"type":"define","dur":16,"eyeb":"El concepto base","h2":"Primero, qué es una API","def":"Una <b>API</b> es la puerta de entrada de un sistema: un conjunto de reglas que le permite a un programa <b>pedirle datos o acciones</b> a otro, sin saber cómo funciona por dentro.","cap":"Una API es la puerta de un sistema: reglas que dejan a un programa pedirle datos o acciones a otro.","narr":"Empecemos por la base. Una API es la puerta de entrada de un sistema. Es un conjunto de reglas que le permite a un programa pedirle datos o acciones a otro, sin necesidad de saber cómo funciona por dentro. Tú tocas la puerta correcta y recibes lo que pediste."},{"type":"pieces","dur":17,"eyeb":"Anatomía de una llamada","h2":"Toda petición REST tiene estas cuatro partes","pieces":[["🔧","Método","Qué quieres hacer"],["📍","Endpoint","A qué recurso apuntas"],["📦","Payload","Los datos que envías"],["🚦","Código","Cómo respondió"]],"cap":"Una petición REST = método (qué haces) + endpoint (a qué apuntas) + payload (qué envías) + código de estado (cómo respondió).","narr":"Cada vez que llamas a una API REST usas cuatro partes. El método, que dice qué quieres hacer: leer, crear, actualizar o borrar. El endpoint, la dirección exacta del recurso. El payload, los datos que mandas, normalmente en formato JSON. Y el código de estado, que te dice si salió bien o falló."},{"type":"flow","dur":17,"eyeb":"Los verbos","h2":"Cuatro métodos para casi todo lo que harás","nodes":[["📥","GET","Leer datos"],["➕","POST","Crear algo nuevo"],["✏️","PUT","Actualizar"],["🗑️","DELETE","Borrar"]],"cap":"Los cuatro verbos REST: GET lee, POST crea, PUT actualiza y DELETE borra. Con ellos cubres casi todo.","narr":"Los métodos son pocos y fáciles de recordar. GET pide datos: leer sin cambiar nada. POST crea algo nuevo. PUT actualiza lo que ya existe. Y DELETE borra. Con estos cuatro verbos cubres casi cualquier interacción que necesites con otro sistema."},{"type":"define","dur":16,"eyeb":"Antes de pedir, identifícate","h2":"Por qué necesitas autenticación","def":"La <b>autenticación</b> es cómo la API confirma que eres tú y que tienes permiso. Sin credenciales válidas, la puerta simplemente <b>no se abre</b>.","cap":"La autenticación confirma quién eres y qué permisos tienes. Sin credenciales válidas, la API no responde.","narr":"Una API no le abre a cualquiera. La autenticación es cómo confirma que eres tú y que tienes permiso para entrar. Sin credenciales válidas, la puerta no se abre, y con razón: detrás hay datos que deben protegerse. Por eso este paso nunca se salta."},{"type":"compare","dur":19,"eyeb":"Dos formas de identificarte","h2":"API key y OAuth2 no son lo mismo","colA":["API key","Una llave simple","Un texto secreto que envías en cada petición. Fácil de usar, ideal entre tus propios sistemas."],"colB":["OAuth2","Permiso delegado","Un flujo que da acceso temporal en nombre de un usuario, sin compartir su contraseña. Más seguro para terceros."],"cap":"API key: una llave secreta simple, ideal entre tus sistemas. OAuth2: acceso temporal en nombre de un usuario, sin compartir su contraseña.","narr":"Hay dos formas principales de identificarte. La API key es una llave simple: un texto secreto que envías en cada petición. Es cómoda y sirve muy bien entre tus propios sistemas. OAuth2 es un flujo más elaborado: da acceso temporal en nombre de un usuario, sin que compartas su contraseña. Es lo que usas cuando conectas apps de terceros."},{"type":"spot","dur":16,"snum":"La regla de oro","sic":"🔐","stitle":"Tus credenciales nunca van en el código","stext":"Una API key filtrada es una puerta abierta para cualquiera. Guárdalas en variables de entorno o un gestor de secretos, nunca a la vista.","sex":"variables de entorno · gestor de secretos · nunca en texto plano","cap":"Nunca escribas credenciales en el código ni las subas a un repositorio. Guárdalas en variables de entorno o un gestor de secretos.","narr":"Y aquí una regla que no se negocia. Tus credenciales nunca van escritas en el código ni subidas a un repositorio. Una API key filtrada es una puerta abierta para cualquiera. Guárdalas en variables de entorno o en un gestor de secretos. Este cuidado te evita el peor de los sustos."},{"type":"define","dur":16,"eyeb":"Cuando no quieres preguntar todo el tiempo","h2":"Qué es un webhook","def":"Un <b>webhook</b> invierte la llamada: en vez de que tú preguntes una y otra vez, el otro sistema <b>te avisa</b> en el momento exacto en que algo pasa.","cap":"Un webhook invierte la llamada: el otro sistema te avisa al instante cuando ocurre un evento, sin que tengas que preguntar.","narr":"Hasta ahora tú preguntabas a la API. El webhook invierte eso. En lugar de preguntar una y otra vez si hay novedades, el otro sistema te avisa en el momento exacto en que algo pasa. Es la diferencia entre revisar el buzón cada rato o recibir la notificación al instante."},{"type":"compare","dur":18,"eyeb":"Dos maneras de enterarte","h2":"Preguntar sin parar cuesta caro","colA":["Polling","Tú preguntas","Consultas la API cada minuto por si hay algo nuevo. Gastas llamadas y siempre llegas tarde."],"colB":["Webhook","Te avisan","El sistema te notifica solo cuando ocurre el evento. Tiempo real y sin desperdicio."],"cap":"Polling: preguntas cada rato y llegas tarde. Webhook: te avisan justo cuando pasa. Tiempo real y sin gastar llamadas de más.","narr":"Compara las dos maneras. Con polling tú preguntas a la API cada minuto por si hay algo nuevo: gastas llamadas y casi siempre llegas tarde. Con webhook, el sistema te notifica solo cuando ocurre el evento. Es tiempo real y sin desperdicio. Cuando la app lo permite, el webhook casi siempre gana."},{"type":"flow","dur":17,"eyeb":"Un webhook en acción","h2":"De un pago recibido a tu flujo trabajando","nodes":[["💳","Evento","Entra un pago"],["📨","Aviso","La app te lo notifica"],["🛡️","Verifica","Confirmas que es legítimo"],["⚙️","Actúa","Tu flujo se dispara"]],"cap":"Ejemplo: entra un pago, la app avisa a tu webhook, verificas que sea legítimo y tu flujo se dispara al instante.","narr":"Veámoslo con un caso. Entra un pago en tu pasarela. La app envía un aviso a tu webhook al instante. Tú primero verificas que ese aviso sea legítimo, no un impostor. Y una vez confirmado, tu flujo se dispara: registra la venta, manda el recibo, avisa al equipo. Todo en segundos."},{"type":"pieces","dur":17,"eyeb":"Sincronizar sin romper nada","h2":"Cuatro cuidados al mantener dos sistemas al día","pieces":[["🔁","Idempotencia","Repetir no duplica"],["📄","Paginación","Traer datos por tandas"],["🔍","Reconciliación","Cotejar que todo cuadre"],["⏱️","Reintentos","Volver a intentar si falla"]],"cap":"Sincronizar bien exige idempotencia (repetir no duplica), paginación, reconciliación de datos y reintentos ante fallos.","narr":"Conectar dos sistemas para que estén siempre al día tiene sus trucos. Idempotencia: que un aviso repetido no cree registros duplicados. Paginación: traer los datos por tandas cuando son muchos. Reconciliación: cotejar de vez en cuando que todo cuadre. Y reintentos: volver a intentar con cabeza cuando algo falla."},{"type":"myth","dur":17,"eyeb":"A tener en cuenta","h2":"Tres cosas para no llevarte una sorpresa","myths":[["Un conector no elimina el criterio",", tú decides qué se sincroniza y cómo"],["Las APIs cambian y fallan",", tu flujo debe manejar errores, no confiar a ciegas"],["Tiempo real no es gratis",", más avisos significa más carga que gestionar"]],"cap":"Un conector no reemplaza tu criterio. Las APIs cambian y fallan, así que maneja errores. Y el tiempo real trae carga que gestionar.","narr":"Antes de cerrar, tres advertencias honestas. Un conector no elimina tu criterio: tú decides qué se sincroniza y con qué reglas. Las APIs cambian y fallan, así que tu flujo debe manejar errores, no confiar a ciegas. Y el tiempo real no es gratis: más avisos significan más carga que gestionar bien."},{"type":"title","dur":15,"eyeb":"En resumen","h2":"APIs para pedir, webhooks para escuchar, autenticación para proteger","sub":"Ya sabes cómo se conectan tus sistemas. Sigue: construir tu primera integración y probarla de punta a punta.","cap":"APIs para pedir, webhooks para escuchar y autenticación para proteger. Sigue: construir y probar tu primera integración.","narr":"Recapitulemos. Las APIs te dejan pedir datos y acciones. La autenticación protege esa puerta. Los webhooks te avisan al instante cuando algo pasa. Y la sincronización mantiene todo al día sin romperse. Ya tienes el mapa. Ahora sigue lo mejor: construir tu primera integración y probarla de punta a punta. Nos vemos en la práctica."}],"18":[{"type":"title","dur":18,"eyeb":"Bienvenido","h2":"Un agente que atiende por chat y por teléfono, sin hacer esperar","sub":"La misma IA que responde mensajes ahora también contesta llamadas y conversa casi como una persona.","cap":"Los agentes conversacionales atienden por chat y por voz. En esta lección vas a entender cómo se diseñan bien.","narr":"Bienvenido a esta lección. Tus clientes escriben por WhatsApp, por la web y también llaman por teléfono. Un agente conversacional puede atender esos canales las veinticuatro horas. Pero solo sirve si conversa bien. Vamos a ver cómo se diseña."},{"type":"list","dur":16,"eyeb":"Qué vas a aprender","h2":"Cuatro ideas, en pocos minutos","items":[["1","Conversaciones que no frustran","intención, contexto y memoria"],["2","Chat por WhatsApp y web","dónde vive tu agente de texto"],["3","Voicebots","una IA que habla por teléfono"]],"cap":"En esta lección: diseñar conversaciones, chatbots en WhatsApp y web, voicebots por teléfono y el traspaso a un humano.","narr":"Vas a entender cuatro cosas: cómo diseñar conversaciones que no frustran, cómo llevar tu chatbot a WhatsApp y la web, cómo funciona un agente que habla por teléfono, y cuándo pasarle la conversación a una persona."},{"type":"define","dur":16,"eyeb":"El concepto base","h2":"Primero, qué es un agente conversacional","def":"Un <b>agente conversacional</b> es una IA que entiende lo que pides en tu idioma, <b>decide qué hacer</b> y responde por chat o por voz, sin guiones rígidos.","cap":"Un agente conversacional entiende tu idioma, decide qué hacer y responde por chat o por voz, sin guiones rígidos.","narr":"Empecemos por la base. Un agente conversacional es una IA que entiende lo que pides con tus propias palabras, decide qué hacer y te responde por chat o por voz. La diferencia con los menús viejos: no sigue un guion rígido, se adapta a lo que dices."},{"type":"pieces","dur":16,"eyeb":"Cómo entiende","h2":"Tres cosas que el agente necesita captar","pieces":[["🎯","Intención","Qué quiere lograr"],["🧩","Contexto","De qué se viene hablando"],["📇","Memoria","Lo que ya te dijo antes"]],"cap":"Para responder bien capta tres cosas: la intención (qué quieres), el contexto (de qué hablan) y la memoria (lo previo).","narr":"Para responder bien, el agente capta tres cosas. La intención: qué quieres lograr con tu mensaje. El contexto: de qué se viene hablando en esta charla. Y la memoria: lo que ya te dijo o le dijiste antes. Sin esas tres, contesta como robot despistado."},{"type":"spot","dur":16,"snum":"La regla de diseño","sic":"🧭","stitle":"Diseña para cuando la cosa se tuerce","stext":"Lo fácil es el camino feliz. La calidad se ve cuando el cliente responde algo raro, cambia de tema o se enoja.","sex":"no entiende · cambia de tema · se molesta","cap":"El camino feliz es fácil. La calidad de un agente se ve cuando el cliente responde raro, cambia de tema o se enoja.","narr":"Aquí una regla clave. Diseñar el camino ideal es fácil: el cliente pregunta, el agente responde. Lo difícil, y lo que marca la calidad, es cuando la cosa se tuerce. El cliente dice algo raro, cambia de tema o se molesta. Ahí se ve si tu agente sirve."},{"type":"compare","dur":18,"eyeb":"La distinción clave","h2":"Un menú de botones no es una conversación","colA":["Bot de menú","Opción 1, opción 2…","Sigue un árbol fijo. Si tu caso no está en la lista, te deja atascado o te repite lo mismo."],"colB":["Agente con IA","Entiende y responde","Capta lo que quieres aunque lo digas a tu manera, y arma la respuesta según tu caso puntual."],"cap":"Bot de menú: árbol fijo de opciones, y si tu caso no está, te atasca. Agente con IA: entiende y responde a tu caso.","narr":"Conviene distinguir. El bot de menú te da opción uno, opción dos, y sigue un árbol fijo. Si tu caso no está en la lista, te deja atascado. El agente con IA entiende lo que quieres aunque lo digas a tu manera, y arma la respuesta para tu caso. No es lo mismo."},{"type":"chips","dur":15,"eyeb":"Dónde vive el chat","h2":"El mismo agente, en varios canales","chips":[["💬","WhatsApp"],["🌐","Web"],["📷","Instagram"],["📨","Messenger"],["➕","y más"]],"cap":"El mismo agente de texto atiende en WhatsApp, tu sitio web, Instagram y Messenger, entre otros canales.","narr":"¿Dónde vive un agente de texto? En los canales donde ya está tu cliente. WhatsApp, el chat de tu sitio web, Instagram, Messenger y varios más. La idea es una sola: armas el agente una vez y lo conectas a todos, sin repetir el trabajo por canal."},{"type":"flow","dur":18,"eyeb":"Un chat real","h2":"Una consulta por WhatsApp, paso a paso","nodes":[["💬","Llega","Cliente escribe"],["🎯","Entiende","Detecta la intención"],["🔧","Consulta","Busca en tus datos"],["📤","Responde","Contesta claro"]],"cap":"Ejemplo: llega el mensaje, el agente detecta la intención, consulta tus datos con una herramienta y responde claro.","narr":"Veámoslo en un caso. Llega un mensaje por WhatsApp: ¿cuándo llega mi pedido? El agente detecta la intención. Usa una herramienta para consultar el estado en tus sistemas. Y responde con la fecha y un tono claro. Todo en segundos, sin que nadie del equipo lo toque."},{"type":"pieces","dur":17,"eyeb":"Voicebots","h2":"Para hablar por teléfono, suma tres piezas","pieces":[["👂","Escucha","Pasa tu voz a texto"],["🧠","Razona","Decide qué responder"],["🗣️","Habla","Convierte texto en voz"]],"cap":"Un voicebot escucha (voz a texto), razona la respuesta con IA y habla de vuelta (texto a voz). Ese es el circuito.","narr":"Pasemos a la voz. Un voicebot atiende llamadas y suma tres piezas al mismo agente. Escucha: convierte tu voz en texto. Razona: la IA decide qué responder. Y habla: transforma esa respuesta de texto en voz. Ese circuito, repetido, sostiene toda la llamada."},{"type":"spot","dur":17,"snum":"El reto de la voz","sic":"⏱️","stitle":"La latencia se nota muchísimo","stext":"En chat esperas sin problema. Al teléfono, dos segundos de silencio se sienten eternos y matan la naturalidad.","sex":"escucha · razona · habla · sin pausas largas","cap":"En chat esperar está bien. Al teléfono, un par de segundos de silencio se sienten eternos: la latencia es el gran reto.","narr":"Y aquí el gran reto de la voz: la latencia, el tiempo de respuesta. En un chat esperas unos segundos sin problema. Al teléfono, dos segundos de silencio se sienten eternos y la llamada pierde naturalidad. Por eso un voicebot debe escuchar, pensar y hablar casi al instante."},{"type":"flow","dur":17,"eyeb":"El traspaso","h2":"Cuándo pasarle la charla a un humano","nodes":[["🚧","Se traba","No puede resolver"],["😟","O se enoja","El cliente se frustra"],["🤝","Deriva","Pasa a una persona"],["📄","Con contexto","Le pasa el resumen"]],"cap":"El handoff: si el agente se traba o el cliente se frustra, deriva a una persona y le pasa el resumen de la charla.","narr":"Ningún agente resuelve todo, y está bien. A esto se le llama handoff, el traspaso a un humano. Si el agente se traba o el cliente se frustra, deriva la conversación a una persona. Y clave: le pasa el resumen de lo hablado, para que el cliente no repita todo desde cero."},{"type":"list","dur":16,"eyeb":"Cómo saber si sirve","h2":"Tres números que conviene mirar","items":[["✅","Tasa de resolución","Cuántas charlas cierra el agente solo"],["🤝","Tasa de traspaso","Cuántas terminan pasando a un humano"],["😊","Satisfacción","Qué tan conforme queda el cliente"]],"cap":"Mide tres cosas: cuántas charlas resuelve solo, cuántas derivan a un humano y qué tan satisfecho queda el cliente.","narr":"¿Cómo sabes si tu agente sirve? Con tres números. La tasa de resolución: cuántas charlas cierra solo. La tasa de traspaso: cuántas terminan en una persona. Y la satisfacción del cliente: qué tan conforme queda. Sin medir, no sabes si ayudas o si estás frustrando gente."},{"type":"myth","dur":17,"eyeb":"A tener en cuenta","h2":"Tres cosas para no llevarte una sorpresa","myths":[["No reemplaza a tu equipo",", filtra lo simple y deriva lo complejo"],["No debe fingir ser humano",", di claro que es un asistente con IA"],["No se lanza y se olvida",", se revisa y se ajusta con los datos"]],"cap":"Un agente no reemplaza al equipo: filtra lo simple. No finjas que es humano. Y no se lanza y se olvida: se ajusta.","narr":"Antes de cerrar, tres advertencias honestas. Un agente no reemplaza a tu equipo: filtra lo simple y deja lo complejo a las personas. No debe fingir ser humano: dile al cliente que habla con un asistente con inteligencia artificial. Y no se lanza y se olvida: se revisa con los datos y se ajusta."},{"type":"title","dur":15,"eyeb":"En resumen","h2":"Un buen agente atiende bien y sabe cuándo dar un paso al costado","sub":"Ya sabes diseñar conversaciones por chat y voz, y cuándo derivar. Sigue: construir el tuyo.","cap":"Un buen agente conversacional atiende por chat y voz, y sabe cuándo pasar a un humano. Sigue: construir el tuyo.","narr":"Recapitulemos. Un agente conversacional entiende la intención, el contexto y la memoria; atiende por chat y por voz; y sabe cuándo pasarle la charla a una persona. Ya tienes el mapa. Ahora sigue lo mejor: armar el tuyo y medirlo. Nos vemos en la práctica."}],"19":[{"type":"title","dur":18,"eyeb":"Bienvenido","h2":"Ahora un video con rostro y voz se produce sin cámara","sub":"Escribes un guion y la IA genera un presentador que lo dice mirando a cámara.","cap":"Con avatares por IA puedes crear video con rostro y voz a partir de un guion, sin grabar nada.","narr":"Bienvenido a esta lección. Grabar un video con presentador pedía cámara, set y varias tomas. Eso cambió. Hoy escribes un guion y la inteligencia artificial genera un rostro que lo dice con voz sincronizada. Aquí vas a entender cómo funciona y cuándo conviene usarlo."},{"type":"list","dur":16,"eyeb":"Qué vas a aprender","h2":"Cuatro ideas, en pocos minutos","items":[["1","Qué es un avatar por IA","y de qué piezas está hecho"],["2","De guion a video","cómo se produce, paso a paso"],["3","Avatares en tiempo real","conectados a un agente que conversa"]],"cap":"En esta lección: qué es un avatar por IA, cómo pasar de un guion a video, y cómo conectarlo en vivo a un agente.","narr":"Vas a entender cuatro cosas: qué es un avatar por IA y de qué está hecho, cómo se pasa de un guion a un video terminado, cómo un avatar puede conversar en vivo conectado a un agente, y qué cuidados éticos no puedes saltarte."},{"type":"define","dur":16,"eyeb":"El concepto base","h2":"Primero, qué es un avatar inteligente","def":"Un <b>avatar inteligente</b> es un presentador generado por IA: un <b>rostro y una voz</b> que dicen el texto que le das, con labios y gestos sincronizados.","cap":"Un avatar inteligente es un presentador generado por IA: rostro y voz que dicen tu texto, con labios sincronizados.","narr":"Empecemos por la base. Un avatar inteligente es un presentador generado por inteligencia artificial: un rostro y una voz que dicen el texto que tú le entregas. La clave es la sincronía: los labios, los gestos y el tono acompañan a las palabras, para que se vea natural."},{"type":"pieces","dur":16,"eyeb":"Cómo funciona por dentro","h2":"Un avatar se arma con cuatro piezas","pieces":[["🗣️","Guion","El texto que va a decir"],["🎙️","Voz","La IA lo convierte en audio"],["🧑","Rostro","La cara que lo presenta"],["👄","Sincronía","Labios y gestos al hablar"]],"cap":"Un avatar = guion (texto) + voz (audio por IA) + rostro (la cara) + sincronía (labios y gestos coordinados).","narr":"Todo avatar, por realista que parezca, tiene cuatro piezas. El guion: el texto que va a decir. La voz: la IA convierte ese texto en audio hablado. El rostro: la cara que presenta, real o generada. Y la sincronía: lo que coordina labios y gestos con cada palabra. Reconoce estas cuatro y entiendes cualquier avatar."},{"type":"compare","dur":18,"eyeb":"La distinción clave","h2":"No es lo mismo un video fijo que un avatar que conversa","colA":["Avatar en video","Dice un guion fijo","Produces un clip: siempre repite lo mismo. Ideal para formación y anuncios que no cambian."],"colB":["Avatar en vivo","Responde en el momento","Se conecta a un agente y contesta lo que le preguntas, distinto en cada conversación."],"cap":"Video: dice un guion fijo, siempre igual. En vivo: conectado a un agente, responde distinto en cada conversación.","narr":"Aquí una distinción que importa. Un avatar en video dice un guion fijo: produces un clip y siempre repite lo mismo, perfecto para formación o anuncios. Un avatar en vivo es otra cosa: se conecta a un agente y responde en el momento, distinto en cada conversación. Uno se graba; el otro dialoga."},{"type":"flow","dur":18,"eyeb":"De guion a video","h2":"Cómo se produce un video con avatar, paso a paso","nodes":[["📝","Guion","Escribes el texto"],["🧑","Eliges avatar","Rostro e idioma"],["🎬","Genera","La IA arma el video"],["⬇️","Exporta","Listo para publicar"]],"cap":"El ciclo: escribes el guion, eliges rostro e idioma, la IA genera el video y lo exportas listo para publicar.","narr":"Producir un video con avatar es un ciclo simple. Escribes el guion con claridad. Eliges el rostro y el idioma que quieres. La IA genera el video, con la voz y la sincronía resueltas. Y lo exportas, listo para publicar. Lo que antes tomaba un día de grabación, ahora toma minutos y unas cuantas correcciones."},{"type":"list","dur":16,"eyeb":"Dónde sí genera valor","h2":"No sirve para todo, pero brilla en esto","items":[["🎓","Formación","Cursos y onboarding que se actualizan fácil"],["🌐","Multi-idioma","El mismo mensaje en varias lenguas"],["📣","Soporte y avisos","Explicaciones repetibles y a escala"]],"cap":"Brilla en formación, contenido en varios idiomas y mensajes de soporte repetibles que se producen a escala.","narr":"¿Dónde conviene? Donde repites un mensaje muchas veces. En formación, para cursos y onboarding que actualizas cambiando el guion. En contenido multi-idioma, diciendo lo mismo en varias lenguas. Y en soporte, para explicaciones repetibles a escala. Para un mensaje íntimo o único, una grabación real sigue siendo mejor."},{"type":"define","dur":15,"eyeb":"El salto interesante","h2":"Qué es un avatar en tiempo real","def":"Un <b>avatar en tiempo real</b> es un rostro conectado a un <b>agente conversacional</b>: escucha, el agente razona la respuesta y el avatar la dice al instante.","cap":"Un avatar en tiempo real conecta un rostro a un agente: escucha, el agente responde y el avatar lo dice al instante.","narr":"Ahora el salto interesante. Un avatar en tiempo real es un rostro conectado a un agente conversacional. Escucha lo que dices, el agente razona la respuesta usando tus datos, y el avatar la pronuncia al instante. Deja de recitar un guion y empieza a sostener una conversación de verdad."},{"type":"flow","dur":18,"eyeb":"En vivo, paso a paso","h2":"De tu pregunta a la respuesta hablada del avatar","nodes":[["🎤","Hablas","Haces una pregunta"],["🧠","El agente razona","Busca y decide qué responder"],["🎙️","Genera voz","Convierte texto en audio"],["🧑","El avatar responde","Lo dice mirándote"]],"cap":"En vivo: hablas, el agente razona la respuesta, la IA genera la voz y el avatar la dice mirándote.","narr":"Veámoslo en vivo. Le haces una pregunta al avatar. El agente detrás razona qué responder y consulta tus datos si hace falta. La IA convierte esa respuesta en voz. Y el avatar la dice mirándote, con labios sincronizados. Todo en segundos. Ahí la latencia manda: si tarda mucho, la conversación se siente falsa."},{"type":"chips","dur":15,"eyeb":"Dónde vive esto","h2":"Herramientas para crear y animar avatares","chips":[["🎬","HeyGen"],["🧑‍🏫","Synthesia"],["🗣️","D-ID"],["🔊","ElevenLabs"],["➕","y más"]],"cap":"Los avatares se crean en herramientas como HeyGen, Synthesia o D-ID, con voces de servicios como ElevenLabs.","narr":"¿Dónde se arma todo esto? En herramientas visuales como HeyGen, Synthesia o D-ID para el rostro y la animación, apoyadas en voces de servicios como ElevenLabs. No necesitas editar video ni programar: eliges, escribes el guion y ajustas. Cada mes aparecen opciones nuevas, así que compara calidad, idiomas y precio."},{"type":"spot","dur":17,"snum":"El límite que no se negocia","sic":"⚖️","stitle":"Solo con consentimiento","stext":"Clonar la voz o la cara de alguien exige su permiso explícito. Sin consentimiento, no es un atajo: es un problema legal y ético.","sex":"pides permiso · lo documentas · avisas que es IA","cap":"Clonar voz o rostro exige permiso explícito. Sin consentimiento no es un atajo, es un problema legal y ético.","narr":"Y aquí un límite que no se negocia. Clonar la voz o la cara de una persona exige su permiso explícito. Sin ese consentimiento no estás tomando un atajo: estás creando un problema legal y ético. Pides permiso, lo documentas por escrito, y usas solo lo autorizado. Esa disciplina te protege a ti y a los demás."},{"type":"myth","dur":17,"eyeb":"A tener en cuenta","h2":"Tres cosas para no llevarte una sorpresa","myths":[["No es indetectable",", di siempre que el presentador es IA"],["No cualquier rostro es tuyo",", necesitas derechos de imagen"],["No reemplaza el contacto real",", suma escala, no calidez"]],"cap":"El avatar no es indetectable: avisa que es IA. No uses rostros sin derechos. Y no reemplaza el contacto humano real.","narr":"Antes de cerrar, tres advertencias honestas. Un avatar no es indetectable ni debe engañar: avisa siempre que el presentador es inteligencia artificial. No cualquier rostro es tuyo: necesitas derechos de imagen para usarlo. Y no reemplaza el contacto humano: te da escala, no calidez. Un deepfake sin permiso no es creatividad, es un fraude."},{"type":"title","dur":15,"eyeb":"En resumen","h2":"Un avatar dice tu guion; con un agente, además conversa","sub":"Ya sabes cómo se produce y qué cuidados exige. Sigue: crear tu primer video con avatar.","cap":"Un avatar por IA dice tu guion y, conectado a un agente, conversa en vivo. Con consentimiento y transparencia siempre.","narr":"Recapitulemos. Un avatar inteligente es un rostro y una voz que dicen tu guion, y conectado a un agente, además conversa en vivo. Bien usado, produce formación y soporte a escala, siempre con consentimiento y transparencia. Ya tienes el mapa. Ahora sigue lo mejor: crear tu primer video con avatar. Nos vemos en la práctica."}],"20":[{"type":"title","dur":18,"eyeb":"Bienvenido","h2":"Cuando un solo agente ya no alcanza, necesitas orquestar","sub":"Un agente resuelve una tarea. Un proceso real necesita varios, coordinados y en orden.","cap":"Un agente resuelve una tarea; un proceso real necesita varios agentes coordinados. Eso es orquestación.","narr":"Bienvenido a esta lección. Ya sabes construir un agente que resuelve una tarea. Pero un proceso de verdad tiene muchas partes. Cuando conectas varios agentes y sistemas para que trabajen juntos, en orden y sin pisarse, eso es orquestación. Aquí vas a entender cómo se diseña."},{"type":"list","dur":16,"eyeb":"Qué vas a aprender","h2":"Cuatro ideas, en pocos minutos","items":[["1","Cuándo usar varios agentes","y cuándo uno solo basta"],["2","Patrones de coordinación","orquestador, trabajadores y eventos"],["3","Cómo se comunican","estado, colas y mensajes entre agentes"]],"cap":"En esta lección: cuándo usar varios agentes, los patrones de coordinación, y cómo se comunican entre sí.","narr":"Vas a entender cuatro cosas: cuándo conviene usar varios agentes en lugar de uno, qué patrones existen para coordinarlos, cómo se comunican entre sí con estado y colas, y cómo vigilar todo cuando hay muchas piezas moviéndose."},{"type":"define","dur":16,"eyeb":"El concepto base","h2":"Primero, qué es orquestar","def":"<b>Orquestar</b> es coordinar varios agentes y sistemas para que resuelvan un proceso completo: cada uno hace su parte, en el <b>orden correcto</b> y con la información adecuada.","cap":"Orquestar es coordinar varios agentes para resolver un proceso completo, cada uno en su parte y en orden.","narr":"Empecemos por la base. Orquestar es coordinar varios agentes y sistemas para resolver un proceso entero. Como en una orquesta, cada uno toca su parte, pero alguien marca el orden y el momento. El resultado no es una tarea suelta, sino un proceso completo funcionando solo."},{"type":"compare","dur":18,"eyeb":"La primera decisión","h2":"Un agente grande no siempre es la respuesta","colA":["Un solo agente","Hace todo","Simple de empezar, pero se satura: mezcla tareas, se confunde y es difícil de arreglar cuando falla."],"colB":["Varios especializados","Cada uno una cosa","Divides el problema. Cada agente es claro, fácil de probar y de mejorar por separado."],"cap":"Un agente que hace todo se satura y confunde. Varios especializados dividen el problema y son más fáciles de mantener.","narr":"Aquí está la primera decisión. Un solo agente que lo hace todo es fácil de empezar, pero se satura: mezcla tareas, se confunde y cuesta arreglarlo cuando falla. Dividir el problema en agentes especializados, cada uno con una función clara, te da piezas simples de probar y de mejorar por separado. Divide cuando el trabajo ya no cabe en una cabeza."},{"type":"list","dur":17,"eyeb":"Cuándo separar","h2":"Tres señales de que necesitas varios agentes","items":[["🧩","Tareas muy distintas","Buscar, redactar y aprobar no piden lo mismo"],["🔧","Herramientas separadas","Cada parte usa sistemas y permisos diferentes"],["📈","Escala y carga","Quieres repartir el trabajo entre varias piezas"]],"cap":"Separa en varios agentes cuando hay tareas muy distintas, herramientas separadas, o necesitas repartir la carga.","narr":"¿Cómo sabes que llegó el momento de separar? Tres señales. Cuando las tareas son muy distintas entre sí: buscar, redactar y aprobar no piden lo mismo. Cuando cada parte usa herramientas y permisos diferentes. Y cuando necesitas repartir la carga para escalar. Si ves una de estas, piensa en varios agentes."},{"type":"pieces","dur":16,"eyeb":"El patrón más común","h2":"Orquestador y trabajadores, cuatro piezas","pieces":[["🧭","Orquestador","Reparte y decide"],["🔨","Trabajadores","Ejecutan su tarea"],["📇","Estado","Qué se hizo ya"],["📤","Resultado","Lo que se entrega"]],"cap":"El patrón orquestador-trabajador: uno reparte y decide, otros ejecutan, un estado compartido guarda el avance.","narr":"El patrón más usado tiene cuatro piezas. El orquestador, que recibe el objetivo, lo parte en tareas y decide quién hace qué. Los trabajadores, agentes que ejecutan cada tarea. El estado, donde se guarda qué se hizo ya. Y el resultado final. Uno dirige, varios ejecutan: sencillo y potente."},{"type":"flow","dur":18,"eyeb":"El patrón en acción","h2":"Una factura que llega y se procesa sola","nodes":[["📥","Llega","Entra una factura"],["🧭","Reparte","El orquestador divide"],["🔨","Trabajan","Leer, validar, registrar"],["✅","Cierra","Pago aprobado"]],"cap":"Ejemplo: llega una factura, el orquestador reparte, los trabajadores la leen, validan y registran, y se aprueba.","narr":"Veámoslo con un caso. Llega una factura. El orquestador la recibe y reparte el trabajo. Un agente lee los datos, otro valida contra el pedido, otro la registra en el sistema. Cada uno hace su parte y avisa. Al final, el pago queda aprobado. Ningún agente hizo todo: entre varios, coordinados, cerraron el proceso."},{"type":"compare","dur":18,"eyeb":"Otra forma de coordinar","h2":"No siempre alguien manda: a veces mandan los eventos","colA":["Orquestado","Un jefe dirige","El orquestador llama a cada agente en orden. Claro y fácil de seguir, pero todo depende de él."],"colB":["Por eventos","Reaccionan a señales","Cada agente actúa cuando ocurre algo que le toca. Más flexible y desacoplado, pero más difícil de rastrear."],"cap":"Orquestado: un jefe llama a cada agente en orden. Por eventos: cada agente reacciona cuando ocurre algo que le toca.","narr":"Hay una segunda forma de coordinar. En la orquestada, un jefe llama a cada agente en orden: es clara, pero todo depende de él. En la de eventos, nadie dirige: cada agente reacciona cuando ocurre algo que le toca. Es más flexible y las piezas quedan desacopladas, pero cuesta más rastrear qué pasó. Se eligen según el proceso."},{"type":"define","dur":16,"eyeb":"La pieza que desacopla","h2":"Qué es una cola","def":"Una <b>cola</b> es una fila de mensajes en espera: un agente deja ahí el trabajo y otro lo toma <b>cuando puede</b>, sin que ninguno tenga que esperar al otro.","cap":"Una cola es una fila de mensajes: un agente deja el trabajo y otro lo toma cuando puede, sin esperarse.","narr":"Para que esto funcione sin que todo se trabe, existe la cola. Es una fila de mensajes en espera. Un agente deja ahí una tarea y sigue con lo suyo. Otro la toma cuando tiene capacidad. Nadie se queda esperando al otro. La cola es lo que permite que muchas piezas trabajen a su ritmo sin chocar."},{"type":"flow","dur":18,"eyeb":"La cola en acción","h2":"Mil pedidos que no saturan el sistema","nodes":[["📨","Entran","Llegan mil pedidos"],["📥","Se encolan","Esperan su turno"],["🔨","Se reparten","Varios agentes toman"],["✅","Se procesan","Sin perder ninguno"]],"cap":"Con una cola, mil pedidos entran, esperan su turno y varios agentes los van tomando sin saturar ni perder ninguno.","narr":"Imagina que entran mil pedidos de golpe. Sin cola, el sistema se satura. Con cola, los mil entran y esperan ordenados. Varios agentes van tomando uno por uno, al ritmo que aguantan. Ninguno se pierde y nada se cae. Así se procesa un volumen enorme con piezas que, una a una, son modestas."},{"type":"pieces","dur":16,"eyeb":"Que no se rompa","h2":"Cuatro cuidados al coordinar agentes","pieces":[["🔁","Reintentos","Si uno falla, se reintenta"],["🧯","Aislar fallos","Que un error no tumbe todo"],["📇","Estado claro","Saber qué se hizo ya"],["🚫","Sin duplicar","No repetir una acción"]],"cap":"Al coordinar agentes cuida: reintentos ante fallos, aislar errores, estado claro y no duplicar acciones.","narr":"Coordinar muchas piezas trae riesgos, y cuatro cuidados los controlan. Reintentos: si un agente falla, que se vuelva a intentar. Aislar fallos: que el error de uno no tumbe a todos. Estado claro: saber siempre qué se hizo ya. Y evitar duplicados: que un reintento no cobre dos veces. Con esto, tu sistema aguanta el mundo real."},{"type":"spot","dur":17,"snum":"El punto ciego","sic":"🔍","stitle":"Si no lo ves, no lo puedes arreglar","stext":"Con muchos agentes, un fallo se esconde. Necesitas trazas: seguir un proceso paso a paso, de principio a fin.","sex":"traza · métricas · alertas","cap":"Con muchos agentes un fallo se esconde. La observabilidad te deja seguir cada proceso paso a paso para arreglarlo.","narr":"Y aquí el punto ciego que hunde a muchos. Con un agente, si falla, lo ves. Con veinte coordinados, un error se esconde entre las piezas. Por eso necesitas observabilidad: trazas que sigan un proceso paso a paso, métricas de cómo va y alertas cuando algo se rompe. Lo que no puedes ver, no lo puedes arreglar."},{"type":"myth","dur":17,"eyeb":"A tener en cuenta","h2":"Tres cosas para no complicarte de más","myths":[["Más agentes no es mejor",", cada uno suma complejidad"],["No se coordina solo",", el diseño y las reglas los pones tú"],["No quita la supervisión",", más piezas piden más criterio"]],"cap":"Más agentes no es mejor: suman complejidad. No se coordinan solos ni se supervisan solos: eso lo diseñas tú.","narr":"Antes de cerrar, tres advertencias honestas. Más agentes no es mejor: cada uno suma complejidad, así que empieza con los mínimos. No se coordinan solos: el diseño, el orden y las reglas los pones tú. Y no quitan la supervisión: mientras más piezas, más criterio hace falta para vigilarlas. Orquestar bien es también saber cuándo no dividir."},{"type":"title","dur":15,"eyeb":"En resumen","h2":"Orquestar es repartir el trabajo y coordinar el orden","sub":"Ya sabes cuándo usar varios agentes y cómo coordinarlos. Sigue: diseñarlo tú mismo.","cap":"Orquestar es repartir el trabajo entre agentes y coordinar el orden con patrones, colas y observabilidad. Sigue: practicarlo.","narr":"Recapitulemos. Orquestar es repartir un proceso entre agentes especializados y coordinar el orden, sea con un orquestador o por eventos, apoyándote en colas y en buena observabilidad. Ya tienes el mapa. Ahora sigue lo mejor: diseñar tu primer sistema de varios agentes trabajando juntos. Nos vemos en la práctica."}],"21":[{"type":"title","dur":18,"eyeb":"Bienvenido","h2":"Una automatización que rompe la ley no ahorra tiempo: lo cuesta caro","sub":"Tus flujos tocan datos personales y credenciales. Cumplir la norma no es un freno: es lo que te deja escalar tranquilo.","cap":"Tus automatizaciones manejan datos y accesos sensibles. Cumplir la ley y la seguridad es lo que te permite escalar sin sustos.","narr":"Bienvenido a esta lección. Tus automatizaciones mueven datos personales, usan contraseñas y toman decisiones solas. Eso trae poder, pero también responsabilidad legal. Aquí vas a entender cómo automatizar cumpliendo la norma, sin frenar tu trabajo."},{"type":"list","dur":16,"eyeb":"Qué vas a aprender","h2":"Cuatro temas, en pocos minutos","items":[["1","Protección de datos","qué exige la ley al tratar datos personales"],["2","El AI Act","cómo se clasifica el riesgo de tus agentes"],["3","Ciberseguridad","cómo proteger secretos y accesos"]],"cap":"En esta lección: protección de datos, el AI Act y su clasificación de riesgo, y la seguridad de secretos y accesos.","narr":"Vas a entender cuatro temas. Qué te exige la ley de protección de datos, cómo el AI Act clasifica el riesgo de tus agentes, cómo proteger contraseñas y accesos, y cómo dejar rastro para superar una auditoría."},{"type":"define","dur":16,"eyeb":"El concepto base","h2":"Primero, qué es un dato personal","def":"Un <b>dato personal</b> es cualquier información que identifica a una persona: su nombre, correo, teléfono, ubicación o historial. Si tu flujo lo toca, la ley aplica.","cap":"Dato personal es toda información que identifica a alguien: nombre, correo, teléfono, ubicación. Si tu flujo lo toca, la ley aplica.","narr":"Empecemos por la base. Un dato personal es cualquier información que identifica a una persona: su nombre, su correo, su teléfono, su ubicación. En el momento en que tu flujo lee o guarda ese dato, la ley de protección de datos ya te aplica."},{"type":"pieces","dur":16,"eyeb":"Protección de datos en la práctica","h2":"Cuatro reglas que tu flujo debe respetar","pieces":[["🎯","Finalidad","Usar el dato solo para lo que se pidió"],["📉","Minimización","Recolectar lo mínimo necesario"],["🔐","Seguridad","Protegerlo mientras lo tratas"],["🙋","Derechos","Dejar acceder, corregir y borrar"]],"cap":"Reglas clave: usar el dato solo para su fin, pedir lo mínimo, protegerlo y respetar el derecho a acceder, corregir y borrar.","narr":"La protección de datos se resume en cuatro reglas. Finalidad: usa el dato solo para lo que la persona autorizó. Minimización: pide lo mínimo necesario, no todo por si acaso. Seguridad: protégelo mientras lo trabajas. Y derechos: la persona puede pedir acceder, corregir o borrar su información."},{"type":"define","dur":16,"eyeb":"La regulación de la IA","h2":"Ahora, qué es el AI Act","def":"El <b>AI Act</b> es la ley europea que regula la inteligencia artificial por <b>nivel de riesgo</b>: a más riesgo para las personas, más obligaciones para quien la usa.","cap":"El AI Act es la ley europea que regula la IA por nivel de riesgo: a mayor riesgo para las personas, más obligaciones.","narr":"Pasemos a la IA. El AI Act es la ley europea que regula la inteligencia artificial según su riesgo. Aunque sea europea, marca la pauta mundial. Su idea es simple: mientras más pueda afectar a las personas tu sistema, más obligaciones tienes al usarlo."},{"type":"flow","dur":18,"eyeb":"Los niveles de riesgo","h2":"El AI Act ordena la IA en cuatro escalones","nodes":[["🚫","Inaceptable","Prohibido de raíz"],["⚠️","Alto","Muy vigilado"],["📄","Limitado","Debes avisar"],["✅","Mínimo","Uso libre"]],"cap":"Cuatro niveles: riesgo inaceptable (prohibido), alto (muy regulado), limitado (obliga a avisar) y mínimo (uso libre).","narr":"El AI Act ordena la IA en cuatro escalones. Riesgo inaceptable, prohibido de raíz, como puntuar personas. Riesgo alto, muy vigilado, por ejemplo en salud o contratación. Riesgo limitado, donde solo debes avisar que hay IA. Y riesgo mínimo, de uso libre. Ubicar tu agente te dice qué te exigen."},{"type":"spot","dur":16,"snum":"La consecuencia práctica","sic":"🗣️","stitle":"Si tu agente atiende personas, avísales","stext":"Un chatbot o voicebot suele caer en riesgo limitado: la persona tiene derecho a saber que habla con una IA, no con un humano.","sex":"chatbot · voicebot · respuestas automáticas","cap":"Un chatbot o voicebot suele ser riesgo limitado: la persona tiene derecho a saber que habla con una IA, no con un humano.","narr":"Veamos qué significa en tu día a día. Si tienes un chatbot o un voicebot atendiendo clientes, casi seguro cae en riesgo limitado. Eso te obliga a algo concreto: avisar que hablan con una inteligencia artificial. Ocultarlo no solo incomoda, ahora también te expone legalmente."},{"type":"compare","dur":18,"eyeb":"La distinción clave","h2":"Un secreto no es lo mismo que un dato cualquiera","colA":["Dato","La información que procesas","El nombre o pedido de un cliente. Lo tratas con cuidado, pero es el material de trabajo del flujo."],"colB":["Secreto","La llave que abre los sistemas","Contraseñas, tokens y claves de API. Si se filtran, alguien entra a todo. Se guardan aparte y cifradas."],"cap":"Dato: la información que procesas, con cuidado. Secreto: contraseñas y claves de API que abren tus sistemas. Se guardan aparte y cifradas.","narr":"Aquí una distinción que salva empresas. Un dato es la información que procesas, como el pedido de un cliente. Un secreto es otra cosa: contraseñas, tokens y claves de API. Son las llaves de tus sistemas. Si un dato se filtra, es grave; si un secreto se filtra, alguien entra a todo."},{"type":"pieces","dur":16,"eyeb":"Ciberseguridad de tus flujos","h2":"Tres prácticas que reducen casi todo el riesgo","pieces":[["🗝️","Gestor de secretos","Claves cifradas, nunca en el código"],["🚪","Mínimo privilegio","Solo el acceso que la tarea necesita"],["🎯","Menos superficie","Menos accesos, menos por atacar"]],"cap":"Claves siempre en un gestor cifrado, nunca en el código. Da el mínimo acceso necesario. Y reduce la superficie de ataque.","narr":"Tres prácticas cubren casi todo el riesgo. Primera: guarda las claves en un gestor de secretos cifrado, nunca escritas en el código. Segunda: mínimo privilegio, dale al bot solo el acceso que su tarea necesita, ni uno más. Tercera: menos accesos abiertos significan menos puertas que alguien pueda atacar."},{"type":"spot","dur":15,"snum":"El error más común","sic":"🔓","stitle":"La clave escrita dentro del flujo","stext":"Pegar una contraseña o API key directo en el código o el nodo es el fallo que más filtraciones causa. Usa siempre variables seguras.","sex":"nada de claves en texto plano","cap":"El error más común: pegar una clave o API key directo en el flujo. Causa filtraciones. Usa siempre variables o secretos seguros.","narr":"Cuidado con el error más común de todos. Pegar una contraseña o una clave de API directo dentro del flujo, en texto plano. Parece práctico, pero cualquiera que vea ese flujo ve la llave. Usa siempre variables seguras o un gestor de secretos. Nunca, la clave a la vista."},{"type":"define","dur":15,"eyeb":"El seguro de todo esto","h2":"Qué es la trazabilidad","def":"La <b>trazabilidad</b> es el registro de <b>quién hizo qué y cuándo</b>: cada acción de tu bot queda anotada, para poder revisarla o auditarla después.","cap":"Trazabilidad es el registro de quién hizo qué y cuándo: cada acción del bot queda anotada para poder revisarla o auditarla.","narr":"Falta una pieza que te protege a ti. La trazabilidad es el registro de quién hizo qué y cuándo. Cada acción de tu bot queda anotada: qué dato tocó, qué decidió, a qué hora. Cuando llega una auditoría o algo falla, ese registro es tu mejor defensa."},{"type":"myth","dur":17,"eyeb":"A tener en cuenta","h2":"Tres ideas honestas antes de cerrar","myths":[["El cumplimiento no es solo del abogado",", tú que diseñas el flujo también respondes"],["La IA no decide sola en temas serios",", una persona debe supervisar lo que importa"],["Cumplir no frena el proyecto",", te evita rehacerlo o pagar multas después"]],"cap":"El cumplimiento también es tuyo, no solo del abogado. La IA no decide sola en lo serio: supervisas. Y cumplir evita rehacer y multas.","narr":"Antes de cerrar, tres ideas honestas. El cumplimiento no es solo del abogado: tú que diseñas el flujo también respondes por él. La IA no decide sola en asuntos serios; una persona supervisa lo que importa. Y cumplir no frena el proyecto: te ahorra rehacerlo o pagar multas más adelante."},{"type":"title","dur":15,"eyeb":"En resumen","h2":"Automatizar con criterio también es automatizar dentro de la ley","sub":"Ya conoces protección de datos, el AI Act, la gestión de secretos y la trazabilidad. Sigue: aplicarlo a un flujo real.","cap":"Automatizar bien también es hacerlo dentro de la ley: datos protegidos, riesgo ubicado, secretos seguros y todo registrado. Sigue: aplicarlo.","narr":"Recapitulemos. Proteges los datos personales, ubicas el riesgo de tu IA con el AI Act, guardas los secretos cifrados y con mínimo privilegio, y registras cada acción. Automatizar con criterio también es hacerlo dentro de la ley. Ahora sigue lo mejor: aplicarlo a un flujo real. Nos vemos en la práctica."}],"22":[{"type":"title","dur":18,"eyeb":"Bienvenido · Lección final","h2":"La IA ya decide; la pregunta es cómo lo hace bien","sub":"Un sistema que actúa por ti también puede fallar por ti. Aquí aprendes a construirlo con responsabilidad.","cap":"Un sistema de IA que actúa por ti también puede equivocarse por ti. Esta lección final trata de construirlo con responsabilidad.","narr":"Bienvenido a la lección final del curso. Ya sabes automatizar con IA. Ahora lo más importante: un sistema que decide por ti también puede fallar por ti. Aquí aprendes a construir IA responsable, para que tu automatización sume y no cause daño."},{"type":"list","dur":16,"eyeb":"Qué vas a aprender","h2":"Cuatro ideas, en pocos minutos","items":[["1","De dónde viene el sesgo","y cómo mitigarlo en tus sistemas"],["2","Transparencia y explicabilidad","que se sepa que es IA y por qué decide"],["3","Supervisión humana real","no un botón decorativo"]],"cap":"En esta lección: sesgos y cómo mitigarlos, transparencia y explicabilidad, y supervisión humana significativa.","narr":"Vas a entender cuatro cosas: de dónde vienen los sesgos y cómo reducirlos, qué es la transparencia y la explicabilidad, cómo diseñar supervisión humana que de verdad sirva, y cómo gestionar riesgos comunicando los límites de tu sistema."},{"type":"define","dur":16,"eyeb":"El concepto base","h2":"Primero, qué es el sesgo en IA","def":"El <b>sesgo</b> es cuando un sistema de IA <b>trata distinto</b>, de forma injusta, a personas o casos parecidos, casi siempre porque aprendió de datos que ya venían torcidos.","cap":"El sesgo es cuando la IA trata de forma injusta a casos parecidos, casi siempre porque aprendió de datos ya torcidos.","narr":"Empecemos por la base. El sesgo es cuando un sistema trata distinto, de forma injusta, a personas o casos parecidos. No suele ser malicia: el modelo aprendió de datos que ya venían torcidos, y repite ese patrón a escala, en cada decisión."},{"type":"flow","dur":17,"eyeb":"De dónde viene","h2":"El sesgo se cuela por tres puertas","nodes":[["📊","En los datos","Reflejan un pasado desigual"],["🧠","En el modelo","Amplifica lo que ve más"],["⚖️","En la decisión","Se aplica sin revisión"]],"cap":"El sesgo entra por los datos que reflejan un pasado desigual, se amplifica en el modelo y se aplica en la decisión sin revisión.","narr":"El sesgo se cuela por tres puertas. En los datos, que reflejan un pasado desigual. En el modelo, que amplifica lo que más ha visto. Y en la decisión, cuando esa salida se aplica sin que nadie la revise. Conocer las tres puertas es el primer paso para cerrarlas."},{"type":"list","dur":17,"eyeb":"Cómo mitigarlo","h2":"No se elimina del todo, pero se reduce mucho","items":[["🔎","Audita los datos","Revisa a quién representan y a quién no"],["🧪","Prueba por grupos","Mide si acierta igual con todos"],["🔁","Corrige y repite","El sesgo se vigila siempre, no una vez"]],"cap":"Mitiga el sesgo auditando los datos, probando el sistema por grupos y corrigiendo de forma continua, no una sola vez.","narr":"El sesgo no se elimina del todo, pero se reduce mucho. Audita tus datos: mira a quién representan y a quién dejan fuera. Prueba el sistema por grupos: revisa si acierta igual con todos. Y corrige de forma continua, porque el sesgo se vigila siempre, no una sola vez."},{"type":"define","dur":16,"eyeb":"La segunda pieza","h2":"Transparencia y explicabilidad","def":"<b>Transparencia</b> es que la persona sepa que está tratando con una IA. <b>Explicabilidad</b> es poder decir <b>por qué</b> el sistema tomó una decisión, en palabras claras.","cap":"Transparencia: que se sepa que es una IA. Explicabilidad: poder decir por qué decidió lo que decidió, en palabras claras.","narr":"La segunda pieza son dos ideas hermanas. Transparencia es que la persona sepa que está tratando con una inteligencia artificial, no con un humano. Explicabilidad es poder decir por qué el sistema decidió lo que decidió, en palabras que cualquiera entienda."},{"type":"compare","dur":18,"eyeb":"Por qué importa","h2":"Una caja negra no es lo mismo que un sistema que rinde cuentas","colA":["Caja negra","Decide y no explica","Da un resultado y nadie sabe por qué. Si falla, no puedes corregirlo ni defenderlo ante nadie."],"colB":["Sistema explicable","Decide y justifica","Muestra en qué se basó. Puedes revisarlo, corregir errores y responder a quien te lo reclame."],"cap":"Caja negra: decide sin explicar y no puedes corregirla. Sistema explicable: muestra en qué se basó y puedes rendir cuentas.","narr":"Aquí está la diferencia. Una caja negra da un resultado y nadie sabe por qué: si falla, no puedes corregirlo ni defenderlo. Un sistema explicable muestra en qué se basó: puedes revisarlo, arreglar el error y responder a quien te lo reclame. Cuando algo decide sobre personas, esa diferencia lo es todo."},{"type":"define","dur":16,"eyeb":"La tercera pieza","h2":"Supervisión humana significativa","def":"Es que una persona pueda <b>entender, revisar y revertir</b> lo que hace la IA en las decisiones que importan. No un botón decorativo: control real.","cap":"Supervisión humana significativa: que una persona pueda entender, revisar y revertir la IA en lo que importa. Control real, no decorativo.","narr":"La tercera pieza es la supervisión humana significativa. Significa que, en las decisiones que importan, una persona pueda entender lo que hizo la IA, revisarlo y revertirlo. No un botón decorativo que nadie mira: control real, con poder de decir que no."},{"type":"flow","dur":17,"eyeb":"Cómo se ve en la práctica","h2":"El humano en el bucle, en el momento correcto","nodes":[["🤖","La IA propone","Sugiere una decisión"],["👤","La persona revisa","Aprueba, corrige o rechaza"],["✅","Se ejecuta","Solo lo aprobado avanza"],["📝","Queda registro","Quién decidió y por qué"]],"cap":"En la práctica: la IA propone, una persona aprueba o corrige, solo lo aprobado avanza y todo queda registrado.","narr":"Así se ve en la práctica. La IA propone una decisión. Una persona la revisa: aprueba, corrige o rechaza. Solo lo aprobado avanza. Y todo queda registrado: quién decidió y por qué. Cuanto más pesa una decisión, más cerca debe estar el humano del bucle."},{"type":"pieces","dur":16,"eyeb":"Gestionar el riesgo","h2":"Antes de soltar un sistema, cuatro preguntas","pieces":[["❓","¿Qué falla?","Dónde y cómo puede equivocarse"],["📉","¿A quién afecta?","Qué daño causaría el error"],["🛡️","¿Cómo lo freno?","Qué límite o freno ponemos"],["📢","¿Qué comunico?","Sus capacidades y sus límites"]],"cap":"Antes de soltar un sistema, pregúntate qué puede fallar, a quién afecta, cómo lo frenas y qué comunicas de sus límites.","narr":"Gestionar el riesgo es hacerse cuatro preguntas antes de soltar un sistema. Qué puede fallar y cómo. A quién afecta ese error y qué daño causa. Cómo lo frenas cuando pase. Y qué comunicas de sus capacidades y sus límites. Anticipar el mal uso es parte de tu trabajo."},{"type":"myth","dur":17,"eyeb":"A tener en cuenta","h2":"Tres verdades honestas sobre la IA responsable","myths":[["No es neutral por defecto",", hay que hacerla justa a propósito"],["No basta con que funcione",", debe poder explicarse y revisarse"],["No traslada tu responsabilidad",", si la IA decide, respondes tú"]],"cap":"La IA no es neutral por defecto ni basta con que funcione: debe explicarse. Y no te libra de responsabilidad: si decide, respondes tú.","narr":"Antes de cerrar, tres verdades honestas. La IA no es neutral por defecto: hay que hacerla justa a propósito. No basta con que funcione: debe poder explicarse y revisarse. Y no traslada tu responsabilidad: si tu sistema decide, ante la ley y ante las personas, respondes tú."},{"type":"pieces","dur":15,"eyeb":"Recapitulemos","h2":"IA responsable se sostiene en cuatro columnas","pieces":[["⚖️","Sin sesgo","Trata justo a todos"],["🔍","Transparente","Se sabe que es IA"],["💬","Explicable","Dice por qué decidió"],["👤","Supervisada","Un humano puede revertir"]],"cap":"Recap: la IA responsable se sostiene en cuatro columnas: sin sesgo, transparente, explicable y supervisada por una persona.","narr":"Recapitulemos. La inteligencia artificial responsable se sostiene en cuatro columnas: que trate justo a todos, que sea transparente, que pueda explicar sus decisiones y que una persona pueda supervisarla y revertirla. Reconoce esas cuatro y sabrás si un sistema está bien construido."},{"type":"title","dur":18,"eyeb":"Fin del curso · Felicidades","h2":"Terminaste el camino. Ahora te toca aplicarlo","sub":"Ya tienes las piezas: de tu primer flujo a la IA responsable. Lo que sigue no lo enseña un video: construir con criterio.","cap":"Completaste el curso, del primer flujo a la IA responsable. Felicidades. Ahora sigue lo importante: aplicarlo con criterio.","narr":"Y con esto cierras el curso. Felicidades: recorriste el camino completo, desde tu primer flujo hasta construir inteligencia artificial responsable. Aprendiste a automatizar, y también a hacerlo bien. La IA potencia tu criterio, no lo reemplaza. Ahora te toca lo mejor: aplicar todo esto en tu trabajo real, con las manos y con la cabeza. Gracias por llegar hasta aquí. Nos vemos construyendo."}]};
